/* Generated by tools/editorial/compile_main_story_k.cjs from tools/editorial/main_story_k/*.md. Do not edit by hand. */
(function(root){root.CRPGMainStoryK={"version":1,"chains":[{"id":"ISK_L01_K","entry":"ISK_L01_K_001","items":[{"k":"keep","id":"ISK_L01_K_001","text":"성문 밖의 길은 멀리서 볼 때보다 좁았다. 어깨끈을 당겼다가, 진이 보고 있다는 걸 알고 아무렇지 않은 척 손을 내렸다."},{"k":"line","id":"PRO_L01K_depart_001","speaker":"진","text":"잠깐만요. 가방끈이 뒤집혔어요. 그대로 걸으면 어깨가 쓸립니다.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_002","text":"잠깐. 가방끈이 뒤집혔어. 그대로 걸으면 어깨 쓸려."}},{"k":"line","id":"PRO_L01K_depart_003","speaker":"나","text":"출발도 전에 들켰네요. 사실 알고 있었는데 고치기 귀찮았어요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_004","speaker":"진","text":"솔직한 건 좋은데, 먼 길에서는 그 귀찮음이 제일 비쌉니다. 내려 보세요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_005","text":"솔직한 건 좋은데, 먼 길에선 그 귀찮음이 제일 비싸. 내려 봐."}},{"k":"line","id":"PRO_L01K_depart_006","speaker":"","text":"진은 천을 접어 끈 아래에 받쳐 주었다. 다시 멘 가방은 거짓말처럼 가벼웠다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_007","speaker":"나","text":"와. 단장님, 기사단 그만두시면 가방 가게 하세요. 제가 첫 손님 할게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_008","speaker":"진","text":"그 전에 첫 손님이 리월에 무사히 도착해야겠죠. 편지 주세요. 맛있는 것 얘기는 그다음 줄에 써도 됩니다.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_009","text":"그 전에 첫 손님이 리월에 무사히 도착해야지. 편지 보내. 맛있는 거 얘기는 그다음 줄에 써도 돼."}},{"k":"line","id":"PRO_L01K_depart_010","speaker":"","text":"발길을 떼려다 멈췄다. 죽어 있던 드발린. 그 모습이 아직 눈에 남아 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_011","speaker":"나","text":"단장님. 드발린이 죽어 있었던 거, 기록에 남겨 주세요. 제가 잘못 본 게 아니니까요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_012","speaker":"진","text":"남깁니다. 저도 그 자리에 있었어요. 죽은 것도, 다시 날아오른 것도요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_013","text":"남길게. 나도 그 자리에 있었잖아. 죽은 것도, 다시 날아오른 것도."}},{"k":"line","id":"PRO_L01K_depart_014","speaker":"나","text":"……그 말이면 됐어요. 다녀올게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_015","speaker":"진","text":"필요하면 연락하세요. 몬드에서 겪은 일은 제가 증언합니다. 오늘은 도착해서 쉴 곳부터 찾으시고요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_016","text":"필요하면 연락해. 몬드에서 겪은 일은 내가 증언할게. 오늘은 도착해서 쉴 곳부터 찾고."}},{"k":"line","id":"PRO_L01K_depart_017","speaker":"","text":"진은 손을 들어 배웅한 뒤 성안으로 돌아갔다. 한 번 돌아보고, 두 번째는 참았다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_001","speaker":"","text":"성벽이 손톱만 해질 때까지 걸었다. 걷는 건 여전히 귀찮았다. 그래도 경치가 좋으니 반쯤은 참을 만했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_002","speaker":"","text":"그 반을 다 쓰기도 전에 풀숲이 흔들렸다. 가면 쓴 머리가 셋. 츄츄족이었다. 이 세계는 길에서 쉬는 걸 허락하지 않는 모양이었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_003","speaker":"나","text":"안녕하세요. 지나가는 사람인데요. 돈 없고, 먹을 것도 없고……","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_004","speaker":"","text":"대답은 곤봉이었다.","map":"MAP_MOND_CITY"},{"k":"combat","id":"PRO_L01K_road_005","group":"EG_MOND_HILI_PATROL","text":"길을 막은 츄츄족 순찰대. 리월로 가는 길은 지나가야 열린다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_006","speaker":"","text":"마지막 한 마리가 풀숲으로 달아났다. 숨을 고르며 가방을 고쳐 멨다. 진이 받쳐 준 천은 그 와중에도 제자리에 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_007","speaker":"나","text":"……가방 가게, 진심으로 추천이네.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_L01_K_016","text":"해가 기울 무렵 망서 객잔의 기둥이 보였다. 반가움은 짧았다. 객잔 아래 짐을 올리는 승강기가 한쪽으로 기울어 있었고, 끊어질 듯한 줄 끝에 짐꾼 하나가 매달려 있었다. 두 사람이 그 아래로 달려왔다."},{"k":"line","id":"PRO_L01K_wangshu_001","speaker":"","text":"상자를 치운 자리로 줄이 또 한 뼘 미끄러졌다. 위에서 짐꾼이 숨을 들이켰다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_wangshu_002","options":[{"label":"받침목 여기 있어요! 제가 끼울 테니 자리만 짚어 줘요!","keep":"REV02_K_LIFT_C1","items":[{"k":"line","id":"PRO_L01K_wangshu_003","speaker":"중운","text":"거기! 바퀴 뒤쪽! 더 깊이!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_004","speaker":"","text":"받침목이 들어가자 승강기가 덜컥 멈췄다. 행추가 줄을 당겨 짐꾼을 끌어올렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_005","speaker":"행추","text":"자네, 손이 빠르군. 받침 자리를 한 번에 찍었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_006","speaker":"나","text":"운이야. 두 번째였으면 손 떨려서 못 했어.","map":"MAP_LIYUE_PLAINS"}]},{"label":"줄은 못 버텨요! 이 천 펴요! 거기 두 분, 구경 말고 모서리 좀!","keep":"REV02_K_LIFT_C2","items":[{"k":"line","id":"PRO_L01K_wangshu_007","speaker":"","text":"구경꾼 둘이 얼떨결에 천을 잡았다. 줄이 끊어진 건 그 직후였다. 짐꾼은 천 위로 떨어져 한 바퀴 굴렀고, 나는 그 반동에 엉덩방아를 찧었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_008","speaker":"중운","text":"다친 사람 없지? 없으면 다들 숨 한 번씩!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_009","speaker":"행추","text":"줄이 못 버틴다는 걸 먼저 본 사람은 자네뿐이었네.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_010","speaker":"나","text":"칭찬은 내 허리한테 해 줘. 바닥이 생각보다 딱딱해.","map":"MAP_LIYUE_PLAINS"}]},{"label":"손이 모자라잖아요! 저도 줄 잡을게요! 저까지 딸려가면 잡아 줘요!","keep":"REV02_K_LIFT_C3","items":[{"k":"line","id":"PRO_L01K_wangshu_011","speaker":"","text":"줄을 잡은 순간 발이 바닥에서 떴다. 중운이 내 허리띠를 잡아 끌어내렸고, 그 사이 행추가 짐꾼을 받쳐 올렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_012","speaker":"중운","text":"딸려가면 잡아 달라더니 진짜 딸려가는 사람은 처음 봤다!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_013","speaker":"행추","text":"그래도 줄이 멈췄네. 자네 몸무게가 받침목 몫을 했어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_014","speaker":"나","text":"그 말 칭찬 맞지? 일단 받아 둘게. 다음엔 받침목 들게.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_wangshu_015","speaker":"","text":"짐꾼은 땅에 내려서자마자 쭈그려 앉아 허리를 두드렸다. 한참 뒤에야 우리 쪽을 올려다봤다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_016","speaker":"짐꾼","text":"사람 셋이 달라붙어서 간신히 내린 게 이 몸뚱이 하나라니. 짐은 떨어졌소?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_017","speaker":"중운","text":"짐보다 아저씨가 먼저죠!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_018","speaker":"짐꾼","text":"짐이 떨어지면 내 품삯이 떨어지는 거라오. 어쨌든…… 고맙소. 셋 다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_019","speaker":"","text":"'셋'이라고 셀 때 내 쪽도 한 번 보았다. 묘하게 뿌듯했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_020","speaker":"행추","text":"우리는 객잔에 짐을 올려 두고 바로 떠나야 하네. 자네는?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_021","speaker":"나","text":"오늘은 여기서 자. 내일 리월항으로 가고. 가서 할 일이 있어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_022","speaker":"행추","text":"그럼 항구 근처에서 다시 보겠군. 요즘 그쪽이 조금 시끄러워서 말이야. 중운, 가자.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_023","speaker":"중운","text":"아까 그 책, 먼저 주워 두라고 했잖아!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_024","speaker":"","text":"두 사람이 멀어진 뒤에도 승강기 줄은 바람에 흔들렸다. 그때 등 뒤에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_025","speaker":"소","text":"움직이지 마.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_026","speaker":"","text":"돌아보자 지붕 위에 창을 든 사람이 서 있었다. 가면은 없었지만 눈빛만으로 알 수 있었다. 소. 이 객잔을 지키는 선인.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_027","speaker":"소","text":"네 주변에서 낯선 냄새가 난다. 죽음과 생명의 냄새가 함께. 사람 하나에게서 나기엔 이상한 조합이지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_028","speaker":"나","text":"……저 오늘 씻긴 했는데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_029","speaker":"소","text":"농담할 상대를 잘못 골랐다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_030","speaker":"나","text":"죄송합니다. 무서우면 입이 먼저 나가서요. 제가 뭘 한 건 아니에요. 적어도 제가 아는 한은요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_031","speaker":"소","text":"그렇게 보인다. 네가 남을 해쳤다는 징후는 없어. 하지만 마신을 미워하는 기척이 네 곁을 스쳤다. 네 것인지, 네가 지나온 곳의 것인지는 모른다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_032","speaker":"나","text":"그럼 저는 어떡해야 합니까?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_033","speaker":"소","text":"이상을 느끼면 모르는 척하지 마. 그 정도다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_034","speaker":"","text":"다음 질문을 꺼내기 전에 지붕 위는 비어 있었다. 바람 소리만 남았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_001","speaker":"","text":"객잔 종업원이 방 열쇠와 함께 따뜻한 물을 내줬다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_002","speaker":"객잔 종업원","text":"승강기 일은 들었어요. 오늘은 그냥 쉬세요. 지붕 위 그분 말씀, 무서워도 틀린 적은 없거든요. 그러니까 더 쉬셔야 하고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_003","speaker":"나","text":"그분이 말 거는 거, 흔한 일은 아니죠?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_004","speaker":"객잔 종업원","text":"저는 여기 삼 년째인데 처음 봐요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_005","speaker":"나","text":"……그 말은 안 해 주셔도 됐는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_006","speaker":"","text":"누워도 죽음과 생명의 냄새라는 말이 천장에 붙어 있었다. 드발린의 식은 몸, 다시 날아오르던 모습. 잠은 늦게 왔다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_064","text":"아침 길에 어제의 짐꾼을 다시 만났다. 어제 떨어질 뻔한 포대를 등에 얹고 있었다. 돕겠다고 손을 뻗자 먼저 내 신발부터 내려다봤다."},{"k":"line","id":"PRO_L01K_wangshu_night_007","speaker":"짐꾼","text":"그 신발로 내 짐까지 들면 리월에는 발바닥만 도착하겠네. 옆에서 길이나 봐 주시오. 수레 오면 소리 지르고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_008","speaker":"나","text":"그 정도는 자신 있어요. 소리 지르는 건 제 특기거든요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_009","speaker":"짐꾼","text":"어제 봤소. 리월항까지 가지? 같이 가지. 혼자 걷는 길은 길어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_010","speaker":"","text":"그렇게 동행이 생겼다. 그는 이름을 말하지 않았고, 나도 묻지 않았다. 아직은 짐꾼과 손님으로 충분했다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_069","text":"귀리 평원으로 접어들자 오래된 돌무더기가 길 양쪽에 늘어났다. 폐허는 오래 보지 않았다. 드발린이 떨어졌을 때의 울림이 이런 돌벽에서 쉽게 떠올랐다."},{"k":"line","id":"PRO_L01K_guili_001","speaker":"짐꾼","text":"자네, 어제 지붕 위 그분하고 말했지? 뭐라던가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_002","speaker":"나","text":"제 주변에 이상한 게 있다고요. 뭔지는 자기도 모른다고 했어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_003","speaker":"짐꾼","text":"그러면 모르는 거지. 선인이 모르는 걸 자네가 밤새 고민해서 알겠소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_004","speaker":"나","text":"아저씨, 그거 지금 제가 들은 말 중에 제일 위로가 되는 말이에요. 조금 슬프네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_005","speaker":"짐꾼","text":"위로하려고 한 말은 아니오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_006","speaker":"","text":"앞줄이 멈출 때마다 그는 포대를 내려놓고, 나는 앞을 보러 갔다. 짐은 그가, 길은 내가 살폈다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_007","speaker":"","text":"세 번째로 앞을 보러 갔을 때, 폐허 그늘에서 사람 셋이 나왔다. 짐꾼들의 수레를 노리는 눈이었다. 보물 사냥단. 이름만 거창하고 하는 짓은 날강도였다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_008","speaker":"보물 사냥단","text":"짐은 두고 가. 다치고 싶지 않으면.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_009","speaker":"나","text":"저 짐 아니에요. 저는 그냥 길 보는 사람인데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_010","speaker":"보물 사냥단","text":"그럼 넌 길 보다가 다치는 거지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_011","speaker":"나","text":"아, 그렇게 되는 거구나.","map":"MAP_LIYUE_PLAINS"},{"k":"combat","id":"PRO_L01K_guili_012","group":"EG_TREASURE_PATROL","text":"귀리 평원의 보물 사냥단 습격조. 짐꾼의 수레를 지켜야 한다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_013","speaker":"","text":"사냥단이 폐허 너머로 흩어졌다. 돌아보니 짐꾼은 포대 위에 앉아 구경하고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_014","speaker":"짐꾼","text":"길 봐 달라고 했더니 길을 아주 깨끗하게 치워 놓는구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_015","speaker":"나","text":"손뼉이라도 쳐 주세요. 품삯은 안 받을 테니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_016","speaker":"짐꾼","text":"품삯은 내가 못 받고 있소.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_075","text":"리월항 입구는 수레와 사람으로 막혀 있었다. 차단선 옆에서 보라색 머리의 여자가 직접 포대를 옮기고 있었다. 각청. 칠성이 여기서 짐을 나르고 있을 줄은 몰랐다. 눈이 마주쳤다."},{"k":"line","id":"PRO_L01K_blockade_001","speaker":"각청","text":"구경할 힘은 남았나 보네. 그 줄 좀 잡아 줘. 이야기는 사람들이 그늘로 옮겨 간 다음에.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_002","speaker":"나","text":"저 방금 도착했는데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_003","speaker":"각청","text":"그래서 힘이 남았잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_004","speaker":"","text":"반박할 말이 없었다. 그늘막 줄을 잡고 한 시간이 지났다. 각청은 접수대 위에 두 장의 표를 나란히 놓았다. 같은 짐인데, 아래 붙은 설명이 서로 달랐다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_005","speaker":"각청","text":"이건 물건을 넘겼다는 확인서. 이쪽은 같은 짐을 받지 못했다는 신고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_006","speaker":"나","text":"같은 짐인데요? 그럼 누가 거짓말을……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_007","speaker":"각청","text":"몰라. 기억이 끊긴 사람도 있거든. 검사했다는 표식은 있는데 검사한 기억이 없대.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_008","speaker":"나","text":"……그건 무섭네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_009","speaker":"각청","text":"무서워. 그래서 아무도 못 들여보내고 있는 거야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_010","speaker":"","text":"각청은 뒤쪽 수레가 밀려오지 않도록 손을 들었다. 기다리라는 말을 들은 수레는 짐꾼의 것이었다. 그 옆의 병사는 아까부터 표찰만 들여다보고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_011","speaker":"나","text":"저 병사, 아까부터 표만 보고 있는데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_012","speaker":"각청","text":"봤어. 내가 물어볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_013","speaker":"","text":"각청은 병사에게 표를 받아 글씨가 보이도록 돌려 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_014","speaker":"각청","text":"어디까지 확인했어? 마지막으로 본 짐을 짚어 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_015","speaker":"천암군 병사","text":"그게…… 잠시만요. 다시 보면 알 수 있을 것 같습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_016","speaker":"","text":"병사의 손가락이 같은 줄을 몇 번이나 오갔다. 각청은 재촉하지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_017","speaker":"천암군 병사","text":"죄송합니다. 한 번만 더……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_018","speaker":"각청","text":"사과부터 할 필요 없어. 교대하고 물 좀 마셔. 이 표는 내가 볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_019","speaker":"","text":"병사가 자리를 뜨자 각청은 표를 접수대 한쪽에 따로 놓았다. 서류 밑에 들어가지 않도록 모서리를 밖으로 빼 두었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_020","speaker":"나","text":"못 떠올리는 사람만 잘못한 것 같아지네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_021","speaker":"각청","text":"그래서 내가 여기 있는 거야. 사람 하나 쥐어짜서 끝낼 거면 칠성이 짐 나를 필요 없지.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_105","text":"접수대 뒤 공고를 다시 보았다. 송신의례. 내가 아는 이야기에서 이 시기에 열리는 것은 청신의례였다. 글자 하나가 다른데, 그 하나가 어떤 뜻인지는 알 수 없었다. 그때 봉쇄선 밖에서 아는 목소리가 들렸다."},{"k":"line","id":"PRO_L01K_desk_001","speaker":"","text":"돌아오자 각청이 접수대 한쪽을 비워 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_002","speaker":"각청","text":"더 알릴 일 있어? 직접 본 거든 들은 거든.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_desk_003","options":[{"label":"확실하지 않은 얘기도 해도 돼요?","id":"PRO_L01K_desk_004","items":[{"k":"line","id":"PRO_L01K_desk_005","speaker":"각청","text":"확실하지 않다고 말하면 돼. 판단은 내가 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_006","speaker":"나","text":"그럼, 좀 이상하게 들려도 끝까지 들어 주세요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_007","speaker":"각청","text":"오늘 들은 이상한 얘기 중에 네 게 제일 이상할 것 같진 않아. 해 봐.","map":"MAP_LIYUE_PLAINS"}]},{"label":"잠깐만요. 어디서부터 말해야 할지……","id":"PRO_L01K_desk_008","items":[{"k":"line","id":"PRO_L01K_desk_009","speaker":"각청","text":"급하게 맞추지 마. 생각나는 것부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_010","speaker":"","text":"각청은 펜을 내려놓고 뒤에 선 사람을 옆 접수대로 보냈다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_011","speaker":"나","text":"……네. 잠깐만요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_desk_012","speaker":"","text":"입을 열려다 어젯밤의 경고가 떠올랐다. 내 주위에서 죽음의 냄새가 난다는 말. 옆에서는 짐꾼이 같은 포대의 끈을 다시 풀고 있었다. 교대한 병사가 또 그 포대를 세고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_001","options":[{"label":"제 얘기부터 할게요. 어젯밤 소에게 경고를 들었어요.","keep":"ISK_L01_K_1_CHOOSE","items":[{"k":"line","id":"PRO_L01K_fork_002","speaker":"","text":"소의 이름에 각청이 고개를 들었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_003","speaker":"각청","text":"호법야차님이? 너한테 직접?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_004","speaker":"나","text":"망서 객잔 지붕에서요. 제 주위에…… 죽음과 생명의 냄새가 같이 난댔어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_005","speaker":"각청","text":"……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_006","speaker":"각청","text":"너 대체 뭘 하고 다닌 거야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_007","speaker":"나","text":"가방끈 고치고, 승강기 받치고, 걸었어요. 그게 다예요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_008","speaker":"","text":"각청은 줄 선 사람들을 돌아본 뒤 접수대 옆으로 자리를 옮겼다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_009","speaker":"각청","text":"이쪽에서 하자. 그분이 네 몸에서 난다고 하셨어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_010","speaker":"나","text":"모르겠대요. 마신을 미워하는 기척도 있다는데, 전 마신한테 감정 없어요. 만난 적도 없고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_011","speaker":"각청","text":"알았어. 그 말만으로 널 어떻게 할 생각은 없어. 그렇다고 그냥 넘길 수도 없고.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_012","options":[{"label":"저도…… 저 병사처럼 될까요?","id":"PRO_L01K_fork_013","items":[{"k":"line","id":"PRO_L01K_fork_014","speaker":"각청","text":"아직 그렇게 볼 근거는 없어. 오늘 온 길은 기억나?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_015","speaker":"나","text":"네. 다만 어젯밤에…… 잠을 거의 못 잤어요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"말 안 하면 더 불안할 것 같았어요.","id":"PRO_L01K_fork_016","items":[{"k":"line","id":"PRO_L01K_fork_017","speaker":"각청","text":"잘 말했어. 몸은? 빠진 기억이나 이상한 데는?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_018","speaker":"나","text":"몸은 괜찮아요. 잠을 좀 설쳤어요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_019","speaker":"각청","text":"잠 설친 건 그렇게 적을게. 다른 걸로 바꿔 적진 않아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_020","speaker":"","text":"각청은 들은 경고와 지금 대답을 따로 적고, 종이를 이쪽으로 돌려 빠진 말이 없는지 짚어 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_021","speaker":"나","text":"이상한 사람 취급할 줄 알았는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_022","speaker":"각청","text":"불안해서 찾아온 사람한테 겁 더 줘서 뭐 해. 넌 지금 손 떨고 있어. 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_023","speaker":"나","text":"……몰랐어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_024","speaker":"","text":"그때 차단선 쪽에서 쇠 부딪히는 소리가 났다. 교대한 병사가 수레를 통과시키려 차단봉을 올리고 있었다. 봉 아래에는 아직 짐꾼이 포대를 묶고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_025","options":[{"label":"잠깐만요! 아래에 아직 사람 있어요! 통과 취소!","keep":"REV02_K1_REPEAT_C1","items":[{"k":"line","id":"PRO_L01K_fork_026","speaker":"","text":"수레가 멈췄다. 병사는 봉을 올린 자기 손을 내려다보더니, 왜 올렸는지 모르겠다는 얼굴로 굳었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_027","speaker":"각청","text":"봉 내려. 천천히. 그대로 두고 물러서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_028","speaker":"짐꾼","text":"……자네 목소리 큰 줄은 알았지만 이 정도일 줄은. 덕분에 머리가 붙어 있소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_029","speaker":"나","text":"특기라고 했잖아요. 목은 좀 아프네요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"방금 하신 것부터 같이 봐요. 수레가 지나가기 전에 봉을 올리셨어요. 지금 손부터 빼요.","keep":"REV02_K1_REPEAT_C2","items":[{"k":"line","id":"PRO_L01K_fork_030","speaker":"","text":"병사는 내 말을 듣고서야 자기 손을 보았다. 봉이 내려왔고, 수레는 그 앞에 섰다. 짐꾼은 그제야 머리 위에 무엇이 있었는지 알았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_031","speaker":"각청","text":"봉이 먼저야, 수레가 먼저야?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_032","speaker":"나","text":"봉이요. 통과하라는 말은 없었어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_033","speaker":"각청","text":"적을게. 네가 본 순서대로.","map":"MAP_LIYUE_PLAINS"}]},{"label":"이거부터 올리면 되잖아! 잠깐, 왜 더 내려가…… 각청, 나 이거 잘못 잡았어!","keep":"REV02_K1_REPEAT_C3","items":[{"k":"line","id":"PRO_L01K_fork_034","speaker":"","text":"봉을 붙잡았는데 반대쪽이 올라갔다. 각청이 뛰어와 내 손 위에 손을 얹었다. 봉이 제자리에 멈췄다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_035","speaker":"각청","text":"손 떼지 말고 그대로. 됐어. 이제 떼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_036","speaker":"짐꾼","text":"구해 주려던 건 알겠는데, 다음엔 소리만 지르시오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_037","speaker":"나","text":"……네. 손이 먼저 나갔어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_038","speaker":"각청","text":"손이 먼저 나가는 건 좋은데 방향은 좀 보고 나가.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_039","speaker":"","text":"병사는 자기가 봉을 올렸다는 사실을 끝까지 떠올리지 못했다. 짧은 빈틈. 각청이 말한 것이 이거였다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_120","text":"각청은 범인을 묻지 않았다. 대신 어느 대목에 다른 사람이 함께 있었는지 물었다. 소의 경고, 그리고 방금 본 일. 내 이름 옆에 두 줄이 적혔다."},{"k":"line","id":"PRO_L01K_fork_040","speaker":"각청","text":"네 자리는 저쪽 그늘이야. 바깥쪽 별도 대기 자리. 어디 갈 땐 옆 병사한테 방향만 알려 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_041","speaker":"나","text":"물 마시러 가는 것도요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_042","speaker":"각청","text":"그건 그냥 가. 그런 것까지 허락받으면 너부터 이상해져.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_043","speaker":"각청","text":"다음 교대 때 같은 질문 또 할 거야. 그전에 몸이 이상하면 먼저 말해. 해 지도록 혼자 두진 않을게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_044","speaker":"","text":"각청은 자리를 뜨기 전에 물을 놓아 주었다. 붙잡혔다고 하기에는 친절했고, 안심하기에는 모르는 것이 너무 많았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_1_END","text":"리월항 밖 별도 대기 자리. 각청에게 소의 경고와 드발린의 죽음·부활을 보았다는 사실을 알렸다. 통행은 닫혀 있고, 옥경대로 가는 별도 길은 안내만 받았다."}]},{"label":"저 포대부터 봐 주세요. 아까 풀려 있던 끈을 봤어요.","keep":"ISK_L01_K_2_CHOOSE","items":[{"k":"line","id":"PRO_L01K_fork_045","speaker":"각청","text":"어느 포대? 건드리지 말고, 본 자리부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_046","speaker":"","text":"색이 다른 끈을 가리키자 각청이 수레 앞에 멈췄다. 짐꾼이 접힌 표를 내밀었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_047","speaker":"짐꾼","text":"아까 여기서 풀고 다시 묶었습니다. 또 풀라니…… 이 포대만 몇 번째인지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_048","speaker":"천암군 병사","text":"표시는 있습니다. 하지만 제가 안을 본 기억이 없어서……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_049","speaker":"나","text":"끈이 바닥에 풀린 건 봤어요. 밟을 뻔했거든요. 안쪽까지 본 건 아니고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_050","speaker":"각청","text":"그 정도면 됐어. 끈 풀린 거랑 검사 끝난 건 따로 볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_051","options":[{"label":"제가 서 있던 곳에서 보여 드릴까요?","id":"PRO_L01K_fork_052","items":[{"k":"line","id":"PRO_L01K_fork_053","speaker":"각청","text":"좋아. 넌 그대로 서 있어. 내가 움직일게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_054","speaker":"","text":"각청이 수레 옆으로 돌아서자, 아까 발을 피했던 자리를 가리켰다.","map":"MAP_LIYUE_PLAINS"}]},{"label":"포대는 그대로 두고, 표부터 같이 봐요.","id":"PRO_L01K_fork_055","items":[{"k":"line","id":"PRO_L01K_fork_056","speaker":"각청","text":"그러자. 또 풀면 남은 흔적도 바뀌니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_057","speaker":"","text":"각청이 표를 펼쳤다. 짐꾼은 풀려던 끈에서 손을 뗐다.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_058","speaker":"각청","text":"다음 짐은 잠깐 세워 줘. 옆 수레 것하고 섞이면 다시 봐야 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_059","speaker":"천암군 병사","text":"예. 수레를 비켜 두겠습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_060","speaker":"","text":"병사가 수레를 비키려 손잡이를 잡았다. 그 순간 수레가 비탈 쪽으로 미끄러졌다. 짐꾼의 손은 아직 포대 끈 사이에 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_061","options":[{"label":"짧은 손잡이부터 잠글게요. 쐐기는 그다음! 아저씨 손 들어가 있으면 수레 움직이지 마요!","keep":"REV02_K2_BRAKE_C1","items":[{"k":"line","id":"PRO_L01K_fork_062","speaker":"","text":"손잡이 옆 쇠고리를 당기자 바퀴가 잠겼다. 수레는 반 바퀴 돌고 멈췄다. 쐐기는 각청이 발로 밀어 넣었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_063","speaker":"짐꾼","text":"……어제는 사람 받침목, 오늘은 수레 받침목이구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_064","speaker":"각청","text":"잠그는 법은 어디서 배웠어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_065","speaker":"나","text":"어제 객잔 승강기에서요. 한 번 보면 잊기 어렵더라고요. 제 허리가 기억해요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"설명은 들었는데 제가 하면 하나는 틀릴 것 같아요. 직접 잠가 주세요. 저는 받침 가져올게요!","keep":"REV02_K2_BRAKE_C2","items":[{"k":"line","id":"PRO_L01K_fork_066","speaker":"","text":"각청이 두 걸음에 수레를 잡고 손잡이를 잠갔다. 내가 받침을 끌어와 바퀴 앞에 끼울 때쯤 수레는 이미 멈춰 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_067","speaker":"각청","text":"모르는 걸 모른다고 하는 건 빠르네. 받침은 잘 끼웠어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_068","speaker":"짐꾼","text":"둘이 그렇게 척척 맞으면 내 손은 어디다 쓰나.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_069","speaker":"나","text":"아저씨 손은 포대 끈에서 빼는 데 쓰세요. 아직 안 뺐잖아요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"긴 줄을 느슨하게 하면 빠지지 않을까? ……아니네, 이거 풀면 전부 쏟아지네!","keep":"REV02_K2_BRAKE_C3","items":[{"k":"line","id":"PRO_L01K_fork_070","speaker":"","text":"줄을 잡은 손을 급히 멈췄다. 그 사이 각청이 손잡이를 잠갔다. 포대 하나가 기울었지만 떨어지진 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_071","speaker":"각청","text":"손 멈춘 게 잘한 거야. 그 줄은 짐 전체를 묶는 줄이었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_072","speaker":"나","text":"……하나 더 풀었으면 큰일 났겠네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_073","speaker":"짐꾼","text":"큰일은 내 허리가 났겠지. 그래도 멈춘 사람은 자네니까 됐소.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_074","speaker":"","text":"짐꾼이 끈 사이에서 손을 빼고 길게 숨을 내쉬었다. 각청은 포대를 봉하고 운송 기록을 따로 챙겼다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_153","text":"세 사람은 서로 다른 자리에서 같은 포대를 보았다. 병사의 기억이 돌아온 것은 아니었다. 그래도 새로 움직인 물건이 없다는 사실만은 그 자리에서 함께 확인할 수 있었다."},{"k":"line","id":"PRO_L01K_fork_075","speaker":"각청","text":"네 증언은 네가 본 것만 적었어. 더 넓히지도, 줄이지도 않았어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_076","speaker":"나","text":"그 정도면 충분해요. 저도 본 것만 말했으니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_077","speaker":"짐꾼","text":"이 포대는 당분간 못 들어가겠지. 나도, 자네도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_078","speaker":"각청","text":"물자 대기 구역에 자리를 마련할게요. 품삯 문제는 제가 확인하겠습니다. 두 번 일했다는 말로 끝나게 두지는 않을게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_079","speaker":"","text":"각청이 짐꾼에게는 말을 높였다. 짐꾼은 처음으로 허리가 아닌 다른 이유로 고개를 숙였다. 어젯밤의 경고는 아직 말하지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_2_END","text":"리월항 밖 물자 대기 줄. 직접 본 인계의 흔적만 각청에게 증언하고 확인을 기다린다. 소의 경고는 아직 말하지 않았다. 항구는 봉쇄 상태다."}]}]}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_2","text":"나도 뭐든 할게! 도착하자마자 사람 떨어지는 거 구경할 생각은 없어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_3","text":"그럼 아래를 맡아 줘. 난 행추, 저 친구는 중운. 소개가 좀 흔들리는군!"},{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_4","text":"둘은 익숙하게 자리를 나눴다. 나는 팽팽한 줄을 피해 승강기 아래로 들어갔다. 받침목을 끼울 자리에 부서진 상자가 박혀 있었다."},{"k":"text","id":"V141_AFTER_ISK_L01_K_016_3","text":"소개 잘 들었어. 둘이 평소에도 이래? 대답은 저분 내려온 다음에!"},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_0","text":"잠깐. 본인이 검사했다는 표식은 있는데, 검사한 기억은 없다? 내가 잘못 들었으면 지금 끊어 줘."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_1","text":"어제 그 친구군! 하루 만에 다시 보다니. 저 짐꾼 아저씨도. 사라진 기억과 남겨진 화물이라…… 흥미로운 사건이네."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_2","text":"책 제목은 사건 끝난 뒤에 지어. 지금 저 병사는 잘못한 게 없어도 일자리를 잃을 수 있고, 저 아저씨는 품삯을 못 받아."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_3","text":"……그건 내가 가벼웠네. 비운 상회 쪽 인계 장소는 내가 안내할 수 있어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_4","text":"행추, 어제는 고마웠어. 이쪽은…… 연비 맞지? 이름은 들어 봤어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_5","text":"응, 법률 자문. 지금은 비용보다 현장이 사라지는 게 급해. 저 짐이 어디서 인계됐는지, 귀리 평원의 짐터부터 같이 보자."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_0","text":"증거를 모으면 단번에 풀릴 줄 알았는데, 물어볼 사람이 늘었군."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_1","text":"그래서 결말을 먼저 쓰면 안 된다는 거야. 이건 내가 맡아 둘게. 넌 아까 그 병사한테 해고된 거 아니라고 전해 줘."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_2","text":"그 말은 내가 할게. 기다리는 입장이 얼마나 피곤한지 조금 알 것 같아서."}]},{"id":"ISK_L02_K1","entry":"ISK_L02_K1_001","items":[{"k":"keep","id":"ISK_L02_K1_001","text":"별도로 마련된 대기 자리는 생각보다 사람들의 왕래와 가까웠다. 소에게 들은 말을 각청에게 전한 뒤부터, 나는 남이 아니라 내 몸에서 먼저 이상을 찾게 되었다. 그 아침, 공고를 든 채 멍하니 앉아 있는 나에게 누군가 다가왔다."},{"k":"line","id":"PRO_L02K1_wait_001","speaker":"","text":"첫날 오후, 각청이 돌아왔을 때 나는 두 손가락을 손목 안쪽에 대고 있었다. 처음엔 맥박을 재려던 거였는데, 어느새 뛰고 있다는 걸 계속 확인해야만 손을 뗄 수 있었다. 각청은 그 손을 먼저 보았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_1","text":"어제 소리쳐 사람들을 멈춰 세운 뒤로 목이 조금 쉬었다. 적어도 그때 내가 외쳤다는 건 기억했다. 손목에서 확인하려는 건 그보다 단순한 사실이었다."},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_2","text":"어제 병사에게 손을 빼라고 말해 준 일이 떠올랐다. 이제는 내 손목을 놓아도 된다고 누가 말해 줬으면 했다. 남의 불안을 짚어 주는 건 내 손을 멈추는 것보다 쉬웠다."},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_3","text":"어제 각청이 잘못 잡은 봉에서 내 손을 떼어 놓던 순간이 떠올랐다. 위험한 건 내 몸 안에서만 벌어지는 일이 아니었다."},{"k":"line","id":"PRO_L02K1_wait_002","speaker":"각청","text":"손목 왜 그래. 어디 아파?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_003","speaker":"나","text":"아뇨. 뛰고 있나 확인 중이에요. 자기 맥박한테 출석 부르는 중이라고 할까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_004","speaker":"각청","text":"……출석은 잘 나오고?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_005","speaker":"나","text":"아직 결석은 없어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_006","speaker":"각청","text":"그럼 그만 봐. 그 선인이 말한 건 네 주변 기척이지, 네가 죽었다는 판정이 아니야. 멀쩡한 사람이 자기 손목이나 보고 있으면 내가 더 불안해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_007","speaker":"나","text":"머리로는 알아요. 그런데 옆 사람이 뭘 잊기라도 하면, 내가 너무 가까이 앉았나부터 생각하게 돼요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_008","speaker":"각청","text":"그래서 네가 오기 전 일하고 온 다음 일을 따로 보고 있는 거야. 네가 지나간 자리만 모으면 네가 범인이라는 얘기밖에 안 나와. 그건 조사가 아니라 핑계 찾기지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_009","speaker":"","text":"각청은 천막의 접힌 부분을 올려 바깥길이 보이게 했다. 밖이 보이자 숨겨진 사람처럼 앉아 있을 필요가 없어졌다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_wait_010","options":[{"label":"하루 종일 앉아 있으면 없는 증상도 만들어 낼 것 같아요. 좀 걸어도 돼요?","id":"PRO_L02K1_wait_011","items":[{"k":"line","id":"PRO_L02K1_wait_012","speaker":"각청","text":"걸어. 어디 가는지만 알려 주고. 널 가둬 두려고 만든 자리 아니야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_013","speaker":"나","text":"갇힌 게 아니라는 말이 듣고 싶었나 봐요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_014","speaker":"각청","text":"갇혔으면 천막 물이나 빼게 뒀겠어?","map":"MAP_LIYUE_PLAINS"}]},{"label":"확인할 때마다 저한테도 결과 알려 주세요. 뭘 적는지 모르고 앉아 있으면 괜찮다는 말도 무섭거든요.","id":"PRO_L02K1_wait_015","items":[{"k":"line","id":"PRO_L02K1_wait_016","speaker":"각청","text":"그건 당연히 해. 네 얘기는 네 앞에서 정리할게. 다른 병사 사정까지 다 보여 줄 순 없지만.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_017","speaker":"나","text":"그거면 돼요. 고마워요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_rain_001","speaker":"","text":"둘째 날에는 비가 들이쳤다. 내 자리 천막 끝으로 물이 몰리자, 각청이 직접 받침을 옮겨 천을 들어 올렸다. 손을 보태려 일어서자 그녀가 손가락부터 가리켰다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_002","speaker":"각청","text":"줄 당기는 사람하고 받침 미는 사람을 나눠. 둘이 같이 힘주면 기둥만 넘어가.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_rain_003","options":[{"label":"리월 칠성하고 천막 물 빼는 중이네요. 나중에 누가 대접 잘 받았냐고 물으면 뭐라고 하죠?","id":"PRO_L02K1_rain_004","items":[{"k":"line","id":"PRO_L02K1_rain_005","speaker":"각청","text":"따뜻한 데 앉혀 주려다 물길을 잘못 잡았다고 해. 왼쪽 조금만 더. 그렇게 세게 잡으면 천 찢어져!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_006","speaker":"나","text":"제가 도움받는 쪽인지 작업 지시받는 쪽인지 잠깐 헷갈렸어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_007","speaker":"각청","text":"둘 다야. 항의는 손에 걸린 거 빼고 해.","map":"MAP_LIYUE_PLAINS"}]},{"label":"왼쪽을 조금씩 당길게요. 어디까지인지는 보는 쪽에서 말해 줘요.","id":"PRO_L02K1_rain_008","items":[{"k":"line","id":"PRO_L02K1_rain_009","speaker":"각청","text":"그 속도가 낫겠어. 세게 당긴다고 물이 빨리 빠지는 게 아니니까. 거기. 멈춰.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_010","speaker":"나","text":"리월 칠성이 천막 물 빼는 걸 직접 가르쳐 주는 날이 올 줄은 몰랐어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_011","speaker":"각청","text":"나도 네가 이렇게 말 잘 듣는 사람일 줄은 몰랐어.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_rain_012","speaker":"","text":"물이 한꺼번에 빠지며 두 사람의 신발을 적셨다. 각청의 신발까지 젖은 걸 보고 참던 웃음이 터졌다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_013","speaker":"각청","text":"뭐가 웃겨.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_014","speaker":"나","text":"아뇨. 아무것도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_015","speaker":"각청","text":"……내 신발이지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_016","speaker":"나","text":"네.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_017","speaker":"","text":"각청은 더 묻지 않고 마른 자리를 발끝으로 확인한 뒤 의자를 그쪽으로 옮겼다. 그날 저녁부터, 나를 실험대 위의 물건처럼 상상하는 횟수가 조금 줄었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_001","speaker":"","text":"셋째 날과 넷째 날에도 병사들의 기억 이상은 풀리지 않았다. 나와 멀리 떨어진 자리에서도 보고가 들어왔고, 내 곁에서 이야기한 사람이 그 대화를 기억하고 돌아오기도 했다. 내가 무관하다고 확정할 수는 없었다. 다만 내가 입을 열면 누군가 반드시 잊는다는 두려움에는 맞지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_002","speaker":"각청","text":"네가 설산에서 봤다는 구슬, 지금 안 갖고 있는 거지? 의심해서 묻는 거 아니야. 가진 사람하고 본 사람은 따로 적어야 해서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_003","speaker":"나","text":"없어요. 제 짐 다 뒤져도 안 나와요. 나오는 건 빨랫감뿐이에요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_004","speaker":"각청","text":"그럼 본 사람으로만 적을게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_005","speaker":"나","text":"의례 때는 저도 올라갈 수 있는 거죠? 여기까지 와서 지붕만 보다 돌아가면 너무 억울한데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_006","speaker":"각청","text":"행사 통로는 열어. 옥경대 올라갔다가 같은 길로 내려오는 거야. 네가 대기 자리에 있다고 참관을 막진 않아. 대신 거기서 아무나 붙잡고 얘기할 수 있다는 뜻은 아니야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_007","speaker":"나","text":"아무나 안 붙잡을게요. 한 명만 붙잡을 거예요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_008","speaker":"각청","text":"그 한 명이 누군지 벌써 불안하네.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_009","speaker":"","text":"내가 기억하는 이야기에서는 신이 하늘에서 떨어지고, 그 뒤는 살아 있는 신의 계획으로 이어졌다. 공고의 송신의례라는 이름은 여전히 기억과 맞지 않았다. 드발린의 죽음 뒤로 나는 순서를 확신할 수 없었다. 그래도 미리 안다고 믿는 부분이 하나 있다는 사실에 자꾸 기대고 싶었다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_029","text":"닷새가 지난 아침, 천막 사이로 사람들의 발걸음이 일찍부터 이어졌다. 내 자리의 천을 정리하고 나섰다. 돌아오면 다시 그 자리에 앉을 것이라는 생각이 아주 자연스러웠다."},{"k":"keep","id":"ISK_L02_K1_030","text":"옥경대로 향하는 길 앞에서 안내 병사가 사람들을 나누어 보냈다. 길목 옆의 거리는 여전히 막혀 있었다. 내게 허용된 것은 도시 입장이 아니라 의례 참관이었다."},{"k":"line","id":"PRO_L02K1_rite_001","speaker":"안내 병사","text":"올라갈 때는 오른쪽, 내려올 때는 맞은편 줄입니다. 길을 벗어나시면 다시 바깥으로 안내합니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rite_002","speaker":"나","text":"네. 이 길로만 올라갔다가 이 길로만 내려올게요. 저 길 잘 외워요.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_033","text":"줄을 따라 올라가는 동안 항구의 소리는 가까워졌다가 벽 뒤로 멀어졌다. 나들이처럼 옷깃을 정리하는 사람도 있었고, 기억을 잃은 병사들의 이야기를 낮은 목소리로 주고받는 사람도 있었다."},{"k":"line","id":"PRO_L02K1_rite_003","speaker":"","text":"옥경대에 도착하자 가장 먼저 내려가는 길의 위치를 확인했다. 도망칠 생각이라기보다, 모르는 군중 속에 들어왔을 때 몸이 먼저 하는 일이었다. 각청은 통로가 꺾이는 곳에서 병사에게 지시하고 있었다. 눈이 마주치자 짧게 고개를 끄덕였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_004","speaker":"각청","text":"올라오는 데 문제없었어?","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K1_rite_005","options":[{"label":"오늘은 제 몸 말고 의례 쪽 봐요. 저도 가끔은 구경 온 사람처럼 서 있고 싶어요.","id":"PRO_L02K1_rite_006","items":[{"k":"line","id":"PRO_L02K1_rite_007","speaker":"각청","text":"좋아. 줄이 움직이면 가운데로 밀리지 말고 이쪽 가장자리로 와.","map":"MAP_LIYUE_HARBOR"}]},{"label":"괜찮아요. 이상해지면 묻기 전에 제가 먼저 말할게요.","id":"PRO_L02K1_rite_008","items":[{"k":"line","id":"PRO_L02K1_rite_009","speaker":"각청","text":"그래 주면 나도 다른 쪽을 볼 수 있지. 줄이 움직이면 이쪽 가장자리로 와.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L02_K1_038","text":"의례가 시작되었다. 시선들이 한꺼번에 높은 곳으로 향했다. 나도 고개를 들었다가, 하늘을 가르며 내려오는 거대한 몸을 보았다. 예상하고 있었다는 말은 충돌음 앞에서 아무 쓸모가 없었다. 모락스의 시신이 의례 한복판에 떨어져 있었다."},{"k":"line","id":"PRO_L02K1_rite_010","speaker":"","text":"질문들이 한꺼번에 터졌다. 원작을 떠올리려 했지만 눈앞의 먼지와 떨리는 목소리들이 그 위를 덮었다. 화면 속 장면에는 나를 밀치는 사람의 팔꿈치가 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_011","speaker":"응광","text":"뒤쪽 통로를 비워. 쓰러진 사람부터 확인하고, 단상으로 접근하는 사람은 막아. 추측을 사실처럼 옮기지 마.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_012","speaker":"","text":"각청은 밀려오는 줄을 멈추고 넘어진 사람이 일어설 공간을 만들었다. 나에게도 자리를 지키라고 손짓했다. 그러나 나는 알고 있었다. 이 뒤에 무엇이 오는지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_013","speaker":"나","text":"각청, 응광하고 따로 얘기하게 해 줘요. 잠깐이면 돼요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_014","speaker":"각청","text":"지금은 안 돼. 널 의심해서가 아니야. 현장 책임자를 지금 빼낼 수가 없어. 급하면 나한테 말해.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K1_rite_015","options":[{"label":"모락스의 죽음이 사람들이 생각하는 그대로가 아닐 수도 있어요.","id":"PRO_L02K1_rite_016","items":[{"k":"line","id":"PRO_L02K1_rite_017","speaker":"각청","text":"그래서 아직 아무것도 발표 안 했어. 아는 게 있으면 뭘 보고 알았는지부터 말해. 여기서 더 크게 말하진 말고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"기억을 잃는 일하고 이번 일이 겹쳤잖아요. 제가 몬드에서 본 것도 죽었다가 다시 움직이는 일이었어요.","id":"PRO_L02K1_rite_018","items":[{"k":"line","id":"PRO_L02K1_rite_019","speaker":"각청","text":"기억해. 하지만 드발린 일을 여기 그대로 붙일 순 없어. 먼저 사람들 안 다치게 길부터 비켜 줘.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L02K1_rite_020","speaker":"","text":"다시 응광을 찾았다. 그녀는 이미 다른 쪽으로 이동하고 있었다. 옷자락이 잠깐 보였고, 곧 사라졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_021","speaker":"나","text":"가 버렸잖아요. 나중에 전해 준다는 게 얼마나 나중인지도 모르는데……","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_022","speaker":"각청","text":"나도 네가 답답한 건 알아. 그래도 이 선은 못 넘게 해. 내가 여기서 듣고 있잖아. 지금 위험한 게 뭔지부터—","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_001","speaker":"","text":"각청의 말이 중간에서 끊겼다. 숨을 고르려는 멈춤과는 달랐다. 손이 공중에 남은 채 힘을 잃었고, 몸이 무너졌다. 내가 손을 뻗는 동안 옆의 병사도 쓰러졌다. 비명을 지르던 사람의 입이 열린 그대로 조용해졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_002","speaker":"","text":"각청의 어깨를 받치려다 함께 주저앉았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_003","speaker":"나","text":"각청.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_004","speaker":"나","text":"장난 아니잖아. 눈 떠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_005","speaker":"나","text":"하던 말 끝내. 듣고 있으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_056","text":"손목을 더듬었다. 닷새 내내 내 손목에서 찾았던 박동이 이번에는 없었다. 잡는 위치를 틀렸다고 생각해 손가락을 옮겼다. 얼굴을 가까이 대어도 숨이 닿지 않았다. 옆 병사도 같았다. 이곳에서 살아 움직이는 것은 나뿐이었다."},{"k":"line","id":"PRO_L02K1_death_006","speaker":"","text":"내 가슴만 뛰었다. 그게 견딜 수 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_007","speaker":"나","text":"누구든…… 아무나 대답해요. 여기 사람들 쓰러졌어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_008","speaker":"나","text":"제발.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_059","text":"대답 대신 바닥에 떨어진 물건이 굴러와 발끝에 닿았다. 그것을 밟지 않으려 발을 옮기다가 뒤로 물러섰다. 각청을 놓고 일어나 버렸다는 것을 알아차렸지만 다시 앉지 못했다. 더 가까이 가면 안 될 것 같았다. 근거는 없었다. 도망칠 방향을 정하기에는 충분했다."},{"k":"line","id":"PRO_L02K1_death_009","speaker":"","text":"계단을 내려갔다. 사람을 밟을까 봐 발을 고르다 벽에 부딪쳤고, 그래도 멈추지 않았다. 등 뒤에서 누가 붙잡아 주기를 바라면서도 뒤를 볼 수 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_061","text":"올라올 때 확인해 둔 길이 몸을 이끌었다. 행사 통로를 벗어나 외곽의 흙길을 밟았을 때에도 한참 더 달렸다. 사람이 있을 만한 길목이 보이면 옆으로 피했다."},{"k":"line","id":"PRO_L02K1_death_010","speaker":"","text":"발이 더 나가지 않는 곳에서 길가의 바위에 기대었다. 손바닥에 묻은 흙이 보였다. 각청의 어깨를 받칠 때 묻었는지, 계단에서 넘어졌을 때 묻었는지 알 수 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_011","speaker":"","text":"몬드로 돌아가 진에게 알리는 길이 떠올랐다. 그러나 가는 동안 또 사람이 죽으면. 이번에는 내 옆에 있던 사람들만 죽었다면. 그 생각을 지울 근거가 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_012","speaker":"나","text":"……선인한테 가자. 류운차풍진군. 적어도 내가 본 걸 끝까지는 들어 주겠지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_013","speaker":"나","text":"겁나서 산으로 숨는 거여도, 가서 말할 사람은 있어야지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_014","speaker":"","text":"말로 목적지를 정하자 흩어지던 생각이 한 방향으로 모였다. 소는 지금 어디 있는지 몰랐다. 류운차풍진군에게는 찾아갈 거처가 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_066","text":"평야에서 산으로 빠지는 갈림길을 한 번 지나쳤다. 되돌아왔을 때 해의 위치가 바뀌어 있었다. 머릿속 지도에는 내 가쁜 숨이 표시되어 있지 않았다."},{"k":"line","id":"PRO_L02K1_mountain_001","speaker":"","text":"바위 사이 좁은 길에서 돌이 굴렀다. 내가 찬 게 아니었다. 바위 색 비늘, 작은 뿔. 새끼 용 도마뱀 셋이 길 한가운데서 나를 보고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_002","speaker":"나","text":"……비켜 줄 생각은 없지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_003","speaker":"","text":"없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"combat","id":"PRO_L02K1_mountain_004","group":"EG_LIYUE_VISHAP","text":"산길을 막은 새끼 용 도마뱀 무리. 지나가지 않으면 오장산에 닿을 수 없다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_005","speaker":"","text":"마지막 한 마리가 바위 틈으로 들어갔다. 손이 떨렸다. 싸움 때문인지, 싸우는 동안만큼은 아무 생각도 안 해도 돼서 그런 건지 몰랐다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_006","speaker":"","text":"한쪽으로 몸을 기울여 통과해야 하는 구간에서 벽을 등지고 오래 서 있었다. 추락하면 누군가 살아 돌아오는 기적이 내게도 일어날지. 그 생각이 스친 것만으로 속이 울렁거렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_007","speaker":"나","text":"……죽었다 살아나는 걸 두 번 기대하는 건 염치없지. 살아서 올라가자.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_008","speaker":"","text":"눈을 감으면 각청이 말을 끝내지 못하던 입 모양이 떠올라서, 눈을 뜬 채 발끝만 보았다. 새가 날고 바람이 나뭇잎을 흔들었다. 그 소리를 확인할 때마다 다시 걸을 수 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_009","speaker":"","text":"거처에 이르렀을 때 문은 닫혀 있었다. 산을 올라오기만 하면 다음 장면이 시작될 줄 알았다. 문은 사람의 도착을 알아서 헤아려 주지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_mountain_010","options":[{"label":"류운차풍진군을 뵈러 왔습니다. 아래에서 큰일이 났어요. 예는 잘 못 갖췄는데, 일부러 그런 건 아닙니다.","id":"PRO_L02K1_mountain_011","items":[{"k":"line","id":"PRO_L02K1_mountain_012","speaker":"","text":"대답은 없었다. 공양 절차를 떠올렸다가 빈손을 내려다보았다. 문을 두드리면 무례일까 고민하다가, 무례가 두려워 돌아갈 상황이 아니라는 생각에 손을 들었다. 손끝이 닿기 전에 안쪽에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_013","speaker":"류운차풍진군","text":"문을 부술 생각으로 손을 드는 것이라면 내려놓게. 자네가 이곳까지 허둥지둥 올라온 사정은 무엇인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_014","speaker":"나","text":"들으셨으면 조금만 빨리 대답해 주시지…… 죄송합니다. 투정 부릴 때가 아닌 건 알아요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"(문 옆에 서서 기다린다.)","id":"PRO_L02K1_mountain_015","items":[{"k":"line","id":"PRO_L02K1_mountain_016","speaker":"","text":"문 옆으로 비켜서서 숨을 골랐다. 안에 아무도 없다면 소용없고, 안에 있는데 예를 모르니 돌려보낸 것일 수도 있었다. 한참 뒤 안쪽에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_017","speaker":"류운차풍진군","text":"문을 두드리지도, 돌아가지도 않는군. 그 정도 참을성이면 들을 만하겠지. 자네가 이곳까지 허둥지둥 올라온 사정은 무엇인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_018","speaker":"나","text":"기다리는 건 닷새 동안 연습했거든요. ……죄송합니다. 농담할 때가 아닌데.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_mountain_019","speaker":"나","text":"아래에서 모락스의 시신이 떨어졌습니다. 그리고 사람들이 죽었어요. 제가 있던 곳에서, 저만 빼고 전부요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_020","speaker":"","text":"안쪽의 기척이 멈췄다. 더 말하려다 숨이 목에 걸렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_021","speaker":"류운차풍진군","text":"제군의 일과 사람들의 죽음을 한숨에 묶어 말하지 말게. 언제, 어디서, 무엇을 보았는지 차례로 답할 수 있겠나. 이 몸이 듣고 있으니 호흡부터 고르게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_022","speaker":"나","text":"차례대로 말할 수 있어요. 대신 문에 대고 말하는 건 여기까지 했으면 해요. 문에 대고 말하니까…… 진짜 혼자 남은 것 같아서요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_023","speaker":"","text":"문이 열렸다. 안쪽에 모습을 드러낸 학이 나를 바라보았다. 그림으로 기억하던 자태와 달리, 눈앞의 존재는 가만히 서 있는 것만으로 내가 걸어온 거리를 작게 만들었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_024","speaker":"류운차풍진군","text":"들어오게. 자네가 무엇인지 이 몸이 벌써 판단한 것은 아니니, 그 표정으로 스스로 판결을 내리지는 말거라. 저 돌턱은 낮아 보이지만 발이 걸리기 쉽다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_025","speaker":"나","text":"……네. 안 걸릴게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_026","speaker":"","text":"걸렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_audience_001","speaker":"","text":"지정받은 자리에 앉았다. 무릎이 굽혀지자 올라오는 동안 참았던 통증이 한꺼번에 느껴졌다. 류운차풍진군은 내가 허리를 펴기도 전에 질문을 이어가지 않았다. 그 짧은 기다림 때문에 오히려 먼저 입을 열 수 있었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_002","speaker":"나","text":"리월항은 며칠 전부터 막혀 있었어요. 천암군 일부가 조금 전 일을 기억하지 못해서요. 저는 항구 밖에서 닷새를 기다렸고, 오늘 의례 길이 열려서 옥경대로 올라갔습니다. 시작하자마자 모락스의 몸이 떨어졌어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_003","speaker":"류운차풍진군","text":"떨어진 것을 직접 보았고, 그 몸을 제군의 시신이라 여겼다는 말이군. 자네가 그 자리에서 죽음을 확인한 사람은 또 누구인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_004","speaker":"나","text":"각청이요. 바로 앞에서 말하다가 쓰러져서 제가 받쳤어요. 숨이 없었고 맥박도 없었어요. 다른 사람도 같았고요. 계속 불렀는데…… 아무도요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_005","speaker":"","text":"말을 끝내자 처음으로 각청의 이름을 부르는 일이 견딜 만해졌다. 류운차풍진군은 곧바로 위로하지 않았다. 대신 내가 직접 본 범위와 보지 못한 범위를 하나씩 짚었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_006","speaker":"류운차풍진군","text":"응광은 그 전에 자리를 떠났고, 자네는 그 뒤의 행방을 보지 못했다. 그렇다면 그 사람의 생사까지 같은 말로 묶지는 않겠네. 어디까지 알며 어디서부터 모르는지가 분명해야, 이 몸도 움직일 방향을 정할 수 있지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_007","speaker":"","text":"맞는 말이었다. 못 본 사람까지 죽었다고 할 수는 없었다. 그리고 여기까지 온 이유가 하나 더 있었다. 숨을 고르고 고개를 들었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K1_audience_008","options":[{"label":"믿기 힘드실 텐데, 이건 모락스의 계략이에요. 리월이 스스로 버틸 수 있는지 보려는 계획. 오셀이 나올 수 있으니 막을 준비를 하셔야 해요.","keep":"ISK_L02_K1_086","items":[]}]},{"k":"line","id":"PRO_L02K1_audience_009","speaker":"","text":"류운차풍진군의 시선이 달라졌다. 놀라서 물러나는 반응이 아니었다. 내가 해서는 안 될 이름을 우연히 입에 담았는지, 아니면 그 무게를 알고 있는지 가늠하는 침묵이었다. 그 침묵을 견디면서 손가락을 무릎 위에 펼쳤다. 다시 맥박을 찾기 시작하면 말을 잇지 못할 것 같았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_010","speaker":"류운차풍진군","text":"자네가 말하는 계략에 방금 죽었다는 사람들까지 포함되어 있나? 그리고 오셀이라는 이름은 어디에서 들었지?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_011","speaker":"나","text":"아니요. 사람들이 죽는 건 제가 알던 일에 없었어요. ……제가 살던 곳에서, 이곳의 일을 이야기로 알고 있었어요. 당신이 계신 곳도 그래서 떠올렸고요. 그런데 여기서는 드발린이 진짜로 죽었다가 살아났고, 오늘은 제 눈앞에서 사람들이 죽었습니다. 제가 알던 이야기만 믿고 괜찮을 거라 말할 수는 없어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_012","speaker":"류운차풍진군","text":"그렇다면 먼저 그 두 가지를 나누게. 자네가 가지고 온 옛 지식과, 오늘 자기 눈으로 본 일. 앞의 것이 맞는지 확인하는 동안 뒤의 것을 버릴 필요는 없지. 허나 앞의 것으로 뒤의 일을 설명했다고 여겨서도 안 되네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K1_audience_013","options":[{"label":"제 말을 다 믿지 않으셔도 돼요. 바다 쪽만 봐 주세요. 제가 틀리면 민망한 걸로 끝나지만, 맞는데 준비가 없으면 사람이 더 죽잖아요.","id":"PRO_L02K1_audience_014","items":[{"k":"line","id":"PRO_L02K1_audience_015","speaker":"류운차풍진군","text":"민망함의 크기를 재러 온 자리가 아니니 그 허세는 내려놓게. 다만 위험의 이름을 구체적으로 말했고 현장의 사정을 함께 가져온 점은 가볍게 듣지 않았네.","map":"MAP_LIYUE_MOUNTAINS"}]},{"label":"다 맞힐 자신은 없어요. 그래도 모르는 척하고 내려가면 각청 앞에서 하던 일을 또 하는 것 같아서요. 중요한 얘기가 있다고만 하고 끝까지 말하지 못했거든요.","id":"PRO_L02K1_audience_016","items":[{"k":"line","id":"PRO_L02K1_audience_017","speaker":"류운차풍진군","text":"이미 끝난 대화를 이 자리에서 다시 이기려 하지 말게. 지금 할 일은 그 사람에게 하지 못한 말로 자신을 벌주는 것이 아니라, 아직 전할 수 있는 말을 빠뜨리지 않는 것이야. 계속해 보게.","map":"MAP_LIYUE_MOUNTAINS"}]}]},{"k":"line","id":"PRO_L02K1_audience_018","speaker":"","text":"더 전할 것이 있는지 생각하자 망서 객잔의 소가 떠올랐다. 그 말을 꺼내면 내가 원인일지 모른다는 두려움까지 드러날 것이다. 그래도 감춘 채 판단을 구하고 싶지는 않았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_019","speaker":"나","text":"망서 객잔에서 소를 만났어요. 제 주변에 죽음과 생명의 냄새가 같이 나고, 마신을 미워하는 기척도 느껴진다고요. 그분도 원인은 모른다고 했어요. 그래서 사람 없는 길로 왔습니다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_020","speaker":"나","text":"혹시 제가 원인이면…… 당신도 만나면 안 되는 거였나 싶은데. 그럼 저는 어디 가서 누구한테 말해야 하죠?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_021","speaker":"류운차풍진군","text":"자네 혼자 살아남았다는 것과 자네가 죽였다는 것은 같은 말이 아니네. 이 몸 앞에서 벌을 달라고 해도 그 빈칸을 대신 채워 줄 생각은 없어. 소의 말도 들었네. 허나 그 말만으로 자네 곁에 선 존재는 모두 죽는다고 결론 내릴 수는 없지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_022","speaker":"","text":"아무 일도 없을 것이라는 약속이 아니었다. 그것을 알아들었다. 어깨가 내려가자 의례장을 나온 뒤 처음으로 숨이 끝까지 들어왔다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_023","speaker":"나","text":"여기서 잠깐 쉬어도 될까요? 일어서려고 하니까 다리가 말을 안 듣네요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_024","speaker":"류운차풍진군","text":"앉아 있으라 했으면 쉬어도 된다는 뜻이지. 발목을 그렇게 비틀고 있으면 일어날 때 더 아플 테니 곧게 놓게. 인간의 몸은 쓰러지기 직전까지 버틴다고 더 오래 가는 물건이 아니야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_025","speaker":"나","text":"……지금 잔소리 들은 거 맞죠?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_026","speaker":"류운차풍진군","text":"충고네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_027","speaker":"나","text":"네. 충고요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_028","speaker":"","text":"자세를 고쳐 앉자 그녀는 한 차례 더 발목을 살피고서야 눈을 돌렸다. 누군가 내 다음 걸음을 실제로 걱정한다는 사실만 남았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_029","speaker":"류운차풍진군","text":"이 몸도 항구 쪽 사정을 확인하겠네. 자네의 이야기를 그대로 받아 적고 끝낼 일은 아니니. 다만 자네가 산을 내려가는 동안 모든 길이 안전해진다고 생각하지는 말게.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_030","speaker":"나","text":"알겠습니다. 내려가면 제가 도망친 길부터 다시 볼게요. 사람을 만나면 피하지 않고요. 다만 지금 바로 뛰어 내려가라고는 하지 말아 주세요. 의욕이 아니라 다리 문제예요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_031","speaker":"류운차풍진군","text":"이제야 두 가지를 제대로 나누는군. 쉬었다 가게. 자네가 가져온 이야기는 이 몸이 들었으니, 문밖에서 다시 외칠 필요도 없네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_return_001","speaker":"","text":"몸을 추스르고 밖으로 나왔을 때 산의 빛은 이미 낮과 달랐다. 어둠이 깊어지는 구간에서는 바람을 피할 만한 곳에서 기다렸다. 눈을 감는 일은 여전히 어려웠다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"keep","id":"ISK_L02_K1_108","text":"밤이 지나 길의 모양이 다시 보이자 산 아래로 향했다. 오를 때 지나친 갈림길에서 한동안 멈췄다. 도망칠 때의 나는 리월에서 멀어지기만 하면 된다고 생각했다. 돌아가는 지금의 나에게는 확인할 곳이 있었다. 각청을 놓고 일어난 자리였다."},{"k":"line","id":"PRO_L02K1_return_002","speaker":"","text":"리월항 외곽의 길에는 사람의 소리가 있었다. 화물 때문에 다투는 목소리, 길을 비켜 달라는 말, 바퀴가 돌을 넘는 소리. 그것들이 옥경대에 두고 온 사람들을 설명해 주지는 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_110","text":"봉쇄선은 남아 있었다. 병사들은 오가는 사람을 확인했고, 옆길로 들어서려는 행렬을 바깥으로 돌렸다. 사람들 사이에서 각청의 목소리를 들었다. 처음에는 비슷한 음성이라고 생각했다. 얼굴을 본 뒤에는 그 생각조차 할 수 없었다."},{"k":"line","id":"PRO_L02K1_return_003","speaker":"","text":"각청은 서 있었다. 어깨를 펴고 상대의 설명을 들으며, 필요한 대목에서 질문하고 있었다. 내 손 안에서 무게만 남았던 몸이 스스로 움직였다. 그녀가 고개를 돌렸을 때 나도 모르게 앞으로 나섰다가 멈췄다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_return_004","speaker":"나","text":"각청.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_return_005","speaker":"나","text":"너…… 어떻게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_return_006","speaker":"나","text":"내가 봤는데. 손도 잡고, 숨도 확인했는데.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_113","text":"각청은 내 얼굴을 바라보았다. 닷새 동안 상태를 묻고, 비 새는 천막을 함께 들어 올리고, 의례장 가장자리를 알려 주었던 사람이었다. 그러나 그 얼굴에, 알아본 사람에게만 잠깐 생기는 반응이 없었다. 시선은 낯선 이의 다친 손과 흐트러진 차림을 살핀 뒤 다시 눈으로 돌아왔다."},{"k":"line","id":"PRO_L02K1_return_007","speaker":"각청","text":"잠깐. 내 이름을 부르는 건 알겠는데, 우리 어디서 만났지? 너, 나를 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_END","text":"리월항 외곽 봉쇄선. 이야기는 살아 있는 각청의 질문 앞에서 멈춘다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_0","text":"송신의례라는 공고를 보여 주자 그녀는 답 대신 반송된 보고통을 꺼냈다. 고운각의 경계대가 보낸 통이었다. 안에는 종이가 없었다."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_1","text":"처음 뵙겠습니다. 월해정 비서 감우입니다. 각청 님께 말씀은 들었어요. 그 공고를 들고 저를 찾아오신 분은 당신이 처음이네요."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_4","text":"저도 갈게요. 앉아서 아는 척만 하는 건 이제 질렸어요. 지금 일어나는 일을 보러 가고 싶어요."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_6","text":"그 말은 보고통 찾아온 다음에 해. 네가 밤새 혼자 찾는 동안 우리 둘이 멀쩡히 쉴 수 있을 것 같아? 이 사람은 대기 자리에서 벗어난다고 병사한테 말해 두면 돼."},{"k":"text","id":"V141_AFTER_ISK_L02_K1_001_3","text":"해안 경계를 바꾸고, 배를 확인하고. 좋아요. 이제 저도 할 수 있는 말이 생겼네요. 불길하다는 말 말고요."}]},{"id":"ISK_L02_K2","entry":"ISK_L02_K2_001","items":[{"k":"keep","id":"ISK_L02_K2_001","text":"다음 날에도 짐은 봉쇄선 밖에 남아 있었다. 한 번 이야기하면 집에 갈 수 있을 줄 알았던 짐꾼은 내 옆에 쪼그려 앉아 손바닥의 굳은살을 문질렀다. 같은 아침을 또 시작한 것 같았다. 그때 아는 얼굴이 수레 사이로 나타났다."},{"k":"line","id":"PRO_L02K2_wait_001","speaker":"짐꾼","text":"당신은 갈 데 있으면 가도 되오. 본 것까지 말해 줬는데 여기 붙들어 놓으면 내가 미안해지지.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_1","text":"짐꾼은 쪼그려 앉기 전에 받침 수레의 짧은 손잡이를 한 번 더 눌렀다. 어제 내가 잠갔던 것과 같은 장치였다. 이제 확인표에 체크가 있어도 손으로 확인하지 않고는 떠나지 못하는 모양이었다."},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_2","text":"어제 내가 끌어온 받침은 병사가 다시 정리해 두었다. 짐꾼이 나를 붙잡아 두기 미안해하는 것과, 어제 일을 고마워하는 것은 다른 일이었다."},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_3","text":"나는 긴 짐끈에 손대지 않고 받침 수레의 잠금부터 살폈다. 어제 한 번 식은땀을 흘렸다고 전문가가 되지는 않았다."},{"k":"line","id":"PRO_L02K2_wait_002","speaker":"나","text":"갈 데가 있으면 이 포대 옆에서 먼지를 털고 있겠어요? 나중에 손해 났다고 반씩 내자는 말만 안 하시면 조금 더 있어 드릴게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_003","speaker":"짐꾼","text":"반씩 낼 사람이 있었으면 당신부터 안 골랐을 거요. 얼굴에 돈 아깝다는 소리가 아주 잘 쓰여 있으니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_004","speaker":"나","text":"그거 지워지는 건가요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_005","speaker":"짐꾼","text":"밥 먹으면 좀 옅어지더군.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_006","speaker":"","text":"웃음이 사라진 뒤 그는 다시 짐을 보았다. 넘겼다고 할 수도, 넘기지 않았다고 할 수도 없는 일 사이에서, 포대의 무게를 계속 자기 어깨에 얹고 있는 사람처럼 앉아 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_001","speaker":"","text":"해가 기울 무렵 각청이 돌아왔다. 짐꾼이 일어서자 그녀가 앉아 계시라는 손짓을 했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_002","speaker":"각청","text":"짐부터 볼게요. 제가 확인한 뒤에 옮기지는 않으셨죠?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_003","speaker":"짐꾼","text":"그대로 뒀소. 풀지도 않았고. 다음 사람이 오면 또 풀자고 하겠지만……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_004","speaker":"각청","text":"그 '다음 사람'은 제가 막을게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_005","speaker":"","text":"각청은 포대의 묶인 부분을 살핀 뒤 병사를 불렀다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_006","speaker":"각청","text":"이 짐은 따로 맡아 줘. 다음 담당자가 와도 풀기 전에 이 표부터 보여 주고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_007","speaker":"짐꾼","text":"그럼 오늘은 어디까지 된 거요? 같은 설명만 하다가 해가 졌소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_008","speaker":"각청","text":"오늘 안에 끝난다고는 못 해요. 대신 처음부터 다시 설명하는 일은 없게 할게요. 그것까지 못 막으면 제가 여기 서 있을 이유가 없죠.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_evening_009","options":[{"label":"저 때문에 더 늦어진 건 아니죠?","id":"PRO_L02K2_evening_010","items":[{"k":"line","id":"PRO_L02K2_evening_011","speaker":"각청","text":"아니. 덕분에 짐 더 섞기 전에 멈췄잖아. 뒷일은 내가 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_012","speaker":"나","text":"다행이네요. 일만 벌여 놓고 가는 것 같아서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_013","speaker":"각청","text":"벌인 건 맞아. 그래도 좋은 쪽으로.","map":"MAP_LIYUE_PLAINS"}]},{"label":"다음에도 처음부터 설명해야 해요?","id":"PRO_L02K2_evening_014","items":[{"k":"line","id":"PRO_L02K2_evening_015","speaker":"각청","text":"아니. 더 물을 게 생기면 어느 부분인지 내가 짚어서 물어볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_016","speaker":"","text":"각청은 병사가 든 표의 아래쪽을 짚어 이미 확인한 내용을 구분해 주었다.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_evening_017","speaker":"각청","text":"잠깐 자리 비우실 땐 이 병사한테 말씀해 주세요. 짐은 두고 다녀오셔도 됩니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_018","speaker":"짐꾼","text":"그 말이면 됐소. 어디까지 가도 되는지 몰라서 꼼짝을 못 했지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_019","speaker":"","text":"짐꾼이 굳은 허리를 폈다. 각청은 그가 지나가도록 옆으로 비켜섰다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_020","speaker":"나","text":"각청 씨도 쉬러 가요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_021","speaker":"각청","text":"다음 교대한테 전할 거 전하고. 그래야 아저씨가 내일 아침에 또 같은 질문 안 듣지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_022","speaker":"나","text":"그럼…… 고맙습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_023","speaker":"각청","text":"……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_024","speaker":"각청","text":"인사는 들었으니까 이제 진짜 가서 쉬어. 서서 조는 사람 처음 봐.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_025","speaker":"나","text":"안 졸았어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_026","speaker":"각청","text":"눈 감고 있었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_001","speaker":"","text":"이튿날에는 짐꾼이 자리를 비웠다가 해가 기울기 전에 돌아왔다. 그가 돌아와 가장 먼저 확인한 것은 짐의 수가 아니라 내가 아직 거기 있다는 사실이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_002","speaker":"짐꾼","text":"설마 내가 도망쳤다고 생각한 건 아니겠지? 볼일이 길어졌소.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_days_003","options":[{"label":"도망칠 거면 짐 두고 간다고 친절하게 말하진 않았겠죠. 모르는 사람들 틈보다 이미 제 형편을 낮게 평가한 사람 옆이 편해서요.","id":"PRO_L02K2_days_004","items":[{"k":"line","id":"PRO_L02K2_days_005","speaker":"짐꾼","text":"높게 평가해 달라는 말로 들리는군. 그런데 걸어오는 꼴부터 불안하오. 오늘은 짐 들어 주겠단 말 하지 마시오. 당신까지 들고 가야 하면 곤란하니.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_006","speaker":"","text":"입을 열었다가 닫았다. 정확히 그 말을 하려던 참이었다.","map":"MAP_LIYUE_PLAINS"}]},{"label":"무거운 건 안 맡을게요. 대신 옆에서 눈으로 볼 일이 있으면 하죠.","id":"PRO_L02K2_days_007","items":[{"k":"line","id":"PRO_L02K2_days_008","speaker":"짐꾼","text":"자기 상태를 알고 말하면 다행이오. 도와주겠다는 사람까지 눕히는 일은 피하고 싶으니.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_009","speaker":"나","text":"어제 승강기에서 딸려 올라간 사람한테 그 말은 좀 아프네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_010","speaker":"짐꾼","text":"그러니까 하는 말이오.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_days_011","speaker":"","text":"짐꾼이 앉을 자리를 비워 주었다. 대화는 인계가 어디서 막혔는지에서 오늘 바람이 어느 쪽으로 부는지로, 다시 어디까지 걸어가면 줄이 덜 붐비는지로 옮겨 갔다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_012","speaker":"","text":"셋째 날, 같은 병사가 익숙한 글씨를 앞에 놓고 한동안 말을 하지 못했다. 자기가 적은 건 알겠는데 그때 한 일이 떠오르지 않는다고 했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_013","speaker":"나","text":"생각 안 나면 거기까지만 말해도 돼요. 저도 끈 풀린 것밖에 못 봤어요. 반쪽짜리 둘 붙인다고 하나가 되진 않잖아요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_014","speaker":"검수 병사","text":"고맙습니다. 그런데 제가 모른다고 하면 다른 사람이 또 멈추니까요. 제가 제일 큰 걸림돌이 된 기분입니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_015","speaker":"짐꾼","text":"당신이 오늘 새로 멈춘 건 아니오. 멈춰야 할 데를 이제 안 거지. 모르는 걸 안다고 하고 넘겼다가 나중에 사라지면, 그땐 셋 다 거짓말쟁이가 되지 않겠소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_016","speaker":"","text":"짐꾼을 보았다. 첫날에는 병사의 대답을 재촉하던 사람이었다. 여전히 기다리는 시간을 아까워하고 끈을 볼 때마다 한숨을 쉬었다. 다만 그 시간을 누구한테 화내서 되찾을 수 있는지에 대해서는 생각이 달라진 듯했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_017","speaker":"","text":"넷째 날에는 의례 날의 동선 안내가 다시 돌았다. 물자가 들어가는 길과 참관객이 올라가는 길은 다르다는 설명에, 짐꾼은 한동안 먼 곳을 바라보았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_018","speaker":"짐꾼","text":"짐은 병사한테 위치 확인받고 그대로 둘 거요. 나도 잠깐 올라갔다 오려고. 신 앞에서 이러고 기다리는 사람 있다는 얘기라도 해 볼까 해서. 당신도 갈 거면 같이 가겠소?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_019","speaker":"나","text":"가죠. 신한테 사정해서 될 일이면 저도 한마디 보탤게요. 줄 서서 옆 사람한테 투덜거리는 건 제 전문이고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_020","speaker":"짐꾼","text":"말만 들으면 아주 큰 선행을 하는 것 같군. 올라가다 힘들다고 먼저 주저앉지만 마시오. 별것도 없는 짐 들고 와 놓고 걸핏하면 어깨를 주무르더구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_021","speaker":"나","text":"그건 체질이에요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_022","speaker":"짐꾼","text":"게으른 체질이지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_023","speaker":"","text":"웃었다. 상대가 내일도 나를 같은 사람으로 기억할 거라고 당연히 믿을 수 있는 대화였다. 그 당연함이 얼마나 드문 일인지, 나는 얼마 뒤에야 알게 된다. 소의 말은 여전히 각청에게 전하지 않은 채였다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_033","text":"닷새가 지난 아침, 두 사람은 짐의 위치가 확인되는 것을 지켜본 뒤 행사 길 쪽으로 향했다. 짐꾼은 돌아왔을 때 어느 자리에서 다시 만나면 되는지까지 정해 두었다."},{"k":"keep","id":"ISK_L02_K2_034","text":"행사 통로가 열려 있었다. 짐꾼은 평소라면 짐을 싣고 향했을 길을 한 번 보고 돌아섰다."},{"k":"line","id":"PRO_L02K2_rite_001","speaker":"안내 병사","text":"의례가 끝나면 이 길로 돌아오십시오. 동행과 떨어져도 옆길로 찾으러 가시면 안 됩니다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_rite_002","options":[{"label":"이분 잃어버리면 화물 있는 데서 찾으면 되겠네요. 그 자리는 잊고 싶어도 못 잊겠어요.","id":"PRO_L02K2_rite_003","items":[{"k":"line","id":"PRO_L02K2_rite_004","speaker":"짐꾼","text":"잃어버린다니, 내가 당신 짐이오? 걱정되면 당신이 뒤처지지 말고 따라오시오.","map":"MAP_LIYUE_PLAINS"}]},{"label":"서로 놓치면 화물 있는 쪽에서 만나요. 제가 뒤처지면 한 번만 불러 주세요.","id":"PRO_L02K2_rite_005","items":[{"k":"line","id":"PRO_L02K2_rite_006","speaker":"짐꾼","text":"찾을 곳 정하는 건 좋소. 다만 부르는 소리 들릴 만큼은 따라와야겠지.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L02_K2_038","text":"두 사람은 앞서거니 뒤서거니 하며 올라갔다. 며칠 함께 기다렸다고 가까운 친구가 되는 것은 아니었다. 그래도 짐꾼이 사람들 사이에서 한쪽 어깨를 낮추고 걷는 버릇을 알게 되었다. 짐이 없을 때도 몸은 무거운 것을 피해 지나갈 틈부터 찾았다."},{"k":"line","id":"PRO_L02K2_rite_007","speaker":"","text":"옥경대에서는 시선이 한곳으로 모였다. 공고의 의례 이름과 내 기억 사이의 어긋남을 생각했다. 이름만 바뀐 건지, 일이 다른 순서로 일어나는 건지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_008","speaker":"짐꾼","text":"고개를 그렇게 내밀면 앞사람과 부딪히오. 이쪽에 서시오. 나는 저 위까지 훤히 안 보여도 괜찮으니.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_009","speaker":"나","text":"오늘은 제가 가려지는 쪽이네요. 고마워요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_010","speaker":"짐꾼","text":"키 얘기는 안 했소.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_011","speaker":"나","text":"했어요, 방금.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_042","text":"말이 끝나고 얼마 지나지 않아 의례가 시작되었다. 하늘로 향하던 시선 앞에서 거대한 몸이 떨어졌다. 짐꾼이 본능적으로 내 팔을 잡아당겼다. 충격이 발바닥을 타고 올라왔고, 모여 있던 사람들이 뒤로 밀렸다. 먼지가 가라앉는 자리에는 모락스의 시신이 놓여 있었다."},{"k":"line","id":"PRO_L02K2_rite_012","speaker":"","text":"짐꾼이 잡은 팔을 바로 빼지 못했다. 두 사람 모두 시신에서 눈을 떼지 못했다. 신마저 죽었다는 말이 가까이에서 튀어나왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_013","speaker":"응광","text":"그 자리에서 서로 밀지 마. 천암군은 통로를 확보하고, 들리는 말을 그대로 옮기지 마라.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_014","speaker":"","text":"각청이 통로 가장자리로 와서 사람들을 물렸다. 짐꾼은 앞에 넘어진 사람을 일으켰고, 나도 손을 뻗어 설 자리를 만들었다. 틈 사이로 응광이 보였다. 나는 알고 있었다. 이 뒤에 무엇이 오는지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_015","speaker":"나","text":"각청, 저 응광하고 따로 얘기해야겠어요. 잠깐만요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_016","speaker":"각청","text":"지금은 안 돼. 네가 물자 일에 협조한 건 알아. 그래도 그걸로 의례 현장을 마음대로 다닐 순 없어. 급하면 내가 들을게.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K2_rite_017","options":[{"label":"자격을 써먹겠다는 게 아니에요. 제군에 관한 일이고, 그 다음에 벌어질 일 얘기예요.","id":"PRO_L02K2_rite_018","items":[{"k":"line","id":"PRO_L02K2_rite_019","speaker":"각청","text":"그럼 더더욱 네가 어떻게 아는지부터 들어야지. 다음 일을 안다는 말만으로 현장 책임자를 데려올 순 없어. 옆에 넘어진 사람부터.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 최소한 제 얘기가 있다는 건 전해 줘요. 출처를 설명하려면 오래 걸려요.","id":"PRO_L02K2_rite_020","items":[{"k":"line","id":"PRO_L02K2_rite_021","speaker":"각청","text":"전할 게 있다는 건 알겠어. 하지만 출처 설명이 어렵다는 말이 출처를 건너뛰어도 된다는 뜻은 아니야. 본 것부터.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L02K2_rite_022","speaker":"","text":"다시 고개를 돌렸을 때 응광은 현장을 떠나고 있었다. 옷자락이 보였다가 사라졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_023","speaker":"짐꾼","text":"아는 게 있으면 지금 이분한테 말하시오. 사람 가려 가며 할 때가 아닌 것 같은데. 당신, 본 것과 안 본 것은 잘 나누더니 오늘은 말 앞에서 자꾸 머뭇거리는군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_024","speaker":"나","text":"……맞아요. 이상하게 들릴까 봐 순서만 찾고 있었어요. 각청, 들어 줘요. 이건 제가 전에—","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_001","speaker":"","text":"짐꾼의 손이 내 팔에서 떨어졌다. 헛디딘 줄 알고 옷깃을 잡았다. 각청도 동시에 무릎이 꺾였다. 옆의 병사가 창을 놓쳤고, 군중의 소리가 중간에서 뚝 끊겼다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_002","speaker":"","text":"짐꾼을 끌어안은 채 주저앉았다. 가벼울 거라던 몸이 갑자기 움직일 수 없는 무게가 되었다. 이름 대신 아는 호칭을 불렀다. 닷새를 같이 있었는데 이름보다 짐꾼이라는 말이 먼저 나왔다는 사실이 뒤늦게 나를 찔렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_003","speaker":"나","text":"아저씨.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_004","speaker":"나","text":"일어나요. 말하라면서요. 말할게요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_005","speaker":"나","text":"들어요. 제발.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_062","text":"몸을 돌려 각청에게 손을 뻗었다. 도움을 청하려 이름을 부르다가 그녀도 같은 상태라는 것을 깨달았다. 손목에도, 목 가까이에도 뛰는 것이 없었다. 짐꾼도 병사도 같았다. 현장의 사람들은 모두 죽었다. 그 가운데 나만 살아 있었다."},{"k":"line","id":"PRO_L02K2_death_006","speaker":"","text":"짐꾼의 몸을 다시 당겼다. 조금 옮기는 것만으로 손이 미끄러졌다. 도와 달라고 고개를 들었다가 그 말마저 삼켰다. 사람은 가득한데 부를 사람이 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_007","speaker":"나","text":"왜…… 아까 다 살아 있었잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_008","speaker":"나","text":"누가 좀. 여기 혼자 두지 말아요.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_065","text":"짐꾼을 바닥에 눕히고 한 발 뒤로 물러났다. 다시 들면 될 것 같아서 손을 뻗었지만, 닿기 전에 팔이 굳었다. 시신이 무서운 것인지 다음 순간 내게 무슨 일이 생길지가 무서운 것인지 구분할 수 없었다. 계단 쪽으로 몸을 돌렸을 때 비명이 터졌다."},{"k":"line","id":"PRO_L02K2_death_009","speaker":"","text":"내려가는 길에서 몇 번이나 돌아서려 했다. 물건을 두고 온 것처럼. 그러나 돌아갈 곳에 무엇이 있는지 떠올릴 때마다 다리가 먼저 달렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_067","text":"행사 통로 밖으로 빠져나온 뒤에도 길을 고를 여유가 없었다. 내 발소리가 겹쳐 들릴 때마다 누가 따라오는 줄 알았다. 물자 구역으로 향하던 발은 중간에 멈췄다. 그곳에 가면 짐꾼이 돌아올 자리가 보일 것이었다."},{"k":"line","id":"PRO_L02K2_death_010","speaker":"","text":"길가에 엎드리듯 앉았다. 아직 짐꾼의 소매를 쥐고 있는 줄 알고 손을 폈다. 아무것도 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_011","speaker":"나","text":"……내가 본 건 내가 말해야지. 저 사람들은 이제 못 하잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_012","speaker":"나","text":"사람 있는 데로 가자. 이번엔 순서 찾다가 놓치지 말고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_013","speaker":"","text":"말을 알아들어 줄 사람을 생각하자 선인들이 떠올랐다. 소는 어디 있는지 몰랐다. 거처와 산의 모습을 가장 선명하게 기억하는 이름을 붙들었다. 류운차풍진군.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_001","speaker":"","text":"머릿속에서는 간단했다. 절운간 쪽으로 가서 오장산에 오르고, 거처를 찾아 소식을 전한다. 실제로는 어느 길이 산을 돌아 올라가고 어느 길이 절벽 아래에서 끊기는지부터 알아내야 했다. 처음 택한 오르막은 능선에 닿지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_002","speaker":"나","text":"길을 안다고 한 적은 없지. 장소를 안다고만 했지. ……산한테 면담 거절당하고 끝낼 수는 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_073","text":"산으로 들어가는 길을 다시 골랐다. 짐꾼이 무거운 것을 든 몸으로 사람 사이의 틈을 찾던 모습이 떠올랐다. 곧장 가는 길이 항상 몸을 가장 적게 쓰는 길은 아니라는 것을, 그의 걸음에서 조금 배웠던 것 같다."},{"k":"line","id":"PRO_L02K2_mountain_003","speaker":"","text":"바위가 많은 비탈에서 돌이 굴렀다. 내가 찬 게 아니었다. 바위 색 비늘, 작은 뿔. 새끼 용 도마뱀 셋이 길 한가운데서 나를 보고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_004","speaker":"나","text":"지금 나 건드리면 안 되는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_005","speaker":"","text":"알아들었을 리 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"combat","id":"PRO_L02K2_mountain_006","group":"EG_LIYUE_VISHAP","text":"산길을 막은 새끼 용 도마뱀 무리. 지나가지 않으면 오장산에 닿을 수 없다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_007","speaker":"","text":"마지막 한 마리가 바위 틈으로 들어갔다. 숨이 거칠었다. 싸우는 동안만큼은 짐꾼의 얼굴이 떠오르지 않았다. 그게 미안했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_008","speaker":"","text":"높이 오를수록 사람 소리가 멀어졌다. 머릿속에서 짐꾼은 여전히 나에게 본 것과 안 본 것을 나누라고 말하고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_009","speaker":"","text":"거처 앞에 도착했을 때 문을 향해 곧장 걸어갔다가 제자리로 돌아왔다. 숨이 거칠어 첫마디를 끝내지 못할 것 같았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_010","speaker":"나","text":"류운차풍진군. 리월항에서 왔습니다. 제군의 시신이 떨어진 것을 봤고, 그 뒤 현장에 있던 사람들이 죽었습니다. 저는 살아 나왔어요. 문을 여실 수 없으면 듣고 계신지만 알려 주십시오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_011","speaker":"","text":"대답이 없었다. 다시 부르고 싶은 마음을 누르며 문 옆으로 비켜섰다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_mountain_012","options":[{"label":"제가 모르는 절차가 있으면 말씀해 주세요. 음식을 갖추라고 하셔도 지금은 없습니다. 있는 척할 수는 없잖아요.","id":"PRO_L02K2_mountain_013","items":[{"k":"line","id":"PRO_L02K2_mountain_014","speaker":"류운차풍진군","text":"갖추지 못한 예물을 핑계로 들어 달라는 것인지, 들은 뒤에 예물을 요구하지 말라는 것인지. 인간의 말은 참으로 돌아가는 길이 많군. 이름을 밝히고 용건을 말하게.","map":"MAP_LIYUE_PLAINS"}]},{"label":"급한 소식을 전하러 왔지만, 문 앞 예절까지 안다고 할 수는 없습니다. 이름과 용건부터 말씀드려도 될까요?","id":"PRO_L02K2_mountain_015","items":[{"k":"line","id":"PRO_L02K2_mountain_016","speaker":"류운차풍진군","text":"모르는 순서를 묻는 것은 허물이 아니지. 다만 급하다는 말로 다른 설명을 덮지는 말게. 이름을 밝히고 용건을 말하게.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_mountain_017","speaker":"나","text":"(자신의 이름을 밝힌다.) 몬드에서 왔습니다. 리월항 밖에서 기다리다가 오늘 의례를 보러 올라갔고요. 들어도 모르실 이름이지만, 제 이름 걸고 말씀드리겠습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_018","speaker":"류운차풍진군","text":"의례를 보러 간 사람이 제군의 시신을 보고 돌아왔다. 그 뒤 사람들이 죽었다는 말은, 모두가 흩어져 보이지 않았다는 뜻이 아니겠지?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_019","speaker":"나","text":"없어진 게 아니에요. 제 앞에 남아 있었어요. 같이 올라간 사람을 잡고 있었는데 힘이 빠졌고, 불러도 대답하지 않았습니다. 각청도 바로 거기서 죽었어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_020","speaker":"","text":"문이 열렸다. 학의 눈이 내 차림보다 얼굴에 오래 머물렀다. 마침내 내 증언이 살아 있는 상대에게 도착했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_021","speaker":"류운차풍진군","text":"발부터 들이밀 생각은 접고 잠깐 서 있게. 바닥의 높이가 달라 몸이 앞으로 쏠릴 것이야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_022","speaker":"나","text":"알겠습니다. 제가 아무 데서나 넘어지는 사람이 된 건 오늘만 그런 겁니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_023","speaker":"류운차풍진군","text":"어제는 아니었다는 말인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_024","speaker":"나","text":"……어제도 조금요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_audience_001","speaker":"","text":"말한 것만큼 조심해서 들어갔다. 류운차풍진군은 나를 앉혔다. 문밖에서 정리한 순서는 앉는 순간 다시 흐트러졌다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_002","speaker":"류운차풍진군","text":"함께 올라갔다는 이는 자네의 오랜 벗인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_003","speaker":"나","text":"아니요. 닷새 같이 기다린 사람이에요. 화물이 막힌 짐꾼이었고…… 망서 객잔 승강기에서 떨어질 뻔한 걸 같이 끌어올린 사람이기도 해요. 이름도 못 물어봤어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_004","speaker":"류운차풍진군","text":"그 사람이 죽은 뒤 자네는 무엇을 했나. 이 몸에게 잘 보일 일을 골라 말하라는 뜻이 아니야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_005","speaker":"나","text":"깨우려고 했고, 끌고 가려고 했어요. 안 됐어요. 각청한테 도와 달라고 하려다가 그 사람도 죽은 걸 확인했고요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_006","speaker":"나","text":"그러고는…… 놔두고 도망쳤습니다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_007","speaker":"","text":"마지막 대답을 할 때 고개를 들었다. 짐꾼에게 본 것만 말하겠다고 했던 사람이, 그를 두고 나온 장면만 다른 모양으로 바꿀 수는 없었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_008","speaker":"류운차풍진군","text":"구할 수 있었는데 하지 않았다는 것과, 구하려 했으나 손이 닿지 않았다는 것은 다르지. 이 몸이 그 자리에 없었으니 어느 쪽이라고 대신 판정하지는 않겠네. 다만 업고 오지 못했다고 해서 가져온 소식까지 버릴 이유는 없네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_009","speaker":"","text":"그분이 여기 있었다면 내 말이 길다고 했을 것이다. 아는 게 있다고만 하지 말고 그냥 말하라고. 그래서 이번에는 먼저 말했다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K2_audience_010","options":[{"label":"모락스의 계략입니다. 자신의 죽음을 계기로 리월이 스스로 위기를 넘기는지 보려는 거예요. 오셀이 나올 수 있으니, 막을 준비를 하셔야 합니다.","keep":"ISK_L02_K2_094","items":[]}]},{"k":"line","id":"PRO_L02K2_audience_011","speaker":"류운차풍진군","text":"자네가 방금 붙인 이름이 얼마나 무거운지 알고 하는 말인가. 누구에게 들었는가? 그 말을 전한 사람이 오늘 그곳에 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_012","speaker":"나","text":"이곳 사람한테 들은 게 아닙니다. 제가 살던 곳에서, 이곳의 일을 이야기처럼 알고 있었어요. 제가 여기 온 것부터 설명이 안 된다는 건 알아요. 그런데 오셀 이름을 아는 이유도, 당신을 찾아올 생각을 한 이유도 그겁니다. 거짓말을 덧대서 더 그럴듯하게 만들 수는 없어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_013","speaker":"류운차풍진군","text":"자네가 알고 있었다는 이야기에는 오늘 함께 갔던 이의 죽음도 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_014","speaker":"나","text":"없었어요. 병사들이 기억을 잃는 일도, 제 눈앞에서 모두가 죽는 일도요. 그러니까 계략이라는 건 제가 아는 원래 이야기의 설명이고, 오늘 이 죽음의 이유까지 안다는 뜻은 아니에요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_015","speaker":"류운차풍진군","text":"아는 이야기가 있으니 모르는 일이 벌어져도 그 안에 들어갈 것이라고 기대하고 있지 않은가. 이미 자네는 그 이야기에 없던 죽음을 두 번 보았네. 그런데도 더 오래 알고 있던 쪽에 모든 판단을 맡길 셈인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_016","speaker":"","text":"반박할 말은 많아 보였다. 어느 반박도 짐꾼을 다시 일으켜 세우지는 못했다. 무릎 위의 손을 풀었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K2_audience_017","options":[{"label":"그래도 경고는 하겠습니다. 미래를 다 안다는 말은 거둘게요. 오셀에 대비해 달라는 말은 거두지 않겠습니다.","id":"PRO_L02K2_audience_018","items":[{"k":"line","id":"PRO_L02K2_audience_019","speaker":"류운차풍진군","text":"그 두 말을 구분할 수 있다면 이 몸도 다르게 듣겠네. 자네의 확신을 증거로 삼지는 않겠으나, 구체적인 위협을 경계할 이유로는 검토하지.","map":"MAP_LIYUE_MOUNTAINS"}]},{"label":"아는 줄 알았던 데 매달린 건 맞아요. 아무것도 모르겠다고 하면 도망갈 데도 없어질 것 같았거든요. 그래도 직접 확인하러 가 주시면 안 될까요?","id":"PRO_L02K2_audience_020","items":[{"k":"line","id":"PRO_L02K2_audience_021","speaker":"류운차풍진군","text":"확인할 필요는 충분히 들었네. 자네를 달래려 나서는 것이 아니라 리월에 일어난 일을 살피러 가는 것이야. 그 차이가 서운하더라도 받아들이게.","map":"MAP_LIYUE_MOUNTAINS"}]}]},{"k":"line","id":"PRO_L02K2_audience_022","speaker":"","text":"아직 말하지 않은 것이 남아 있었다. 망서 객잔에서 소에게 들었던 말. 각청에게는 끝내 전하지 못했다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_023","speaker":"나","text":"한 가지 더요. 소를 만났을 때 제 주변에 죽음과 생명의 냄새가 같이 난다고 했습니다. 마신을 미워하는 기척도요. 저는 그런 마음 없어요. 그분도 누구 건지까지는 말하지 않았고요. 각청한테는…… 못 전했어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_024","speaker":"류운차풍진군","text":"그 말을 듣고 난 뒤 자네에게 달라진 점이 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_025","speaker":"나","text":"딱히요. 오늘 일을 전부 그 말에 붙이면 설명한 것 같겠지만, 그럴 근거는 없잖아요. 그냥 저만 남았어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_026","speaker":"나","text":"그게 지금 제일 무서워요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_027","speaker":"류운차풍진군","text":"이 몸은 소가 전한 말을 가볍게 여기지 않네. 그렇다고 들은 말 하나로 지금의 모든 죽음에 주인을 정해 주지도 않을 것이야. 모르는 것을 견디지 못해 아무 답이나 붙잡으면, 다음에 보는 것도 그 답에 맞춰 바꾸게 되지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_028","speaker":"나","text":"닷새 동안 남한테는 모르면 모른다고 해도 된다고 해 놓고, 정작 제가 모르겠다는 건 이렇게 못 견디네요. 말로 남 도와주는 건 참 편했어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_029","speaker":"류운차풍진군","text":"누군가에게 해 준 말이 이제 자네에게도 필요한 때가 온 것이겠지. 그 말이 거짓이 되는 건 아니네. 허나 자네를 위로하는 일만 하고 있을 수는 없어. 이 몸은 항구 쪽 사정을 살피겠네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_030","speaker":"","text":"그녀는 자신이 무엇을 이미 알고 있는지 풀어놓지 않았다. 원작의 장면을 맞혀 보이는 손님이 아니라, 실제 현장에서 소식을 가져온 사람으로 대우받고 있다는 것을 느꼈다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_031","speaker":"나","text":"저도 내려가겠습니다. 그분 짐이 있던 곳으로요. 집이 어딘지, 기다리는 사람이 누군지는 모르지만…… 물을 사람이 있으면 제가 대답해야죠.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_032","speaker":"류운차풍진군","text":"지금 내려가겠다고 벌떡 일어나지는 말게. 산길은 자네가 후회하는 만큼 짧아지는 것이 아니야. 빛이 남은 구간만 움직이게. 소식을 전하려거든 소식을 가진 몸부터 무사히 데려가야 하네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_033","speaker":"나","text":"들을수록 제가 되게 관리 안 된 짐짝 같네요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_034","speaker":"류운차풍진군","text":"자네가 그렇게 말했네. 이 몸은 아니야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_035","speaker":"나","text":"……네. 안 떨어뜨리고 내려가 볼게요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_036","speaker":"류운차풍진군","text":"해 보겠다는 말은 장담이 아니니 마음에 드는군. 앉아 있을 수 있을 때는 더 앉아 있게.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_return_001","speaker":"","text":"조금 더 앉아 있었다. 무언가를 해야 한다는 마음과 몸이 움직일 수 있다는 사실을 처음으로 따로 생각했다. 나를 재촉할 짐꾼은 없었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"keep","id":"ISK_L02_K2_123","text":"해가 진 뒤에는 길을 확인할 수 없는 비탈을 포기하고 바위 아래에 머물렀다. 눈을 감으면 짐꾼의 몸을 놓는 순간이 떠올랐다. 몇 번을 다시 보아도 다음 장면은 달라지지 않았다. 다시 밝아진 뒤에야 외곽으로 발걸음을 이었다."},{"k":"line","id":"PRO_L02K2_return_002","speaker":"","text":"항구로 향하는 길에서 먼 곳의 수레를 먼저 보았다. 사람이 끌고 있었다. 살아 있는 사람이 일하고 있었다. 다행이라고 생각하는 순간, 두고 온 사람들만 다시 떠올리는 것이 미안해졌다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_125","text":"도시는 여전히 통제되어 있었다. 물자를 기다리는 사람들이 병사 앞에서 설명하고 있었다. 그 가운데 익숙한 옷차림을 보았다. 각청이었다. 그녀가 걸음을 옮기자 주변 사람들이 자연스럽게 길을 비켜 주었다."},{"k":"line","id":"PRO_L02K2_return_003","speaker":"","text":"잘못 보았다고 생각하려 했다. 그러나 눈앞의 각청은 자기 이름을 부르는 사람에게 돌아보았고, 질문에 대답했다. 살아 있었다. 의례장에서 확인한 손목의 침묵과 이곳에서 움직이는 손이 한 사람의 것이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_return_004","speaker":"나","text":"각청.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_return_005","speaker":"나","text":"너 어떻게…… 나야. 포대 끈 봤다던 사람.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_return_006","speaker":"나","text":"너 죽었잖아. 내가 확인했는데.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_128","text":"각청은 즉시 대답하지 않았다. 그녀가 잠깐 멈춘 것을 나는 알아보았다는 신호로 받아들이려 했다. 그러나 다음 시선은 알고 있는 사람의 말을 기다리는 시선이 아니었다. 혼란스러운 말을 늘어놓는 낯선 사람이 자신을 어디에서 보았을지 살피는 눈이었다."},{"k":"line","id":"PRO_L02K2_return_007","speaker":"각청","text":"내가 죽었다고? 진정하고 처음부터 말해 봐. 그 전에 하나만. 너 누구야? 나를 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_END","text":"리월항 외곽 봉쇄선. 이야기는 살아 있는 각청의 질문 앞에서 멈춘다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L02_K2_001_0","text":"짐꾼은 같은 일을 두 번 했다는 확인 때문에 품삯을 받지 못했다. 그런데 행추가 들고 온 인계표를 보니, 그가 옮긴 자루에는 서로 다른 두 항구의 번호가 붙어 있었다."},{"k":"text","id":"V141_BEFORE_ISK_L02_K2_001_6","text":"둘이 밥 맡으면 나는 짐표 맡을게. 아저씨, 다녀와서 또 세라고 하면 그땐 제가 대신 화낼 거예요."},{"k":"text","id":"V141_AFTER_ISK_L02_K2_001_2","text":"고마워. 이건 내가 전할게. 행추, 나중에 저 아저씨를 못 찾게 되면…… 이번에는 짐 말고 사람부터 찾아 줘."}]},{"id":"ISK_L03_K1","entry":"ISK_L03_K1_001","items":[{"k":"keep","id":"ISK_L03_K1_001","text":"각청이 누구냐고 묻자 나는 대답 대신 그녀의 손목을 보았다. 살아 있다는 사실이 눈앞에 있는데도 손끝으로 다시 확인해야 할 것 같았다. 각청은 그 시선을 따라 자기 팔을 한 번 보더니, 뒤에서 다가오던 병사에게 기다리라고 손짓했다. 익숙한 동작이었다."},{"k":"line","id":"PRO_L03K1_stranger_001","speaker":"나","text":"알아. 닷새 동안 저쪽 천막에 같이 있었어. 내가 자꾸 맥박 재니까 네가 그만 보라고 했고, 비 오던 날엔 둘이 천막 물도 뺐어. 네 신발 젖었잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_002","speaker":"각청","text":"……그 천막이 어딘지는 알아. 네가 말한 일은 기억에 없어. 내가 너를 조사했다면 담당 병사도 있었겠지. 그 사람부터 찾자. 손은 언제 다쳤어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_003","speaker":"","text":"손바닥을 뒤집었다. 산을 오르다 긁힌 자국과 말라붙은 흙. 그녀를 붙들던 손이었고, 놓고 도망쳤던 손이었다. 각청은 병사에게 씻을 물이 있는 곳을 묻고 나에게 길옆의 낮은 자리를 가리켰다. 그 배려마저 익숙해서 앉을 수 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_004","speaker":"나","text":"상처는 나중에. 의례 말해 줘. 모락스의 시신이 떨어졌잖아. 응광이 지시하고, 네가 사람들 물리고. 그것도 기억 안 나?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_005","speaker":"각청","text":"제군의 시신? 의례에 간 건 기억해. 그런 일이 있었으면 내가 지금 여기서 수레나 세고 있겠어? 천천히. 뭘 봤는지부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_006","speaker":"","text":"뒤의 병사도 그날 안내를 맡았다고 했지만 하늘에서 떨어진 거대한 몸은 기억하지 못했다. 다른 참관객을 불러도 답은 같았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_007","speaker":"참관객","text":"사람이 많아서 앞은 안 보였어요. 그런데 그런 일이 났으면 소리라도 들었겠죠. 저는 그냥…… 잠깐 정신이 없었던 것 같은데. 왜 그렇게 보세요? 숨기는 거 없어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_008","speaker":"나","text":"숨겼다고 안 했어요. 다들 그 부분만 없다고 하니까…… 어디에다 대고 말해야 하나 싶어서요.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K1_stranger_009","options":[{"label":"나 못 믿어도 돼. 대신 내가 가리키는 자리까지 같이 가 줘. 없는 일 우긴 거면 돌아오는 길에 나한테 화내도 돼.","id":"PRO_L03K1_stranger_010","items":[{"k":"line","id":"PRO_L03K1_stranger_011","speaker":"각청","text":"없는 일인지 보려고 가는 거야. 화낼 이유를 미리 만들 생각은 없어. 혼자 통제선 넘으면 그 자리 가기도 전에 붙잡혀. 내 옆에서 움직여.","map":"MAP_LIYUE_PLAINS"}]},{"label":"네가 날 기억 못 하는 건 억지로 받아들여 볼게. 그래도 의례장까지 없어지진 않았잖아. 거기서부터 보자.","id":"PRO_L03K1_stranger_012","items":[{"k":"line","id":"PRO_L03K1_stranger_013","speaker":"각청","text":"현장 다시 보자는 데는 동의해. 걷는 동안 물은 마셔. 목소리만 높이면 네 다리가 못 버텨.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L03_K1_016","text":"각청은 신뢰한다는 선언 대신 길을 열었다. 그 뒤를 따르다 천막 끝을 보았다. 비를 빼던 날 접어 둔 천이 여전히 같은 방향으로 말려 있었다. 흔적은 남았는데 사람을 알아보던 눈길만 사라져 있었다."},{"k":"keep","id":"ISK_L03_K1_017","text":"두 사람은 행사 때 이용했던 계단을 다시 올랐다. 각청이 앞서가다 돌아볼 때마다 그녀가 쓰러졌던 순간이 지금의 몸에 겹쳤다. 계단 중간에서 한 번 멈춰 숨을 골랐고, 각청은 재촉하지 않았다."},{"k":"line","id":"PRO_L03K1_empty_001","speaker":"","text":"사람이 쓰러졌던 곳을 먼저 보았다. 제례에 쓴 물건이 정리되어 있었고, 줄은 한쪽으로 걷혀 있었다. 각청을 받쳤던 자리를 찾아 멈췄다가, 시선을 더 안으로 옮겼다. 가장 큰 것이 없었다. 모락스의 시신이 사라져 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_002","speaker":"나","text":"여기 있었잖아. 저기서 떨어져서 이쪽으로. 네가 이 앞에 섰고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_003","speaker":"현장 병사","text":"저희가 넘겨받을 때는 그런 시신이 없었습니다. 큰 물건을 옮겼다는 인계도 없고요. 응광 님께도 전했습니다만, 제군께 그런 일이 있었다는 기억이 없다고 하셨습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_004","speaker":"","text":"응광까지. 그 거대한 몸 앞에서 냉정하게 사람을 움직이던 여자가, 이제는 시신을 옮기라고 했는지조차 말해 줄 수 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_005","speaker":"나","text":"그럼 끝이야? 기억 없고 넘겨받은 것도 없으니까 원래 없었던 걸로?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_006","speaker":"나","text":"저게 주머니에 넣고 갈 물건이야? 사람이 죽고, 너도 죽고, 시신까지 없어졌는데 왜 나만 찾고 있냐고!","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_007","speaker":"","text":"마지막 말은 각청을 향해 튀어나왔다. 소리를 지른 뒤에야 그녀가 한 발도 피하지 않았다는 것을 보았다. 병사가 말리려 팔을 내밀자 각청이 그 앞을 막았다. 살아 돌아온 사람에게 왜 죽었느냐고 따지고 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_008","speaker":"각청","text":"네 말이 맞으면 난 모르는 사이에 죽었다가 지금 여기 서 있는 거겠지. 설명 못 해 주는 건 미안해. 그런데 기억 없다고 나까지 손 놓은 사람으로 만들지는 마. 지금 네 옆에 서 있잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_009","speaker":"나","text":"……알아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_010","speaker":"나","text":"네가 너무 멀쩡해서 화가 나. 미안.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_011","speaker":"각청","text":"화내. 대신 걸으면서 내. 시신이 없어졌으면 옮긴 길이 있어. 기억이 없다고 길까지 없어지진 않아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_012","speaker":"","text":"각청은 곧장 병사 둘을 나누어 보냈다. 큰 몸을 숨길 수 있는 장소, 제군의 힘을 노리고 접근할 사람. 이름 하나가 머릿속을 차갑게 가로질렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_013","speaker":"나","text":"타르탈리아. 우인단 집행관. 그 사람 리월에 와 있지? 황금옥부터 봐야 해.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_014","speaker":"각청","text":"그 이름은 알아. 그런데 왜 그 사람이야? 가져갔다는 목격이 있어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_015","speaker":"나","text":"본 건 아니야. 내가 알던 이야기에서는 그가 황금옥에서 신의 심장을 노려. 거기서 뜻대로 안 되면 일이 바다까지 번져. 다 그 사람 짓이라는 게 아니라, 더 큰 사고가 날 곳을 하나 아는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_031","text":"각청은 황금옥이라는 말에서 옆에 있던 병사를 불렀다. 그때 계단 쪽에서 숨이 찬 목소리가 올라왔다. 감우와 연비였다. 두 사람은 의례장에 없었다. 그러니 기억도 그대로였다."},{"k":"line","id":"PRO_L03K1_adepti_001","speaker":"","text":"돌바닥 위로 긴 그림자가 드리웠다. 바람이 제례용 천을 뒤집었고, 병사들의 시선이 한꺼번에 하늘로 올라갔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_002","speaker":"류운차풍진군","text":"이 몸이 항구의 사정을 살피겠다고 한 것이 그저 자네를 돌려보내려는 말로 들렸나? 돌아오자마자 목이 쉬도록 외쳐 대고 있으니 산에서 쉬게 한 보람이 없군. 자네가 말한 각청이 이 사람인가?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_003","speaker":"","text":"류운차풍진군이 내려앉는 동안 먼 지붕 위로 또 다른 선인의 형체가 멈췄다. 소는 소란의 가운데로 들어오지 않은 채 각청과 나 사이에 시선을 멈췄다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_004","speaker":"나","text":"맞아요. 제 앞에서 죽었는데 지금은 살아 있어요. 시신도 없어졌고, 각청도 응광도 기억 못 한대요. 제가 거짓말한다고 생각하실까 봐…… 아니, 그거 걱정할 때가 아니네요. 타르탈리아가 황금옥에 있을 수 있어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_005","speaker":"류운차풍진군","text":"산에서 들은 말을 이 몸이 잊지 않았네. 자네가 눈앞의 사람을 보고 말을 바꾼 것이 아니라는 뜻이지. 칠성이 제군의 일을 모른다 하니, 이 몸도 당사자에게 직접 물을 말이 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_006","speaker":"각청","text":"응광에게 자리를 마련하라고 전하겠습니다. 다만 선인께서 함께 들으신다는 것과 제가 현장을 확인할 책임은 같이 갑니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_007","speaker":"류운차풍진군","text":"이 몸이 자네에게 손을 놓으라 하였나? 움직일 마음이 있다면 길부터 열게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_008","speaker":"","text":"각청의 눈썹이 움직였지만 그녀는 돌아서서 길을 지시했다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_adepti_009","options":[{"label":"오셨으니까 말씀드리는데, 이 사람은 제 말 안 믿겨도 현장까지 같이 와 줬어요. 저 때문에 서로 화내지 마세요.","id":"PRO_L03K1_adepti_010","items":[{"k":"line","id":"PRO_L03K1_adepti_011","speaker":"류운차풍진군","text":"자네는 목 아끼라는 충고는 들을 생각이 없으면서 남의 언성은 걱정하는군. 좋네. 따질 말은 당사자 앞에서 하겠어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"같이 가 주셔야겠어요. 제가 혼자 모락스의 계획이라는 말을 꺼내면 의자에 앉기도 전에 끌려나올 것 같습니다.","id":"PRO_L03K1_adepti_012","items":[{"k":"line","id":"PRO_L03K1_adepti_013","speaker":"류운차풍진군","text":"산에서는 문밖에 앉을 자리라도 있었지. 여기서는 서서 고함만 지를 작정이었나 보군. 이 몸이 함께 듣겠네. 틀리면 틀렸다고 할 사람도 필요할 테니.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_adepti_014","speaker":"소","text":"네가 서 있던 곳은 내가 보겠다. 바다 쪽도. 너는 살아 있는 사람 붙들고 죽었던 순간만 묻지 마. 그다음에 뭘 할지도 들어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_015","speaker":"나","text":"……알겠어요. 그런데 망서 객잔에서 하신 말이 아직 걸려요. 지금도 제가 사람들하고 같이 있어도 되는 겁니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_016","speaker":"소","text":"답할 단서는 아직 없다. 그래서 보고 있는 거야. 두려워서 혼자 움직이다 죽을 이유도 없다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_017","speaker":"","text":"소는 더 설명하지 않고 현장 바깥으로 움직였다. 나를 무해하다고 선언한 것은 아니었다. 그래도 혼자 사라지지 말라는 말은 들었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_049","text":"군옥각으로 향하는 동안 각청은 먼저 보낸 병사들의 보고를 받았다. 황금옥 쪽에 우인단이 드나든 흔적이 있고, 안쪽과 연락이 원활하지 않다는 소식이었다. 군옥각에 오른 뒤, 나는 아래로 멀어지는 거리보다 문 안에서 기다리는 사람을 먼저 보았다."},{"k":"line","id":"PRO_L03K1_palace_001","speaker":"","text":"응광은 긴 탁자 곁에 서 있었다. 손님용 잔과 항구 지도가 함께 놓여 있었다. 그녀의 눈길이 내 흙 묻은 신발, 갈라진 입술, 선인 앞에서도 물러서지 않는 각청을 차례로 훑었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_002","speaker":"응광","text":"며칠 바깥에서 기다리던 손님이 선인들을 데리고 올라올 줄은 몰랐네. 나한테 따로 할 말이 있었다지? 들을 사람은 다 모였어. 급한 것부터.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_003","speaker":"나","text":"먼저 확인할게요. 의례에서 모락스의 시신이 떨어졌고, 당신은 사람들을 물린 다음 현장을 떠났어요. 저는 각청한테 당신을 만나게 해 달라고 했고요. 하나도 기억 안 나세요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_004","speaker":"응광","text":"의례를 준비하고 올라간 건 기억해. 네가 말하는 제군의 죽음은 없어. 자리를 떠난 뒤 누구에게 뭘 맡겼는지 물으면, 그 사이가 분명하지 않아. 마음에 안 드는 대답이겠지만 없는 기억을 만들어 줄 수는 없잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_005","speaker":"류운차풍진군","text":"제군께 일이 생겼다는 증언을 이 몸이 들었고 다른 선인들에게도 전했네. 그런데 와 보니 제군의 몸은 없고, 칠성마저 당시를 기억하지 못한다 하는군. 이 일을 장부 한 장 빠진 정도로 취급할 수는 없어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_006","speaker":"응광","text":"가볍게 봤으면 지도를 펴 두지 않았겠죠. 기억이 없다는 말과 손을 놓았다는 말은 달라요. 지금도 이동로와 황금옥을 확인하고 있어요. 바다와 항구 밖은 선인들께서 봐 주실 수 있겠죠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_007","speaker":"나","text":"그래서 말씀드려요. 제가 알고 있던 이야기에서 이건 모락스의 계획이었어요. 죽은 모습을 보이고, 자기 없는 리월이 어떻게 버티는지 보려는 계획. 타르탈리아가 신의 심장을 찾아 황금옥으로 가고, 결국 오셀이 나타납니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_008","speaker":"","text":"잔을 옮기던 사람의 손이 멈췄다. 이름 하나가 방의 무게를 바꾸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_009","speaker":"응광","text":"제군의 계획을 안다는 말은 가벼운 패가 아니야. 그분이 직접 알려 줬어? 아니면 네가 본다는 그 이야기에, 지금 이 방 사람들의 결정까지 적혀 있었니?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_010","speaker":"나","text":"직접 들은 적은 없어요. 다른 세계에서 이곳의 일을 이야기로 봤습니다. 그런데 이번에는 사람들까지 죽었어요. 제가 알던 계획에 그런 건 없었습니다. 그것까지 모락스가 했다고 우기는 게 아니라, 제가 아는 다음 위험을 말하는 거예요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_011","speaker":"각청","text":"앞에서 맞는 게 있었다고 뒤를 전부 믿을 순 없어. 그래도 대비 안 할 이유도 없지. 네가 아는 거, 바다랑 타르탈리아 막는 데 도움이 돼?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_012","speaker":"","text":"군옥각의 안쪽을 보았다. 멀리서는 거대한 이야기 속 무대였지만 지금은 누군가 오래 모은 물건들이 놓인 집이었다. 그것을 잃으라고 말할 차례가 다가오자, 머릿속에서 쉬웠던 공략이 갑자기 남의 삶을 처분하는 말이 되었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_013","speaker":"나","text":"오셀이 정말 나오고 제가 아는 대로 흘러가면…… 이 군옥각을 포기해야 합니다. 바다에 떨어뜨려서 막는 거예요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_014","speaker":"나","text":"당신이 이걸 얼마나 아끼는지 알아요. 그래서 돌려 말하고 싶지 않아요. 당신 집을 잃는 이야기입니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_015","speaker":"응광","text":"내 집을 얼마나 아끼는지 안다는 손님이, 처음 올라온 자리에서 버리라고 권하네. 재미있는 방문이야. 그런데 넌 지금 내 결정을 알려 주는 거니, 아니면 그 상황을 막아 달라는 거니? 둘은 값이 많이 달라.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_palace_016","options":[{"label":"막을 수 있으면 막고 싶어요. 그래서 황금옥으로 가겠다는 거고요. 제가 못 막으면, 아무 준비 없이 그 순간을 맞게 하고 싶지 않아요.","id":"PRO_L03K1_palace_017","items":[{"k":"line","id":"PRO_L03K1_palace_018","speaker":"응광","text":"그럼 순서가 바뀌었네. 나는 지금 군옥각을 버리기로 결정하지 않아. 먼저 바다를 늦추고, 해안의 사람을 물리고, 이곳을 어떻게 쓸지 계산할 거야. 마지막에 내놓아야 하면 그때 내가 결정해. 네 기억 속 장면에 맞추려고 미리 지붕을 떼어 버릴 생각은 없어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"제가 기억하는 결말은 경고로만 받아 주세요. 재현하자는 게 아니에요. 해안 사람들을 먼저 옮길 수 있는지 봐 주세요.","id":"PRO_L03K1_palace_019","items":[{"k":"line","id":"PRO_L03K1_palace_020","speaker":"응광","text":"경고와 결정은 구분하지. 네가 알려 준 위험을 지금 이곳의 조건으로 다시 계산할 거야. 언제 포기할지는 내가 판단해. 누구 이야기 속 장면을 완성하려고 버리지는 않아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_palace_021","speaker":"류운차풍진군","text":"그 판단에 선인들의 힘도 계산해 넣게. 인간의 건물 하나를 떨어뜨릴 때까지 구경만 할 셈으로 온 것이 아니니.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_022","speaker":"각청","text":"해안부터 움직이겠습니다. 선인들이 바다를 맡아 주시면 안쪽 통로는 제가 열겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_023","speaker":"","text":"논쟁이 끝났다는 선언은 없었지만 할 일이 갈라졌다. 내 말이 받아들여지면 홀가분할 줄 알았다. 실제로는 내 말 때문에 사람들이 움직이기 시작한 것이 더 무거웠다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_palace_024","options":[{"label":"한 가지만요. 제가 안 돌아오더라도 황금옥은 꼭 한 번 더 봐 주세요. 소식 끊긴 사람이 또 생기면, 이번에도 저 혼자 기억하는 일로 끝날 것 같아서요.","id":"PRO_L03K1_palace_025","items":[{"k":"line","id":"PRO_L03K1_palace_026","speaker":"응광","text":"안 돌아올 생각부터 하고 나가는 손님은 대접하기 어렵지. 바깥 연락선은 남겨 둘게. 돌아와서 직접 보고하는 편이 나한테도 훨씬 값진 일이야.","map":"MAP_LIYUE_HARBOR"}]},{"label":"군옥각 지키면 나중에 여기서 밥 한 번 먹어도 됩니까? 돌아올 핑계가 하나쯤 있으면 좋겠어요.","id":"PRO_L03K1_palace_027","items":[{"k":"line","id":"PRO_L03K1_palace_028","speaker":"응광","text":"이 방까지 와서 밥값부터 걱정하는 사람은 드문 편이야. 식탁을 차릴 만큼 시간이 남도록 만드는 게 먼저겠지. 그때 메뉴는 내가 고를게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_palace_029","speaker":"나","text":"그럼 저는 타르탈리아 막으러 갈게요. 제군의 시신이 거기 있는지도 보고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_030","speaker":"응광","text":"병사들이 바깥까지 안내할 거야. 네가 알던 상대만 만나리라고 기대하지 마. 지금 네 이야기에서 가장 확실해 보이는 것조차 이미 여러 번 달라졌으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_078","text":"그 말은 내가 나 자신에게 해 주지 못했던 충고였다. 잔에 남은 물을 다 마셨다. 군옥각을 희생해야 한다는 말을 들은 직후에도 응광의 손은 흔들리지 않았다. 대신 창밖을 보는 시간이 아주 잠깐 길어졌다."},{"k":"keep","id":"ISK_L03_K1_079","text":"군옥각을 내려와 길을 나누는 곳에서 각청이 나를 잠깐 세웠다. 앞서 보낸 병사가 황금옥의 안쪽 문이 제대로 열리지 않는다고 보고하고 있었다. 서둘러 걸음을 옮기려다 각청이 내민 물통을 보고 멈췄다."},{"k":"line","id":"PRO_L03K1_water_001","speaker":"각청","text":"마시고 돌려줘. 가는 길에 쓰러지면 네가 하겠다는 일 아무도 못 이어받아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_002","speaker":"나","text":"……말하는 건 진짜 그대로네. 기억만 없는 게 이렇게 서운할 줄 몰랐다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_003","speaker":"나","text":"나중에 생각나면, 내가 천막 당기는 힘 조절은 좀 나아졌다고 해 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_004","speaker":"각청","text":"기억 안 나는 걸 기억난다고 약속은 못 해. 대신 네가 돌아오는 건 기다릴 수 있어. 네가 봤다는 나하고 지금의 나를 자꾸 시합시키지 마. 둘 다 나야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_005","speaker":"나","text":"……알았어. 물통은 돌려줄게. 그건 기억해 둬.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_006","speaker":"각청","text":"그건 기억해. 비싼 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_007","speaker":"","text":"물통을 돌려주며 처음으로 그녀의 얼굴을 제대로 보았다. 죽어 있던 얼굴과 겹쳐 보지 않고, 지금 나에게 화를 내지 않으려 애쓰는 사람을 보았다. 각청은 곧 해안 쪽으로 돌아섰다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_084","text":"황금옥 방면 통행은 별도로 허가되었다. 호위 병사들은 길목의 수레를 다른 곳으로 돌리고, 안쪽에 남은 일꾼을 데리고 나오기 위해 연락을 이어 갔다. 나에게 열린 길은 위험이 보고된 건물로 가는 길 하나였고, 그 사실이 이상할 만큼 마음을 단순하게 만들었다."},{"k":"keep","id":"ISK_L03_K1_085","text":"언덕 쪽으로 오르는 동안 손가락을 펴고 오므렸다. 무기를 쥘 때 갈라진 곳이 당겼지만 손목은 움직였다. 황금빛 건물이 가까워질수록 안에서는 아무 소리도 들리지 않았다. 그 고요를 의례장의 고요와 같은 것으로 만들지 않으려고, 발밑의 자갈 소리에 귀를 기울였다."},{"k":"line","id":"PRO_L03K1_golden_001","speaker":"","text":"황금옥 외부에서는 마지막 일꾼 둘이 병사의 부축을 받아 나오고 있었다. 안쪽 통로에서 큰 소리가 난 뒤 문짝 하나가 비틀렸고, 관리 구역을 거쳐 돌아 나왔다는 설명이었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_002","speaker":"","text":"그리고 그 통로 앞에 회색 외투가 둘 서 있었다. 우인단. 일꾼들을 내보내 준 게 아니라, 들어갈 사람을 고르고 있었던 것이다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_003","speaker":"우인단 병사","text":"여기서부터는 집행관의 영역이다. 돌아가.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_004","speaker":"나","text":"저 집행관한테 할 말 있어서 왔는데요. 약속은 안 했지만.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_005","speaker":"우인단 병사","text":"약속 없는 손님은 받지 않는다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_006","speaker":"나","text":"그쪽도 리월에 약속하고 온 건 아니잖아요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_007","speaker":"","text":"대답 대신 얼음이 튀었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"combat","id":"PRO_L03K1_golden_008","group":"EG_FATUI_PATROL","text":"황금옥 관리 통로를 막은 우인단 전투조. 안으로 들어가려면 뚫어야 한다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_009","speaker":"","text":"마지막 병사가 무릎을 꿇었다. 호위 병사들이 달려와 그를 끌어냈다. 통로는 비어 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_010","speaker":"나","text":"저는 저 통로로 들어갈게요. 안에 있는 사람이 나오면 붙잡으려고 몰려들지 마세요. 타르탈리아면 출구 막는 쪽이 더 위험해요. 사람들 먼저 멀리 보내고, 제가 나오면 이쪽이 비어 있게 해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_011","speaker":"호위 병사","text":"무작정 쫓아가진 않겠습니다. 대신 방향을 바꾸시면 소리를 내십시오. 출구를 비우는 것과 당신이 어디 있는지 모르게 되는 건 다른 일입니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_089","text":"틈을 지나 안으로 들어갔다. 천장과 기둥 사이의 먼지가 아주 가늘게 떠 있었다. 모락스의 시신은 보이지 않았다. 그보다 먼저, 넓은 공간 한가운데 서 있는 붉은 머리의 남자가 눈에 들어왔다. 타르탈리아였다."},{"k":"line","id":"PRO_L03K1_golden_012","speaker":"타르탈리아","text":"오는 데 시간이 걸렸네. 길을 못 찾은 건 아닐 테고, 만나고 싶은 사람이 많았나 봐. 여기까지 왔으니 할 말은 있겠지?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_013","speaker":"","text":"말투는 가벼웠다. 그 뒤에 당연히 따라올 호기심을 기다렸다. 어디서 왔는지, 얼마나 싸울 수 있는지. 그러나 타르탈리아의 시선은 내 얼굴, 손, 문, 다시 얼굴 순으로 움직였다. 사람을 반기는 눈길인지, 무언가가 도착했는지 살피는 눈길인지 알 수 없었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K1_golden_014","options":[{"label":"시신부터 내놔. 네가 가져갔다면 어디 있는지 말하고, 아니라면 뭘 하러 왔는지 말해.","id":"PRO_L03K1_golden_015","items":[{"k":"line","id":"PRO_L03K1_golden_016","speaker":"타르탈리아","text":"빈자리를 보고 바로 나를 찾아왔군. 네가 찾는 게 원래 여기 있었는지는 확인했어? 아니면 내가 여기 있어야 한다고 생각해서 온 건가?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"네가 여기 있다는 것과 시신을 옮겼다는 건 따로 묻겠어. 뭘 찾으러 왔고, 도착했을 때 여기엔 뭐가 있었지?","id":"PRO_L03K1_golden_017","items":[{"k":"line","id":"PRO_L03K1_golden_018","speaker":"타르탈리아","text":"내가 여기 있다는 이유만으로 빈칸을 다 채우지는 않겠다는 건가. 그럼 네가 확인한 것부터 따져 보자고. 내가 여기 있어야 한다고 생각해서 온 거잖아?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K1_golden_019","speaker":"나","text":"질문으로 되받는 솜씨는 알겠는데 칭찬해 줄 여유는 없어. 신의 심장 찾으러 왔으면 그만둬. 못 얻었다고 바다 쪽으로 일 벌일 생각도 말고.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_020","speaker":"","text":"타르탈리아의 입가에 엷은 웃음이 걸렸다. 예상한 말을 들은 사람처럼 놀라지 않는 반응이 등을 서늘하게 했다. 눈앞의 남자는 신의 심장이라는 말보다 내가 어디까지 다가왔는지에 더 관심이 있는 것처럼 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_021","speaker":"타르탈리아","text":"내가 뭘 할지 많이 생각했구나. 그러고도 혼자 이 앞까지 들어왔어. 바깥 사람들을 물린 건 잘했어.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_022","speaker":"나","text":"보통 그런 말은 부하들 상태부터 보고 하지 않나? 밖에 네 사람들 쓰러져 있는데.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_023","speaker":"타르탈리아","text":"지금 내 앞에 있는 건 너잖아. 싸우러 왔으면 움직여. 네가 어디서 멈추는지 보고 싶네.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_024","speaker":"","text":"무기를 고쳐 쥐었다. 기억 속 타르탈리아라면 그 말에 자신이 먼저 들떠 있을 것 같았다. 눈앞의 남자는 웃고 있었지만 재촉하지 않았다. 시작보다 끝에 관심이 있는 사람처럼 기다렸다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K1_golden_025","options":[{"label":"어디서 멈추는지 궁금하면 네 발부터 움직여. 밖에서 기다리는 사람들 있으니까 오래 끌 생각은 없어.","id":"PRO_L03K1_golden_026","items":[{"k":"line","id":"PRO_L03K1_golden_027","speaker":"타르탈리아","text":"기다리는 사람. 그래, 돌아가야 할 이유가 있겠지. 그 이유만큼 움직여 봐.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"내가 아는 너는 싸움 앞에서 그렇게 심심한 얼굴 안 했어. 기분이 나쁜 건지 원래 이랬던 건지 모르겠지만, 확인할 시간도 없네.","id":"PRO_L03K1_golden_028","items":[{"k":"line","id":"PRO_L03K1_golden_029","speaker":"타르탈리아","text":"사람을 안다는 자신감은 편리하지. 처음 보는 내 표정보다 네 기억을 먼저 믿게 해 주니까. 가까이 와서 확인하면 더 빨리 끝나겠네.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K1_golden_030","speaker":"","text":"물이 칼날의 모양으로 빛났다. 반사적으로 몸을 옆으로 던졌고, 뒤의 돌에 날카로운 자국이 생겼다. 첫 공격은 대화를 이어 갈 틈을 잘라 냈다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_107","text":"황금옥 내부에서 타르탈리아와의 전투가 시작된다."},{"k":"line","id":"PRO_L03K1_golden_031","speaker":"","text":"기둥 뒤로 물러났을 때 발밑의 돌판이 내려앉았다. 타르탈리아가 따라 들어오다 자세를 낮췄다. 손아귀가 풀려 무기를 놓칠 뻔했다. 그래도 밖으로 이어지는 길을 그냥 내줄 수는 없었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_032","speaker":"나","text":"여기서 끝내. 바다도, 밖의 사람들도 건드리지 마.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_033","speaker":"","text":"타르탈리아가 고개를 들었다. 다음 공격을 준비하는 대신 내 어깨 너머를 보았다. 그 시선이 어디에 닿았는지 확인하지 못했다. 승기를 붙잡았다고 생각한 바로 그 순간, 발밑에서 낮은 파열음이 났다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_034","speaker":"","text":"바닥의 금이 발끝을 지나 기둥 아래로 달렸다. 위에서 먼저 먼지가 쏟아지고, 이어 돌을 잇던 구조물이 굉음과 함께 어긋났다. 출구 쪽으로 몸을 틀었다. 늦었다. 무너져 내리는 들보가 시야를 가렸고, 틈 너머로 보이던 타르탈리아의 모습도 먼지 속에 사라졌다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_035","speaker":"나","text":"밖으로 물러나요! 문 앞에 서 있지 말고, 멀리—!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_113","text":"외침은 건물이 내려앉는 소리에 묻혔다. 충격이 어깨와 등을 차례로 때렸다. 쏟아진 돌과 들보가 몸을 눌렀다. 빛이 가늘어졌다. 황금옥이 무너졌고, 나는 그 아래에 깔렸다."},{"k":"keep","id":"ISK_L03_K1_END","text":"황금옥 잔해가 나를 덮친 순간에서 멈춘다. 구조 여부와 부상 상태는 아직 밝혀지지 않는다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_0","text":"각청 님, 고운각에서 가져온 보고와 같은 배가 다시 보였답니다. 경계대를 더 보내고 있어요. 그리고…… 이분. 공고를 들고 저를 찾아오셨던 분이에요. 며칠 전에 저와 함께 고운각에 가셨어요."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_1","text":"……네가 이 사람을 알아? 감우, 그 보고 찾은 게 언제야. 황금옥 확인하고 해안 경계도 같이 진행해. 하나 끝날 때까지 기다리지 말고."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_2","text":"회수한 원본은 여기 있어. 이 사람 이름도 적혀 있지. 각청, 네가 기억 못 하는 건 네 잘못이 아니지만, 이 사람이 거짓말을 한 것도 아니야."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_3","text":"……두 사람이 기억하고 있을 줄은 몰랐어. 그 보고 못 찾았으면 또 나만 아는 얘기로 끝났겠네. 고마워. 진짜로."}]},{"id":"ISK_L03_K2","entry":"ISK_L03_K2_001","items":[{"k":"keep","id":"ISK_L03_K2_001","text":"각청이 누구냐고 묻는 동안 나는 그녀의 등 뒤로 시선을 보냈다. 포대를 올려 두던 자리, 손바닥으로 허리를 두드리던 짐꾼의 모습이 차례로 떠올랐다. 각청이 살아 있다면 그 사람도 있을 수 있었다. 반가움이 생기기도 전에 몸이 먼저 움직였다."},{"k":"line","id":"PRO_L03K2_stranger_001","speaker":"나","text":"……각청? 너, 살아 있었어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_002","speaker":"각청","text":"네가 누군지는 모르겠는데, 다짜고짜 살아 있었냐니. 칠성한테 하는 인사치곤 꽤 무례한걸?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_003","speaker":"나","text":"진짜 기억 안 나? 끈 풀린 포대. 같이 봤잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_004","speaker":"각청","text":"그 포대 일은 알아. 그런데 너랑 같이 있었다고? ……우선 무슨 일인지부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_005","speaker":"","text":"낯선 사람을 보는 눈빛에 다가가던 발이 멎었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_006","speaker":"나","text":"그럼 그 짐꾼은? 허리 아프다던 분. 나랑 같이 있었잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_007","speaker":"각청","text":"허리 아픈 짐꾼? 이 근처에서 본 기억은 없는데. 그 사람을 찾는 거야?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_008","speaker":"나","text":"응. 이름은 못 들었어. 얼굴은 알아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_009","speaker":"각청","text":"그럼 마지막으로 본 곳부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_010","speaker":"나","text":"의례장. 모락스의 시신이 떨어지고…… 사람들이 전부 쓰러졌어. 너도, 그 사람도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_011","speaker":"각청","text":"……제군의 시신이 떨어졌다고? 그런 건 기억에 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_012","speaker":"나","text":"데리고 나오려고 했는데 못 했어. 네가 살아 있으니까, 그분도 혹시……","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K2_stranger_013","options":[{"label":"그분이 돌아왔는지 같이 찾아봐 줘.","id":"PRO_L03K2_stranger_014","items":[{"k":"line","id":"PRO_L03K2_stranger_015","speaker":"각청","text":"알겠어. 짐 맡겨 둔 곳으로 가자. 거기 병사라면 알 수도 있어.","map":"MAP_LIYUE_PLAINS"}]},{"label":"나부터 기억해 달라는 게 아니야. 그분만 찾아 주면 돼.","id":"PRO_L03K2_stranger_016","items":[{"k":"line","id":"PRO_L03K2_stranger_017","speaker":"각청","text":"널 기억 못 한다고 안 찾아 줄 것 같아? 가자.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L03K2_stranger_018","speaker":"","text":"각청이 앞장서 수레 사이로 길을 잡았다. 맡겨 둔 짐은 그대로였지만 그 곁에 짐꾼은 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_019","speaker":"각청","text":"이 사람과 같이 왔던 짐꾼, 어디 있는지 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_020","speaker":"검수 병사","text":"아, 그때 그분이군요. 두 분이 함께 계셨던 건 기억합니다. 짐도 여기 있고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_021","speaker":"나","text":"그럼 그분은요? 돌아온 거 봤어요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_022","speaker":"검수 병사","text":"자리를 비우신 건 아는데…… 돌아오셨는지는 기억이 안 납니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_023","speaker":"각청","text":"의례장에 다녀온 사람도 불러 줘. 제군의 시신이 떨어졌다는 말을 들은 적 있는지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_024","speaker":"","text":"병사가 불러온 두 사람도 고개를 저었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_025","speaker":"나","text":"짐은 여기 있는데. 사람만 어디로……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_026","speaker":"각청","text":"마지막으로 본 자리가 남았잖아. 같이 갈게.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K2_stranger_027","options":[{"label":"그분 짐 잠깐 맡아 달라고만 해 줘. 돌아올 사람이 살아 있다면, 남의 짐까지 없어져 있으면 안 되잖아.","id":"PRO_L03K2_stranger_028","items":[{"k":"line","id":"PRO_L03K2_stranger_029","speaker":"각청","text":"원래도 인계가 안 끝난 물건이야. 주인 확인 없이 안 옮기게 해 둘게. 가자.","map":"MAP_LIYUE_PLAINS"}]},{"label":"그분이 오면 내가 찾았다고 말해 줘. 이름도 모르면서 아는 척하는 사람 있었다고.","id":"PRO_L03K2_stranger_030","items":[{"k":"line","id":"PRO_L03K2_stranger_031","speaker":"각청","text":"그렇게는 안 전해. 함께 의례에 갔던 사람이 돌아와 찾고 있다고 할 거야. 네가 싫어할 말을 굳이 보탤 필요는 없잖아.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L03_K2_017","text":"짐이 놓인 곳을 마지막으로 보았다. 남겨 둔 물건이 기다리는 사람을 증명해 주지는 않았지만, 돌아와 다시 일할 자리가 있다는 것만은 지우고 싶지 않았다. 돌아갈 곳은 그 사람을 두고 온 의례장이었다."},{"k":"keep","id":"ISK_L03_K2_018","text":"옥경대로 올라가는 동안 각청에게 온 전갈은 상황을 더 이상하게 만들었다. 응광도 제군의 죽음을 기억하지 못했다. 병사의 말을 끊지 않으려고 턱에 힘을 주었다. 그 힘이 풀리면 다시 소리를 지르게 될 것 같았다."},{"k":"line","id":"PRO_L03K2_empty_001","speaker":"","text":"도착하자마자 짐꾼이 쓰러졌던 곳으로 갔다. 짐꾼도, 모락스의 거대한 몸도 보이지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_002","speaker":"나","text":"없어? 분명히 저기 있었잖아. 누가 옮긴 거야!","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_003","speaker":"현장 병사","text":"옮기라는 명령도, 인계받은 곳도 찾지 못했습니다. 여기 남은 사람들도 본 적이 없다고 합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_004","speaker":"각청","text":"남은 사람만 물어본 거야? 그날 일하고 돌아간 사람들도 찾아봐.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_005","speaker":"나","text":"그 짐꾼도…… 없어. 여기엔 있을 줄 알았는데.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_006","speaker":"","text":"짐꾼을 끌어안았던 팔이 떨렸다. 각청이 병사에게 잠시 기다리라는 손짓을 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_007","speaker":"나","text":"내가 여기 두고 갔어. 조금만 더 끌어 봤으면……","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_008","speaker":"각청","text":"그건 모르는 일이잖아. 어디까지 옮겼는지 보여 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_009","speaker":"나","text":"……여기. 돌아오면 같이 짐 확인하자고 했는데.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_010","speaker":"","text":"각청이 몸을 낮춰 살폈다. 끌고 왔다는 방향까지 확인하고 병사를 불렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_011","speaker":"각청","text":"부두 검수 병사에게 사람 보내. 맡겨 둔 짐으로 신원 알아보고, 같이 일한 사람들도 찾아. 부상자 옮긴 곳도.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_012","speaker":"나","text":"이름도 못 들었어. 얼굴은 알아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_013","speaker":"각청","text":"그럼 넌 얼굴을 봐 줘. 이름은 검수 병사한테 물으면 돼. 방법이 없는 게 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_014","speaker":"","text":"병사를 보낸 각청은 내 곁에 남았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_015","speaker":"나","text":"……도와주는 거야? 내 말이 맞는지도 모르면서?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_016","speaker":"각청","text":"그러니까 확인하는 거야. 기억 안 난다고 네가 틀린 건 아니잖아. 사람 사라졌다는 말을 그냥 넘기는 칠성이 어디 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_017","speaker":"나","text":"찾으면 꼭 알려 줘. 다쳤으면 내가 갈게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_018","speaker":"각청","text":"알았어. 그때까진 내 옆에 있어. 지금 혼자 뛰어다닐 상태 아니야. 너 지금 서 있는 것도 비뚤어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_019","speaker":"","text":"각청은 보폭을 늦춰 걸음을 맞추고, 남은 병사에게 의례장 밖을 가리켰다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_020","speaker":"각청","text":"제군의 몸을 옮긴 흔적도 찾아봐. 큰 수레가 나갈 만한 길부터.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_021","speaker":"","text":"각청이 짚은 길을 보다가, 내가 알던 이야기에서 제군의 몸을 옮겨 두었던 곳이 떠올랐다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_empty_022","options":[{"label":"타르탈리아야. 저걸 가져가는 걸 본 건 아닌데…… 그 사람이 황금옥으로 가. 신의 심장을 찾으러. 응광을 만나야겠어. 이번에는 진짜로.","id":"PRO_L03K2_empty_023","items":[{"k":"line","id":"PRO_L03K2_empty_024","speaker":"각청","text":"우인단 집행관. 황금옥은 살피게 할게. 그런데 왜 그렇게 예상하는지는 설명해야 해. 이름 하나로 응광 앞에 세울 순 없어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"황금옥부터 확인해 줘. 내가 아는 이야기대로면 타르탈리아가 신의 심장을 찾으러 갈 수 있어. 시신 옮긴 걸 봤다는 건 아니야.","id":"PRO_L03K2_empty_025","items":[{"k":"line","id":"PRO_L03K2_empty_026","speaker":"각청","text":"예상이랑 목격을 나눈 건 알겠어. 황금옥은 살피게 할게. 근거는 응광 앞에서 설명해.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_empty_027","speaker":"나","text":"설명할게. 모락스의 계획하고, 그 뒤에 일어날 일을 알아. 산에 가서 류운차풍진군한테도 먼저 말했어. 그분한테 확인하면 돼. 이번에는 나만 기억하는 말이 아닐 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_030","text":"각청이 병사를 보내는 사이, 계단 아래에서 숨 가쁜 발소리가 올라왔다. 행추와 연비였다. 두 사람은 의례장에 없었다. 그러니 기억도 그대로였다."},{"k":"line","id":"PRO_L03K2_adepti_001","speaker":"","text":"그 순간 공기가 달라졌다. 병사들이 한꺼번에 자세를 바로잡았고, 높은 곳에 선 그림자가 내려왔다. 류운차풍진군이었다. 산의 문밖에서 목이 쉬도록 불렀던 상대가 이번에는 먼저 찾아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_002","speaker":"류운차풍진군","text":"이 몸에게 확인하면 된다더니, 정작 이 몸이 와도 인사할 숨은 남겨 두지 않았군. 자네가 말한 사람들 가운데 이 여인이 있었지?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_003","speaker":"나","text":"네. 살아 있어요. 그런데 저를 기억 못 하고, 응광도 모락스가 쓰러진 걸 기억 못 한답니다. 시신은 없어졌고요. 같이 갔던 짐꾼은 아직 못 찾았어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_004","speaker":"류운차풍진군","text":"살아 있는 사람을 보고 다른 살아 있을 사람을 찾는 것이 잘못은 아니지. 다만 이 몸도 없는 사람을 이 자리에 곧장 데려다줄 수는 없네. 제군께 관한 일은 칠성과 직접 이야기하겠네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_005","speaker":"","text":"선인들을 보며 처음으로 산길에서 한 일이 헛되지 않았다는 것을 실감했다. 짐꾼을 데려오지 못했지만 이야기는 전달했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_006","speaker":"각청","text":"자리를 마련하겠습니다. 황금옥에도 사람을 보냈고요. 확인되지 않은 일을 확인된 것처럼 말씀드릴 수는 없지만, 없는 기억을 핑계로 기다리고 있지는 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_007","speaker":"류운차풍진군","text":"그 마음가짐은 좋네. 그렇다면 길을 여는 데 오래 걸릴 이유도 없겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_008","speaker":"","text":"소는 선인들 뒤에서 나를 잠깐 살폈다. 망서 객잔에서와 같은 간결한 눈길이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_009","speaker":"나","text":"황금옥에 가려면 응광을 먼저 만나야겠어요. 바다 쪽도 함께 봐 주실 수 있습니까? 제가 타르탈리아 막는 동안 다른 쪽이 먼저 터지면 저 혼자 뛰어간 의미가 없어져요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_010","speaker":"소","text":"바다는 우리가 보겠다. 네가 안다는 상대에게만 눈을 두지 마. 도망칠 길이 막혔는지도 봐라. 사람 하나 더 두고 돌아왔다고 후회할 필요는 없으니.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_adepti_011","options":[{"label":"사람 하나 더는 저 말씀이시죠? 다들 저를 배달할 짐처럼 다루시는데, 솔직히 지금은 안내가 있는 쪽이 좋습니다.","id":"PRO_L03K2_adepti_012","items":[{"k":"line","id":"PRO_L03K2_adepti_013","speaker":"류운차풍진군","text":"자네는 짐짝이라는 비유를 좀처럼 놓지 못하는군. 그 짐은 말이 너무 많다는 흠도 있겠어. 따라오게. 다리가 풀리면 허세 부리지 말고 멈췄다고 말하고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"제가 먼저 말을 꺼내겠습니다. 응광이 화를 내면 중간에서 들어만 주세요. 혼자 우기는 사람으로 끝내고 싶지 않습니다.","id":"PRO_L03K2_adepti_014","items":[{"k":"line","id":"PRO_L03K2_adepti_015","speaker":"류운차풍진군","text":"화내는 사람 하나 견디지 못하면서 제군의 계획을 논하러 갈 셈인가. 말할 것은 말하게. 이 몸이 들은 부분은 이 몸이 대답할 테니.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_adepti_016","speaker":"","text":"응광의 답은 오래 걸리지 않았다. 그사이 황금옥으로 보낸 병사가 되돌아와 안쪽 연락이 끊기고 우인단이 드나들었다고 보고했다. 각청은 즉시 대피와 외곽 통제를 지시했다. 내가 짐작하던 장소가 실제로 문제가 벌어진 장소가 되어 가고 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_047","text":"군옥각으로 이동하는 동안 아래쪽의 물자 대기 구역을 찾았다. 멀리서는 수레도 포대도 구별되지 않았다. 누군가의 하루를 닷새나 묶어 둔 짐이 이 높이에서는 점 하나도 되지 않는다는 사실이 마음에 들지 않았다. 응광에게 말할 때 그 사람을 큰 계획의 작은 피해로 줄여 부르지 않기로 했다."},{"k":"line","id":"PRO_L03K2_palace_001","speaker":"","text":"응광은 내가 앉을 의자를 미리 비워 두었다. 흙 묻은 옷 때문에 망설이자 그녀는 손으로 자리를 가리켰다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_002","speaker":"응광","text":"내 앞에 오기 위해 먼저 산을 다녀온 손님이네. 평소라면 기다린 값부터 물었을 텐데 오늘은 시간이 없겠지. 제군 일과 황금옥 일, 모두 네가 꺼낸 이야기라고 들었어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_003","speaker":"나","text":"그 전에 직접 물을게요. 의례에서 모락스의 시신이 떨어진 거, 정말 기억이 없습니까? 당신이 떠난 뒤에 사람들이 죽었어요. 저하고 같이 온 짐꾼도요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_004","speaker":"응광","text":"기억에 없어. 그 시간이 매끄럽게 이어지지 않는다는 건 나도 알아. 함께 간 이의 행방은 찾았니?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_005","speaker":"나","text":"아직요. 짐만 그대로 있어요. 그러니까 지금부터 하는 말이 맞든 틀리든 그분 찾는 일도 계속해 주세요. 큰일 앞에서 작은 일 됐다고 넘어가지 말고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_006","speaker":"응광","text":"사람 하나를 찾는 일과 항구를 지키는 일은 서로 깎아야 값이 맞는 거래가 아니야. 각청이 이미 사람을 붙였다고 들었어. 보고는 계속 받겠어. 이제 네가 여기까지 와서 하려던 말을 들어 보자.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_007","speaker":"","text":"찾았다는 약속도 위로도 아니었다. 그러나 처음으로 내 부탁을 손에서 놓을 수 있었다. 누군가가 계속 들고 있겠다고 말했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_008","speaker":"나","text":"제가 알고 있던 이야기에서 모락스의 죽음은 계획이었습니다. 리월이 제군 없이 설 수 있는지 보기 위한 거였어요. 타르탈리아가 황금옥에서 신의 심장을 찾고, 뜻대로 되지 않으면 오셀을 불러옵니다. 저는 그걸 막으려고 해요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_009","speaker":"각청","text":"제군이 우리를 시험한다는 뜻이야? 기억이 끊겨서 누구 말을 믿을지도 흔들리는 사람들이 있어. 그 고통까지 계획이라면 못 받아들여.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_010","speaker":"나","text":"그건 아니야. 내가 알던 이야기엔 기억상실도, 사람들이 죽는 일도 없었어. 그래서 나도 화가 나. 아는 줄 알고 왔는데, 그 사이에서 사람이 죽었는데, 큰 계획이 있겠지 하고 기다릴 순 없잖아. 아는 위험이라도 먼저 막자는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_011","speaker":"류운차풍진군","text":"산에서도 그와 같이 말했네. 제군의 계획이라는 말과 자신이 설명하지 못하는 참사를 나누어 이야기했지. 이 몸이 그 해석을 모두 받아들였다는 뜻은 아니네. 허나 오셀을 경계하라는 말을 듣고도 손 놓고 있을 이유는 없었어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_012","speaker":"응광","text":"내가 궁금한 건 네가 왜 그 이야기의 다음 일을 믿느냐는 거야. 앞에서 틀린 게 이렇게 많았다면 타르탈리아도 네 예상대로 움직이지 않을 수 있어. 그를 막는 데 사람을 보내는 동안 바다가 먼저 움직이면?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_013","speaker":"나","text":"그래서 선인들께 바다를 부탁한 겁니다. 저는 황금옥으로 가고요. 전부 제 말 한 줄에 걸라고는 못 해요. 하지만 저기서 위험을 막을 기회가 있는데, 어긋날 수도 있다는 이유로 기다리는 건 못 하겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_014","speaker":"","text":"응광은 지도의 해안선을 짚었다. 류운차풍진군은 바다를 맡을 선인들의 움직임을, 각청은 사람을 빼낼 순서를 짚었다. 서로의 판단을 다 좋아하지는 않아도 손은 같은 지도 위에서 움직였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_015","speaker":"응광","text":"황금옥은 확인할 거야. 네가 가겠다는 것도 들었고. 그 전에, 네가 아는 이야기에서 오셀은 어떻게 막았니? 그 얼굴을 보니 답이 마음에 안 드는 모양인데.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_016","speaker":"나","text":"군옥각입니다. 제가 아는 대로 가면 오셀을 막으려고 이걸 포기해야 해요. 바다에 떨어뜨려야 합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_017","speaker":"나","text":"처음 온 사람이 집을 버리라고 하는 게 얼마나 뻔뻔한지 알아요. 그래도 말 안 하고 가면 더 비겁할 것 같아서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_018","speaker":"","text":"방의 소리가 멎었다. 응광은 바로 답하지 않았다. 창 너머로 항구가 펼쳐져 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_019","speaker":"응광","text":"네가 그 이야기를 알았다고 내 군옥각에 대한 권리까지 얻은 건 아니야. 그렇지만 손해 날 수 있다는 말을 듣기 싫어서 숨기는 사람도 아니지. 내가 알고 싶은 건 그 순간까지 뭘 해 볼 수 있느냐는 거야. 떨어뜨리기 전까지는 아주 쓸모 있는 곳이거든.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_palace_020","options":[{"label":"마지막 수가 있다고 다른 방법을 덜 찾으면 안 된다는 거죠. 그래서 타르탈리아 쪽을 먼저 끊고 싶어요. 그게 되면 여기서 무슨 차를 마실지도 고민할 수 있겠죠.","id":"PRO_L03K2_palace_021","items":[{"k":"line","id":"PRO_L03K2_palace_022","speaker":"응광","text":"차는 나중에 골라. 지금은 비울 사람과 남을 사람부터 정할 거야. 언제 포기할지는 내가 판단해. 누구 이야기 속 장면을 완성하려고 버리지는 않아.","map":"MAP_LIYUE_HARBOR"}]},{"label":"다른 방법을 먼저 찾죠. 마지막 수단이 있다는 이유로 사람을 옮기거나 바다를 늦출 기회까지 줄이고 싶지는 않아요.","id":"PRO_L03K2_palace_023","items":[{"k":"line","id":"PRO_L03K2_palace_024","speaker":"응광","text":"그래. 할 수 있는 일을 다 세어 본 뒤에야 마지막이라는 말을 쓸 수 있겠지. 언제 포기할지는 내가 판단해. 누구 이야기 속 장면을 완성하려고 버리지는 않아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_palace_025","speaker":"류운차풍진군","text":"좋은 건물은 쓰임이 많지. 바다의 경계는 맡겠네. 인간들의 준비가 늦어져 싸움터에 사람이 남는 일은 없도록 하게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_026","speaker":"각청","text":"그건 저희가 하겠습니다. 다만 대피 중인 길 위로 싸움이 밀려오면 즉시 알려 주세요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_palace_027","options":[{"label":"그분을 찾으면 제가 도망친 얘기를 먼저 하셔도 됩니다. 변명 안 할게요. 대신 제가 다시 돌아와 찾았다는 것도 같이 전해 주세요.","id":"PRO_L03K2_palace_028","items":[{"k":"line","id":"PRO_L03K2_palace_029","speaker":"응광","text":"전할 수 있게 되면 함께 전하겠어. 다만 네가 지금도 살아 있다는 말까지 붙일 수 있도록 행동해. 상대에게 할 말을 남겨 두고 사라지는 건 거래를 끝내는 좋은 방법이 아니니까.","map":"MAP_LIYUE_HARBOR"}]},{"label":"나중에 일이 끝나면 이 방에서 아무 일 없는 얘기도 한 번 하고 싶어요. 밥 늦게 나왔다고 불평하는 정도로요. 지금은 그게 되게 사치스럽네요.","id":"PRO_L03K2_palace_030","items":[{"k":"line","id":"PRO_L03K2_palace_031","speaker":"응광","text":"그런 불평은 평소에도 충분히 들어. 그래도 네가 직접 돌아와서 한다면 한 번쯤은 시간을 내 주지. 그때는 귀한 방에 들어왔다는 이유로 억지 칭찬부터 늘어놓지 말고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_palace_032","speaker":"나","text":"좋아요. 저는 타르탈리아를 막으러 황금옥으로 가겠습니다. 제군의 시신이 왜 사라졌는지 단서도 찾을 수 있으면 찾을게요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_033","speaker":"응광","text":"황금옥 바깥에 병사를 남겨 둘게. 네가 가져올 답은 네가 돌아와야 나한테 닿으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_079","text":"응광은 다음 지시를 내리기 전 내가 일어서는 모습을 지켜보았다. 다리에 힘이 늦게 들어가 잠깐 의자 끝을 붙잡았지만 넘어지지 않았다. 류운차풍진군이 무슨 말을 하려다 멈췄고, 나는 굳이 못 본 척하지 않았다. 아직 몸을 챙기라는 잔소리를 들을 사람이 있다는 사실이 나쁘지 않았다."},{"k":"keep","id":"ISK_L03_K2_080","text":"군옥각에서 내려온 뒤 각청은 황금옥으로 가는 호위 병사들에게 나를 인계했다. 물자 구역의 답도 하나 도착해 있었다. 짐꾼은 아직 찾지 못했고 그의 물건은 그대로 보관 중이었다."},{"k":"line","id":"PRO_L03K2_water_001","speaker":"나","text":"고마워. 못 찾았다는 말이 이렇게 아픈데, 그래도 아무 말 없이 잊히는 것보다는 낫네. 돌아오면 그것부터 물어볼 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_002","speaker":"각청","text":"물어봐. 내가 바쁜 척해도 붙잡고 물어. 닷새는 못 돌려주지만 아저씨 찾는 건 내가 해. 오늘부터 내 일이야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_003","speaker":"나","text":"네 일 많잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_004","speaker":"각청","text":"하나 더 늘었다고 안 죽어. 너야말로 황금옥 가서 죽지 마. 남의 일 늘리지 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_005","speaker":"나","text":"……그 말투, 진짜 그대로다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_006","speaker":"각청","text":"뭐가.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_007","speaker":"나","text":"아니. 좋은 뜻이야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_008","speaker":"","text":"그 말을 듣자 각청에게 예전 일을 다시 증명하려던 마음을 조금 내려놓았다. 그녀는 닷새를 돌려줄 수 없었지만 새로운 일을 맡을 수 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_009","speaker":"나","text":"그럼 나도 내 몫 하러 갈게. 남의 짐 대신 드는 재주는 없는데 남의 일에 끼어드는 재주만 자꾸 느네. 끝까지 끼어들고 돌아올 테니까 저쪽 자리 하나는 비워 둬.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_010","speaker":"각청","text":"자리는 있어. 그리고 할 일이 생겼다고 안 다치는 몸이 된 건 아니야. 무리하면 물러서.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_086","text":"각청이 해안의 대피 상황을 보러 돌아서는 동안 황금옥 쪽 병사들이 앞장섰다. 익숙한 포대와 수레들이 길옆으로 물러나 있었다. 이번에는 사람이 먼저 빠져나간 자리를 지나고 있다는 것을 확인했다."},{"k":"keep","id":"ISK_L03_K2_087","text":"황금옥으로 향하는 길은 생각보다 길었다. 누구도 짐꾼처럼 걸음이 짧다고 놀리지 않았다. 그 침묵이 더 낯설어 나는 길의 모양을 외우기 시작했다. 돌아올 때 헤매지 않는 것부터 하기로 했다."},{"k":"line","id":"PRO_L03K2_golden_001","speaker":"","text":"황금옥 앞에서는 일꾼들이 밖으로 빠져나오고 있었다. 안쪽에서 충격이 난 뒤 주 출입문이 비틀려 관리 통로로 우회했다는 말이었다. 길목을 보았다. 큰 수레를 세우면 문을 가릴 위치였다. 닷새 동안 물자 구역에서 익힌 감각이 엉뚱한 곳에서 도움이 되었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_002","speaker":"나","text":"저 수레는 문 앞에서 옆으로 빼 주세요. 사람이 급하게 나오면 바퀴에 걸려요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_003","speaker":"","text":"수레가 비켜나자 그 뒤에 서 있던 회색 외투 둘이 드러났다. 우인단. 일꾼들을 내보내 준 게 아니라, 들어갈 사람을 고르고 있었던 것이다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_004","speaker":"우인단 병사","text":"여기서부터는 집행관의 영역이다. 돌아가.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_005","speaker":"나","text":"저 집행관한테 할 말이 있어서 왔는데요. 약속은 안 했지만.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_006","speaker":"우인단 병사","text":"약속 없는 손님은 받지 않는다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_007","speaker":"나","text":"그쪽도 리월에 약속하고 온 건 아니잖아요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_008","speaker":"","text":"대답 대신 얼음이 튀었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"combat","id":"PRO_L03K2_golden_009","group":"EG_FATUI_PATROL","text":"황금옥 관리 통로를 막은 우인단 전투조. 안으로 들어가려면 뚫어야 한다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_010","speaker":"","text":"마지막 병사가 무릎을 꿇었다. 호위 병사들이 달려와 그를 끌어냈다. 통로는 비어 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_011","speaker":"나","text":"저는 안으로 들어가겠습니다. 타르탈리아가 나오면 앞을 막고 싸우려 하지 말고, 사람들 쪽으로 못 가게만 떨어져 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_012","speaker":"호위 병사","text":"안에서 길이 막히면 무리해서 넘어가지 마십시오. 돌아올 수 있는 틈이 있을 때 돌아오셔야 합니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_091","text":"주머니에 무엇이 있는지 무의식중에 확인하다 손을 뗐다. 설산에서 본 구슬은 여기 없었다. 꺼내서 앞길을 바꾸어 줄 물건도 없었다. 무기를 잡고 통로로 들어갔다."},{"k":"line","id":"PRO_L03K2_golden_013","speaker":"","text":"넓은 공간에 이르자 발소리가 길게 돌아왔다. 모락스의 시신은 보이지 않았다. 대신 타르탈리아가 서 있었다. 내가 상상한 상대는 무언가를 찾고 있거나 뜻대로 되지 않아 불쾌해하고 있을 것 같았다. 눈앞의 남자는 빈 공간에서 기다리는 데 익숙해 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_014","speaker":"타르탈리아","text":"들어오기 전에 바깥을 제법 정리했더군. 나갈 때도 그 길을 쓸 생각인가 봐. 준비성 좋은 손님은 싫지 않아. 날 찾아온 거지?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K2_golden_015","options":[{"label":"그래. 제군의 시신 찾으러 온 거면 헛걸음한 것 같네. 나도 없어서 여기까지 왔거든. 신의 심장 찾겠다고 다른 일 벌일 생각이면 그것부터 접고.","id":"PRO_L03K2_golden_016","items":[{"k":"line","id":"PRO_L03K2_golden_017","speaker":"타르탈리아","text":"찾으러 온 사람이 둘이라. 그럼 너는 나에게서 뭘 얻으려고 싸울 셈이지? 이미 없다는 걸 확인한 물건? 아니면 네가 생각한 순서대로 흘러가지 않는 일의 답?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"나도 시신을 못 찾아서 왔어. 네가 가져갔다면 어디 있는지 묻겠지만, 아니라면 여기서 무슨 계획을 세웠는지 말해.","id":"PRO_L03K2_golden_018","items":[{"k":"line","id":"PRO_L03K2_golden_019","speaker":"타르탈리아","text":"내 계획과 네가 찾는 답을 한꺼번에 묻는군. 그럼 너는 나에게서 뭘 얻으려고 싸울 셈이지? 이미 없다는 걸 확인한 물건? 아니면 네가 생각한 순서대로 흘러가지 않는 일의 답?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K2_golden_020","speaker":"","text":"미간을 좁혔다. 시신과 신의 심장을 동시에 들은 사람의 얼굴치고는 놀라움이 너무 적었다. 그는 이곳에 온 이유를 따지는 대신 내가 어디까지 버틸지 보고 있는 것처럼 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_021","speaker":"나","text":"질문 잘하네. 그럼 내 질문에도 답해 봐. 너, 지금 싸우고 싶어? 내가 아는 너라면 여기까지 온 상대 보고 좀 더 들떠야 할 것 같은데. 아까부터 내가 뭘 할지만 기다리고 있잖아.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_022","speaker":"타르탈리아","text":"네가 아는 나라는 말이 재미있군. 나는 아직 네 이야기를 많이 듣지 못했는데. 그렇게 확신한다면 먼저 보여 줘. 내가 어떤 반응을 할지도 알고 있을 테니까.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_023","speaker":"","text":"한 발 움직이자 타르탈리아의 시선은 무기가 아니라 발이 놓인 곳으로 잠깐 내려갔다. 전투에서 위치를 보는 것은 이상한 일이 아니었다. 그런데 그 짧은 시선이 이상하게 오래 남았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_024","speaker":"나","text":"밖에 네 사람들 쓰러져 있어. 안쪽 연락도 끊겼다던데, 찾아볼 생각은 없어? 난 여기까지 오는 길에 남의 짐꾼 한 사람 못 찾았다는 얘기만 들었는데도 계속 걸렸거든.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_025","speaker":"타르탈리아","text":"그래서 네가 여기 온 건 아니잖아. 못 찾은 사람 얘기로 시간을 벌려고? 네가 막겠다고 한 일을 막아 봐. 다른 사람은 네가 돌아간 다음에 찾아도 늦지 않을지 모르지.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_026","speaker":"","text":"손에 힘이 들어갔다. 도발하고 흡족해하는 기색도 없었다. 그저 아픈 지점을 짚고 다음 반응을 기다렸다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K2_golden_027","options":[{"label":"그 사람 얘기는 네가 입에 올릴 농담거리가 아니야. 나도 내가 아는 너를 앞세워 방심하지 않을게. 지금 내 앞에서 하는 짓만 보고 상대하겠어.","id":"PRO_L03K2_golden_028","items":[{"k":"line","id":"PRO_L03K2_golden_029","speaker":"타르탈리아","text":"그편이 너에게도 편하겠지. 기억해 둔 상대와 눈앞의 상대를 번갈아 보면 손이 늦어질 테니까. 이제 네가 멈추려는 일을 행동으로 보여 줘.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"그래, 돌아가서 찾아야지. 그러려면 너하고 말만 주고받을 수는 없겠네. 문 앞 수레 치워 달라고 한 이유가 도망갈 때 걸리기 싫어서만은 아니거든.","id":"PRO_L03K2_golden_030","items":[{"k":"line","id":"PRO_L03K2_golden_031","speaker":"타르탈리아","text":"돌아갈 자리를 남겨 둔 건 좋은 생각이야. 그 자리를 다시 밟을 수 있을지는 네가 얼마나 움직이느냐에 달렸겠지. 시작하자.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K2_golden_032","speaker":"","text":"타르탈리아가 손을 움직였고 물빛 날이 번쩍였다. 바닥을 박차며 몸을 피했다. 칼날이 지나간 기둥에서 돌가루가 떨어졌다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_110","text":"황금옥 내부에서 타르탈리아와의 전투가 시작된다."},{"k":"line","id":"PRO_L03K2_golden_033","speaker":"","text":"몇 번이나 넘어질 뻔하며 뒤로 물러났다. 내가 디딘 금 간 돌판을 타르탈리아도 피하려 몸을 틀었다. 무기를 고쳐 쥐자 손끝이 아팠다. 멋있는 싸움은 아니었다. 아직 여기서 끝낼 수 없다는 고집만 남아 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_034","speaker":"나","text":"그만해. 네가 뭘 하려고 했든 여기서 끝내. 나는 돌아가서 찾을 사람이 있어.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_035","speaker":"","text":"타르탈리아는 답하지 않았다. 시선이 내 무기 끝에서 벗어났지만, 무엇을 보았는지 확인하기 전에 몸이 앞으로 나갔다. 마지막 틈이라고 판단했다. 결정타를 날리려 팔을 뻗는 순간, 발밑의 감각이 통째로 내려앉았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_036","speaker":"","text":"기둥의 장식이 떨어지며 바닥을 부쉈고, 천장을 가로지르는 들보가 뒤틀렸다. 출구 방향을 기억해 몸을 틀었다. 바깥의 수레를 치워 두었다는 생각이 스쳤다. 길은 열어 두었다. 그러나 그 길에 닿을 시간이 남은 것은 아니었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_037","speaker":"나","text":"황금옥 무너져요! 문에서 떨어져! 들어오지 마요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_116","text":"무너진 돌이 어깨를 때렸고 다리가 꺾였다. 이어 떨어진 들보가 몸을 덮쳤다. 타르탈리아는 먼지에 가려 보이지 않았다. 남의 몸을 들어 올리려다 놓쳤던 팔이 이번에는 제 몸 위의 무게를 밀어내지 못했다. 황금옥이 내려앉으며 나를 잔해 아래에 묻었다."},{"k":"keep","id":"ISK_L03_K2_END","text":"내가 무너진 황금옥에 깔리는 순간에서 멈춘다. 구조 여부와 부상 상태는 아직 밝혀지지 않는다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_0","text":"자네! 살아 있었군. 물자 구역에 짐만 남았다고 해서 얼마나…… 아저씨는? 아저씨는 같이 안 왔나?"},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_1","text":"행추, 숨 좀 쉬고 말해. 각청, 이 사람은 내가 알아. 고운각에서 회수한 인계표에 이 사람과 짐꾼 둘 다 적혀 있어. 네가 기억 못 하는 건 네 잘못이 아니지만, 이 사람이 꾸며 낸 것도 아니야."},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_2","text":"……둘이 이 사람을 안다는 거지. 알겠어. 지우지 않아. 찾을 사람을 늘릴게. 너는 선인께 무슨 말을 했는지 계속 설명해 줘."},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_3","text":"……행추, 연비. 아저씨는 못 찾았어. 내가 두고 왔어. 찾았다는 소식 오면 나부터 불러 줘. 밥 먹었는지도 물어봐 주고."}]},{"id":"ISK_L04_K1","entry":"ISK_L04_K1_001","items":[{"k":"keep","id":"ISK_L04_K1_001","hold":true,"text":"눈을 떴는지 감고 있는지 한동안 알 수 없었다. 입 안에 먼지가 씹혔고 숨을 들이마실 때마다 어깨가 아팠다. 들보는 기울어진 석재에 받쳐 있었고, 그 아래 생긴 비좁은 틈에 등이 눌려 있었다. 숨이 드나들 공간이 있다는 사실부터 붙잡았다."},{"k":"line","id":"PRO_L04K1_rubble_001","speaker":"","text":"팔을 비틀어 손목을 만졌다. 박동이 있었다. 각청에게서 찾지 못했던 것을 내 몸에서 찾자 안심과 죄책감이 함께 올라왔다. 타르탈리아가 움직이는 소리는 들리지 않았다. 대신 멀리서 돌 구르는 소리와 사람의 목소리가 났다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_002","speaker":"나","text":"여기 사람 있어요! 관리 통로로 들어간 사람, 아직 살아 있어요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_003","speaker":"호위 병사","text":"들립니다! 위치 찾았으니 계속 소리 지르지 마십시오. 앞이 막혔습니다. 손은 움직입니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_004","options":[{"label":"손은 움직여요. 그런데 위에 들보가 걸려 있어요. 돌부터 막 치우지 마요. 이거 내려앉으면 대답 못 해요.","id":"PRO_L04K1_rubble_005","items":[{"k":"line","id":"PRO_L04K1_rubble_006","speaker":"호위 병사","text":"바깥에서도 들보가 보입니다. 먼저 받침을 넣겠습니다. 안에서는 손 닿는 작은 돌만 옆으로 밀어 주십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"어깨하고 허벅지가 눌렸어요. 손은 움직이고 다리 감각도 있어요. 어떻게 하면 돼요?","id":"PRO_L04K1_rubble_007","items":[{"k":"line","id":"PRO_L04K1_rubble_008","speaker":"호위 병사","text":"그 정도면 됩니다. 억지로 빼지 마십시오. 받침 넣는 동안 손 닿는 작은 돌만 옆으로 밀어 숨 쉴 틈을 넓혀 두세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"thru","id":"ISK_L04_K1_001"},{"k":"line","id":"PRO_L04K1_rubble_009","speaker":"","text":"틈으로 빛이 들어왔을 때 병사는 곧장 팔을 잡아당기지 않았다. 숨을 쉬는지 묻고, 몸이 어디에 걸렸는지 살핀 뒤 다른 이들과 무게를 나누었다. 나를 찾는 목소리가 실제로 돌아왔다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_010","speaker":"나","text":"옆에 있던 남자는요? 붉은 머리, 회색 옷. 저랑 싸우다 같이 안에 있었어요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_011","speaker":"호위 병사","text":"나오는 사람은 보지 못했습니다. 지금 열린 틈에서도 당신뿐입니다. 안쪽 전체를 확인한 건 아닙니다. 먼저 당신부터 꺼냅니다. 고개 이쪽으로.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K1_008","text":"몸이 잔해에서 빠져나오자 바람이 젖은 옷 안으로 들어왔다. 시원하다고 생각하기도 전에 통증이 밀려왔다. 무릎을 세우려다 옆으로 기울었고 병사가 받쳐 주었다. 무너진 황금옥은 내가 들어갔던 건물과 다른 모양이었다. 어디에도 타르탈리아는 보이지 않았다."},{"k":"line","id":"PRO_L04K1_rubble_012","speaker":"군의관","text":"제 말을 들으면서 손가락을 펴 보세요. 이번엔 발. 어깨와 허벅지가 심하게 눌렸지만 지금 보이는 출혈은 막을 수 있습니다. 숨이 더 차거나 가슴이 아프면 바로 말하세요. 멀쩡히 말한다고 안쪽까지 괜찮은 건 아닙니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_013","options":[{"label":"치료받을게요. 혼자 멀쩡하다고 우겨 봐야 걷다가 또 업혀 갈 것 같네요.","keep":"ISK_L04_K1_010","items":[{"k":"line","id":"PRO_L04K1_rubble_014","speaker":"군의관","text":"그 말이면 됩니다. 아픈 곳은 참지 말고 바로 말하세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K1_011","text":"병사들이 구조 지점 옆으로 구호 물자를 가져왔다. 군의관은 내 동의를 듣고 처치 자리를 마련했다. 어떻게 살아남았는지를 다 설명할 수는 없어도, 지금 치료할 사람이 이곳에 있다는 것은 분명했다."},{"k":"line","id":"PRO_L04K1_rubble_015","speaker":"","text":"군의관은 찢어진 옷을 걷어 상처를 씻고 눌러 지혈한 뒤 붕대를 감았다. 혼자 서 보겠다는 말을 삼켰다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_016","options":[{"label":"저 살아 있는 거 맞죠? 웃긴 질문인 건 아는데, 요 며칠 제가 확인한 것들이 자꾸 뒤집혀서요.","id":"PRO_L04K1_rubble_017","items":[{"k":"line","id":"PRO_L04K1_rubble_018","speaker":"군의관","text":"숨 쉬고, 대답하고, 피 납니다. 여기까지는 제가 확인했습니다. 살아 있다는 것과 뛰어도 된다는 건 다른 말이고요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_019","speaker":"나","text":"피 나는 걸 확인 항목에 넣는 건 처음 보네요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_020","speaker":"군의관","text":"죽은 사람은 피가 안 납니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_021","speaker":"나","text":"……아, 네.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"붕대 감는 솜씨가 너무 익숙해서 고마우면서도 좀 무섭네요. 조금만 덜 아프게 안 될까요?","id":"PRO_L04K1_rubble_022","items":[{"k":"line","id":"PRO_L04K1_rubble_023","speaker":"군의관","text":"아프다고 말하는 건 잘하셨습니다. 조금 조절하죠. 다만 출혈 막을 만큼은 감아야 합니다. 이 악물고 괜찮다고만 하는 환자보다는 낫군요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K1_019","text":"처치가 끝나기 전에 바다 쪽에서 소리가 왔다. 바람 소리와 달랐다. 먼 하늘이 검게 꺾이고, 수평선 위로 거대한 물줄기가 솟았다. 보고하러 달려온 병사의 얼굴을 본 군의관이 설명을 멈췄다. 바다에 나타난 것이 항구 쪽으로 움직이고 있었다."},{"k":"line","id":"PRO_L04K1_rubble_024","speaker":"나","text":"오셀이야. 막으려고 했는데 결국 나왔어.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_025","speaker":"나","text":"타르탈리아는…… 아니, 지금 그걸 찾고 앉아 있을 때가 아니지. 군옥각으로 가야 해요. 응광한테 제가 살아 나왔고 황금옥은 무너졌다고 전해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_026","speaker":"군의관","text":"걸을 수 있다는 확인이 전투 허락은 아닙니다. 혼자 달려가면 도중에 다시 업어 와야 합니다. 병사들과 같이 가세요. 호흡이 바뀌면 멈추고요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_027","speaker":"","text":"황금옥을 돌아보았다. 내가 기억하는 타르탈리아는 싸움을 즐겼다. 안에서 만난 상대는 끝나는 순간만 기다리는 듯했다. 의문은 살아서 나중에 붙잡아야 했다. 병사가 내민 팔을 붙들었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K1_023","text":"호위대는 구조 지점을 표시하고 추가 수색 인원에게 인계했다. 안전한 길까지 부축받고, 완만한 구간에서는 직접 걸었다. 먼 바다에서 솟아난 형체를 보았다. 이야기 속에서 알고 있던 이름이 실제 도시보다 크게 일어섰다. 미리 경고했다는 사실이 그 크기를 줄여 주지는 않았다."},{"k":"keep","id":"ISK_L04_K1_024","text":"항구로 돌아오는 길에는 대피한 사람들이 이어졌다. 병사들이 어느 쪽을 비워 달라고 외치면 사람들은 움직였다. 그 작은 질서가 무너진 도시를 붙들고 있었다."},{"k":"line","id":"PRO_L04K1_harbor_001","speaker":"","text":"사람들이 빠져나간 거리 한쪽에서 비명이 났다. 빈 가게였다. 닫힌 문이 안쪽에서 부서지고, 보물 사냥단 셋이 자루를 메고 나왔다. 바다가 일어선 날에도 남의 물건부터 챙기는 사람은 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_002","speaker":"보물 사냥단","text":"비켜. 다리도 성치 않은 게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_003","speaker":"나","text":"그 말은 맞는데요. 손은 멀쩡해요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_004","speaker":"","text":"옆의 호위 병사가 창을 내렸다. 나도 무기를 들었다. 다친 어깨가 당겼다. 참을 만했다.","map":"MAP_LIYUE_HARBOR"},{"k":"combat","id":"PRO_L04K1_harbor_005","group":"EG_TREASURE_PATROL","text":"대피로 비어 버린 거리를 터는 보물 사냥단 습격조. 지나가는 길이니 비켜 세울 수밖에 없다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_006","speaker":"","text":"자루가 바닥에 떨어지고 사냥단은 골목으로 흩어졌다. 병사가 자루를 가게 안으로 던져 넣고 문을 닫았다. 다시 걸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_007","speaker":"","text":"한참 뒤 방어 인원이 오가는 항구의 집결지에 닿았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_008","speaker":"각청","text":"살아 돌아왔네. 황금옥 무너졌다는 보고가 먼저 와서 사람을 더 보내려던 참이야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_009","speaker":"각청","text":"왜 그렇게 서 있어. 다친 쪽에 힘 빼. 보고는 앉아서 해도 들려.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_010","speaker":"나","text":"돌아오면 기다리겠다며. 지키러 왔는데 시작부터 자세 지적이네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_011","speaker":"나","text":"타르탈리아하고 싸웠고, 끝낼 수 있을 것 같던 순간에 건물이 무너졌어. 그 사람은 못 찾았대. 시신도 안에 없었어. 바다 막는 쪽에 나도 보태 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_012","speaker":"각청","text":"어디에 붙일지는 네 몸부터 보고. 여기서 쓰러지면 널 지키느라 또 사람이 빠져. 팔 들었을 때 어디가 아픈지 말해.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_013","speaker":"","text":"팔을 천천히 들자 붕대가 당겼다. 각청은 그 범위를 보고 칼을 크게 휘두르는 자리 대신 방어선 안쪽을 가리켰다. 부상자를 옮기고, 장치로 이어지는 길을 막는 자리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_harbor_014","options":[{"label":"뒤쪽도 괜찮아. 앞으로 나가야 도움 된다는 고집은 황금옥 밑에 놓고 왔어.","id":"PRO_L04K1_harbor_015","items":[{"k":"line","id":"PRO_L04K1_harbor_016","speaker":"각청","text":"잘 놓고 왔네. 올라가는 동안 난간 잡고, 손에 힘 빠지면 옆 사람 불러. 살려 놓은 사람 다시 잃고 싶지 않아.","map":"MAP_LIYUE_HARBOR"}]},{"label":"솔직히 앞에 서고 싶었는데, 네 말대로 할게. 물통 돌려주러 온 사람이 또 깔리면 체면이 없잖아.","id":"PRO_L04K1_harbor_017","items":[{"k":"line","id":"PRO_L04K1_harbor_018","speaker":"각청","text":"체면 때문이라도 말 들으면 됐어. 난간 잡고, 손에 힘 빠지면 옆 사람 불러. 살려 놓은 사람 다시 잃고 싶지 않아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_031","text":"방어 지점으로 가는 통로가 열렸다. 일반 대피 인원과 방어에 합류하는 인원이 갈라졌고, 나는 각청이 지정한 조를 따라 움직였다."},{"k":"keep","id":"ISK_L04_K1_032","text":"군옥각에 오르는 길은 전과 달랐다. 아래에서는 마지막 대피 인원이 길을 건넜고, 위에서는 선인들의 힘이 바다를 향해 뻗었다. 발을 디뎠을 때 그곳은 차를 마시며 지도를 펼쳤던 집이 아니라 도시 앞에 놓인 방어 진지가 되어 있었다."},{"k":"line","id":"PRO_L04K1_osial_001","speaker":"응광","text":"황금옥에서 바로 내 집까지 무너뜨리러 온 건 아니겠지? 살아 돌아온 건 환영이야. 환영할 형편이 아닐 뿐이지. 네 덕에 대피를 먼저 시작했어. 이제 그 시간을 더 벌어야 해.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_002","options":[{"label":"앞 건물은 제가 부순 걸로 계산하지 말아 주세요. 다음 건물도 가능하면 남기고 싶습니다.","id":"PRO_L04K1_osial_003","items":[{"k":"line","id":"PRO_L04K1_osial_004","speaker":"응광","text":"달라진 건 이미 있어. 아래에 남을 뻔한 사람들이 빠져나갔어. 하지만 상대가 작아지진 않았네. 선인들이 전면을 맡는 동안 뒤로 들어오는 적을 막아 줘.","map":"MAP_OSIAL_BATTLE"}]},{"label":"어디를 맡으면 앞에서 싸우는 사람들 손이 덜 묶일까요? 제가 안다던 순서대로 가지도 않으니, 지금 필요한 일부터 듣겠습니다.","id":"PRO_L04K1_osial_005","items":[{"k":"line","id":"PRO_L04K1_osial_006","speaker":"응광","text":"그렇게 물어 주는 편이 지금은 훨씬 도움이 돼. 선인들이 전면을 맡는 동안 뒤로 들어오는 적을 막아 줘. 그들이 힘을 돌리면 바다 쪽이 비어.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_007","speaker":"","text":"류운차풍진군이 고개를 돌렸다. 깔렸다 나온 몸으로 또 높은 곳에 섰다는 말을 하려는 듯하다가, 다친 어깨와 옆에 선 병사를 보고 말을 줄였다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_008","speaker":"류운차풍진군","text":"살아 돌아온 것은 잘했네. 그렇다고 기둥 아래서 버텼다는 이유로 파도 앞에서도 버틸 몸이 되었다고 착각하지 말게. 장치 뒤쪽 연결로를 지키게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_009","speaker":"나","text":"알겠습니다. 저 거대한 머리랑 눈 마주칠 생각은 없어요. 크기 비교해 보니까 협상할 여지가 없더라고요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_010","speaker":"","text":"바다에서 솟은 물줄기가 방어의 빛을 때렸다. 허리를 낮추고 난간을 잡았다. 뒤쪽으로 스며든 습격자들이 좁은 연결로를 향해 달려왔다. 각청이 앞의 공격을 끊어 냈고, 나는 내가 맡은 틈으로 다가오는 적을 향해 무기를 들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K1_040","text":"오셀에 맞선 공동 방어가 이어지는 동안, 군옥각 후방 연결로를 지키는 방어전이 시작된다."},{"k":"line","id":"PRO_L04K1_osial_011","speaker":"","text":"연결로에 밀려들던 적의 마지막 공격이 끊겼다. 길은 지켰다. 그러나 바다의 형체가 다시 몸을 일으키자 방어 장치 위로 균열이 번졌고, 선인들이 힘을 밀어 넣던 자리가 통째로 흔들렸다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_012","speaker":"각청","text":"뒤쪽 인원부터 내려보내! 장치 붙들려고 남지 마! 너도 그 부상자 데리고 안쪽으로!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_013","speaker":"나","text":"이 사람 다리에 힘이 안 들어가. 반대쪽 어깨 잡아 줘!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_014","speaker":"","text":"병사 하나와 부상자를 사이에 두고 옮겼다. 팔이 떨렸지만 놓지 않았다. 각청이 다가와 무게를 받아 주자 숨이 터졌다. 전에는 손에 남은 사람을 놓고 도망쳤다. 지금은 누군가가 그 무게를 나누어 들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_015","speaker":"","text":"응광은 무너진 방어 지점과 바다를 번갈아 보았다. 류운차풍진군은 장치를 다시 이어도 오래 버티기 어렵다고 말했다. 응광은 창 안쪽을 한 번 보았다. 급히 챙겨 나온 문서와 물건들. 그녀는 더 가져오라는 명령을 내리지 않았다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_016","speaker":"응광","text":"결정할 때네. 군옥각을 포기하겠어. 바다에 떨어뜨려 그 틈을 막을 거야. 남은 사람을 모두 옮겨. 내 물건 때문에 누가 마지막까지 여기 남는 일은 없게.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_017","options":[{"label":"정말 다른 방법이 없는 겁니까? 제가 먼저 말한 건 알아요. 그런데 당신이 지켜 온 걸 직접 보니까, 알고 있었으니 괜찮다는 말은 못 하겠네요.","id":"PRO_L04K1_osial_018","items":[{"k":"line","id":"PRO_L04K1_osial_019","speaker":"응광","text":"괜찮을 필요 없어. 아깝고, 화나고, 다시 지을 생각 하면 벌써 손이 많이 가. 그래도 아래 도시를 남길 수 있다면 선택은 분명해. 네가 말했기 때문이 아니라 내가 지금 보고 정한 거야. 그러니 내 표정 살필 시간에 사람을 옮겨.","map":"MAP_OSIAL_BATTLE"}]},{"label":"……알겠습니다. 제가 먼저 꺼낸 얘기라서 지금은 아무 말도 안 하는 게 예의 같네요.","id":"PRO_L04K1_osial_020","items":[{"k":"line","id":"PRO_L04K1_osial_021","speaker":"응광","text":"그 예의는 받아 두지. 하지만 네가 말했기 때문에 하는 결정이 아니야. 내가 지금 보고 정한 거야. 내 표정 살필 시간에 사람을 옮겨.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_022","speaker":"류운차풍진군","text":"이 몸이 길을 열겠네. 소, 남은 자들을 살피게. 이 건물을 떨어뜨리는 것만으로 끝내서는 안 되니, 닿는 순간까지 빈틈을 남기지 말게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_023","speaker":"","text":"각청은 마지막 명단을 확인하는 사람 곁에서 직접 머릿수를 세었다. 난간에 걸린 천을 걷어 발이 걸리지 않게 한 뒤, 뒤를 돌아보며 따라오는 사람을 재촉했다. 비 새는 천막을 둘이 들어 올리던 일이 떠올랐다. 이번에는 물을 빼는 대신 집을 두고 떠나야 했다.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_024","options":[{"label":"천막에서는 왼쪽 당기라더니 오늘은 오른쪽으로 빠지라네. 알았어, 이번에도 네 말 들을게. 대신 너 마지막까지 남아서 혼자 확인하지 마.","id":"PRO_L04K1_osial_025","items":[{"k":"line","id":"PRO_L04K1_osial_026","speaker":"각청","text":"천막 얘기는 모르겠지만, 네가 먼저 가면 나도 바로 따라가. 여기 남은 사람은 확인했어. 자꾸 뒤돌아보다가 발 헛디디지 마.","map":"MAP_OSIAL_BATTLE"}]},{"label":"남은 사람 없지? 한 번 놓고 나온 사람을 자꾸 다시 찾는 버릇이 생겨서 그래. 너 살아 있는 건 이번엔 안 놓쳐.","id":"PRO_L04K1_osial_027","items":[{"k":"line","id":"PRO_L04K1_osial_028","speaker":"각청","text":"남은 인원 확인했어. 네가 모든 사람을 혼자 기억해야 하는 자리 아니야. 병사들도, 나도 보고 있어. 발판 건너. 바로 뒤에 있어.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_029","speaker":"","text":"발판이 기울자 몸을 낮췄다. 소가 마지막으로 주변을 살핀 뒤 남은 이들을 이끌었고, 선인들의 힘이 부서지는 가장자리에서 사람들을 떼어 냈다. 발밑에 있던 군옥각이 멀어졌다. 응광은 마지막까지 바다를 보며 힘을 내렸고, 거대한 건물이 빛을 안은 채 아래로 향했다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_030","speaker":"","text":"바다와 하늘 사이가 눈부시게 터졌다. 차가 놓여 있던 방, 지도가 펼쳐졌던 탁자, 손님에게 비워 주었던 의자가 모두 빛과 물 아래로 사라졌다. 솟아 있던 거대한 형체도 그 아래로 가라앉았다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K1_059","text":"안전한 지점에 내려선 뒤에도 다리가 흔들렸다. 군옥각은 돌아오지 않았다. 사람들은 환호하다가 누가 없는지 확인했고, 누군가는 앉아서 울었다. 응광을 찾았다. 그녀는 자신이 잃은 쪽보다 사람들이 모인 쪽을 먼저 보고 있었다."},{"k":"keep","id":"ISK_L04_K1_060","text":"해안의 감시 인원이 바다의 거대한 위협이 가라앉았다는 보고를 전했다. 군옥각을 희생해 마지막 틈을 막았고, 선인과 칠성이 함께 지켜 낸 도시가 뒤에 남았다."},{"k":"line","id":"PRO_L04K1_osial_031","speaker":"나","text":"일 끝나면 같이 밥 한 번 먹고 싶어요. 식탁은 잃었어도 같이 앉을 자리까지 없어진 건 아니라고 생각하고 싶어서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_osial_032","speaker":"응광","text":"밥 한 끼 먹을 곳도 못 남겼으면 오늘 선택은 실패였겠지. 다행히 아래에 도시가 남았네. 너는 먼저 치료부터 받아. 손님을 식탁에서 쓰러지게 하는 건 내 취향이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_osial_033","speaker":"","text":"웃으려다 갈비뼈 근처가 당겨 얼굴을 찡그렸다. 각청이 그 표정을 놓치지 않았다. 그녀는 군의관을 불렀고, 나는 이번에는 바다를 핑계로 일어서지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_064","text":"대피소의 치료 구역에서 군의관은 젖은 붕대를 풀었다. 멍이 번진 부위를 다시 살피고 상처를 씻었다. 침상에 누워 처음으로 천장이 움직이지 않는다는 사실을 오래 바라보았다."},{"k":"line","id":"PRO_L04K1_rest_001","speaker":"군의관","text":"다시 벌어진 곳은 처치했습니다. 오늘은 쉬십시오. 밤에 숨이 가빠지면 곁의 사람을 부르세요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_002","speaker":"나","text":"걷는 범위를 남이 정해 주는 생활에 아주 익숙해지고 있네요. 도시 구해야 한다는 핑계도 다 썼으니 얌전히 누워 있을게요. 물 좀 가까이 놔 주실 수 있어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_003","speaker":"","text":"그날 밤은 짧게 끊겼다. 돌이 쏟아지는 소리에 놀라 깼다고 생각했지만 옆 침상의 사람이 물그릇을 떨어뜨린 소리였다. 손목을 찾았다가 멈췄다. 방 안에는 숨 쉬는 사람이 여럿 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_068","text":"이틀 동안 치료와 휴식이 이어졌다. 통증과 피로는 남았지만 다시 일어서서 식사를 하러 갈 수 있었다. 그동안 해안의 급한 정리는 끝났고, 항구는 피해 구역을 제외한 통행을 순서대로 되돌리고 있었다."},{"k":"line","id":"PRO_L04K1_rest_004","speaker":"","text":"각청이 찾아왔을 때 나는 침상 가장자리에 앉아 밥을 먹고 있었다. 그녀는 빈 그릇부터 확인했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_005","speaker":"각청","text":"오늘부터 리월항 일반 봉쇄를 해제해. 황금옥 잔해랑 해안 파손 구역만 계속 막아 둘 거야. 멀리 가지 말라는 건 군의관 지시니까 내가 취소 못 해 주고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_006","speaker":"나","text":"보고 없이 뛰어나갈 생각 없으니까 수상한 환자 보듯 보지 마.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_rest_007","options":[{"label":"그런데 너, 오늘 내가 뭘 먹었는지는 기억해 줄 수 있지? 나중에 똑같은 것만 가져오지 말라고 미리 부탁하게.","id":"PRO_L04K1_rest_008","items":[{"k":"line","id":"PRO_L04K1_rest_009","speaker":"각청","text":"오늘 일은 기억해. 네가 빈 그릇 앞에 두고 다음 메뉴부터 요구한 것도. 네가 말한 닷새는 아직 안 떠올라. 그걸 대신 채워 주진 못해도, 네가 얄미운 말 하는 건 지금부터 충분히 남길 수 있겠네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"오늘 먹은 거하고 걸은 거리는 같이 기억해 두자. 지난 닷새 억지로 떠올려 달라는 건 아니야. 지금부터 남길 수 있는 건 남기고 싶어서.","id":"PRO_L04K1_rest_010","items":[{"k":"line","id":"PRO_L04K1_rest_011","speaker":"각청","text":"그건 할 수 있어. 오늘 내가 본 거랑 아직 안 떠오르는 걸 따로 말해 줄게. 네가 빈 그릇 앞에 앉아 있던 것부터 시작이네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_073","text":"그 대답을 듣고 소리 없이 웃었다. 각청도 아주 잠깐 입가를 움직였다. 둘이 같은 일을 기억하며 웃는 순간이 새로 생겼다. 사라진 닷새를 돌려받은 것은 아니었다. 그래도 잃은 시간만 세느라 그 뒤에 생긴 시간을 놓칠 필요는 없었다."},{"k":"keep","id":"ISK_L04_K1_074","text":"며칠 전 지도를 펼쳤던 이들이 이번에는 땅 위의 임시 집무 공간에 모였다. 응광은 남의 책상에서도 자기 물건을 쓰는 것처럼 자연스러웠고, 류운차풍진군은 낮은 처마를 잠깐 올려다보았다. 소는 열린 문 바깥에 서 있었다."},{"k":"line","id":"PRO_L04K1_council_001","speaker":"류운차풍진군","text":"군옥각이 사라졌다고 회의할 자리까지 없어지지는 않았군. 이 몸은 칠성의 판단을 가볍게 보지 않겠네. 허나 함께 막아 냈다고 바다와 산의 경계를 풀어도 된다는 뜻은 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_002","speaker":"각청","text":"필요할 때 도움을 청하는 것과 결정을 전부 맡기는 건 다르다고 생각합니다. 저희가 맡은 곳에서 이상이 생기면 숨기지 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_003","speaker":"응광","text":"같은 탁자에 앉았다고 생각이 같아질 필요는 없죠. 서로 지키려는 걸 직접 봤으니 다음 대화는 조금 덜 돌아가도 되겠네요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_council_004","options":[{"label":"저는 산길을 덜 돌아가면 좋겠습니다. 그때 문 앞까지 올라가다가 다리가 먼저 포기할 뻔했거든요.","id":"PRO_L04K1_council_005","items":[{"k":"line","id":"PRO_L04K1_council_006","speaker":"류운차풍진군","text":"이 몸이 모든 방문객의 식사를 맡을 생각은 없네. 다만 제대로 소식을 가져온 사람이 문밖에서 쓰러져도 좋다는 뜻도 아니지. 다음에는 숨 고를 여유가 있을 때 올라오게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"다음에 급히 전할 일이 생기면 문 앞에서 쓰러지기 전에 부를 방법부터 알려 주세요. 소식 전하러 왔다가 제가 구조 대상이 되는 건 서로 번거롭잖아요.","id":"PRO_L04K1_council_007","items":[{"k":"line","id":"PRO_L04K1_council_008","speaker":"류운차풍진군","text":"자기 숨부터 살피겠다는 뜻이라면 제법 배웠군. 길은 이 몸이 일러 두겠네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_council_009","speaker":"","text":"농담 뒤에는 의례장의 이야기가 남았다. 각청도 응광도 모락스가 쓰러지던 순간을 되찾지 못했고, 나는 사람들의 실제 죽음을 기억했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_010","speaker":"나","text":"바다가 잠잠해진 건 다행인데, 제가 의례에서 본 일은 그대로예요. 각청이 죽었던 것도, 사람들이 한꺼번에 쓰러진 것도요. 없던 일로 넘기지는 말아 주세요. 황금옥에서 만난 타르탈리아도 제가 알던 성격과 달랐습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_011","speaker":"응광","text":"전투가 끝났다고 조사를 끝내진 않아. 다만 살아 있는 사람들한테 네가 본 죽음을 날마다 증명하라고 할 수도 없지. 남은 문제는 따로 추적할 거야. 다시 물어야 할 때는 사람을 보내겠어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_012","speaker":"소","text":"네 기억을 버릴 필요는 없어. 그렇다고 그 기억 때문에 지금 숨 쉬는 사람을 못 보면 안 된다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_013","speaker":"","text":"소의 말을 듣고 각청 쪽을 보았다. 그녀는 고개를 끄덕여 주지 않았다. 이미 오늘의 자신으로 옆에 앉아 있었다. 그걸로 충분했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_001","speaker":"","text":"집무 공간을 나온 뒤 길가의 긴 의자에 잠깐 앉았다. 멀리서 한 남자가 걸어왔다. 단정한 옷차림과 낮은 목소리. 종려였다. 알고 있던 이름을 처음 실제로 부르게 되는 순간이었다. 손을 흔들지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_002","speaker":"종려","text":"부상이 있는데도 오늘 여러 사람을 만났다고 들었네. 왕생당의 객경, 종려라고 하네. 잠깐 함께 앉아도 괜찮겠나?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_003","speaker":"나","text":"앉으세요. 성함은 알고 있습니다. 처음 뵙는데 안다고 말하는 게 여기 와서 버릇이 됐네요. 어떤 분인지 안다고 생각했다가 몇 번 크게 틀렸으니, 이번에는 직접 듣겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_004","speaker":"종려","text":"남의 이야기로 아는 것과 직접 마주한 것은 서로를 완전히 대신하지 못하지. 자네가 선인들에게 전한 경고가 도움이 되었다고 들었네. 다만 자네도 예상하지 못한 일을 많이 겪은 모양이군.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_005","options":[{"label":"도움이 됐다고는 하는데, 결국 군옥각은 사라졌어요. 황금옥도요. 사람들 먼저 옮긴 게 다행인 건 알아요. 그래도 안다는 말에 너무 기대 버린 것 같네요.","id":"PRO_L04K1_zhongli_006","items":[{"k":"line","id":"PRO_L04K1_zhongli_007","speaker":"종려","text":"남은 사람들을 사소한 결과로 여기지 말게. 한 사람의 하루가 이어지는 일은 그 사람에게 결코 작은 일이 아니네. 그렇다고 잃은 것을 아쉬워하지 말라는 뜻도 아니야. 둘을 함께 보아야 다음 선택이 가벼워지지 않겠지.","map":"MAP_LIYUE_HARBOR"}]},{"label":"알고 있던 결말하고 비교하느라 오늘 실제로 도운 사람들을 자꾸 빠뜨리는 것 같아요. 그렇다고 잃은 걸 잘됐다고 할 수도 없고요.","id":"PRO_L04K1_zhongli_008","items":[{"k":"line","id":"PRO_L04K1_zhongli_009","speaker":"종려","text":"하나를 인정하기 위해 다른 하나를 지울 필요는 없네. 지켜 낸 것과 잃은 것을 함께 보아야 다음 선택이 가벼워지지 않겠지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_010","speaker":"","text":"종려는 군옥각이 사라진 하늘을 바라보았다. 제군이라는 호칭을 길 한가운데 던지면 곁을 지나가는 사람들의 이야기도 바뀔 수 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_011","speaker":"나","text":"따로 묻고 싶은 게 있어요. 제가 알고 있는 당신 일이요. 여기서 소리 높여 꺼내진 않겠습니다. 조용히 얘기할 자리 있어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_012","speaker":"종려","text":"마침 약속된 일을 마무리하러 가는 길이네. 북국은행에서 만나지. 답할 수 있는 것도, 없는 것도 있을 걸세. 그 차이는 그곳에서 말해 주겠네.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_101","text":"북국은행으로 가는 길에는 다시 가게를 여는 사람들이 있었다. 은행 안으로 들어가자 종려와 시뇨라가 먼저 보였다. 그 옆에 서 있는 타르탈리아를 본 순간 발이 멈췄다. 황금옥의 먼지 속으로 사라졌던 얼굴이 너무 멀쩡하게 그곳에 있었다."},{"k":"line","id":"PRO_L04K1_zhongli_013","speaker":"시뇨라","text":"몬드의 그 방해꾼이잖아. 여기까지 기어왔어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_014","speaker":"시뇨라","text":"끼어들 생각이면 지금 말해. 참아 줄 생각은 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_015","speaker":"나","text":"안 끼어듭니다. 당신들 계약을 제가 뒤집을 수 있다고 생각하지도 않아요. 끝난 뒤에 묻고 싶은 것만 묻겠습니다. 저쪽에 멀쩡하게 서 있는 사람한테도요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_016","speaker":"","text":"타르탈리아가 그 시선을 받고 눈썹을 올렸다. 낯선 적을 경계하는 것과 자신을 아는 상대를 흥미로워하는 기색이 섞여 있었다. 황금옥에서 보았던, 끝을 기다리는 듯한 눈길과 달랐다. 무기에 손을 댔다가 거두었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_017","speaker":"종려","text":"얼음의 여왕과 맺은 계약에 따라 약속한 것을 이행하겠네. 나의 신의 심장은 자네가 받아 전하게. 대가와 조건 역시 계약에 따라 지켜지기를 바라네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_018","speaker":"","text":"종려가 내민 신의 심장을 시뇨라가 받았다. 알고 있던 일이 눈앞에서 행동으로 확인되고 있었다. 거리에서는 여전히 물건 값을 흥정하는 소리가 들렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_019","speaker":"타르탈리아","text":"결국 나는 바깥에서 한참 뛰고, 마지막 얘기는 두 사람이 다 알고 있었던 거네요. 종려 씨, 숨겨 둔 패가 많은 건 알겠는데 이번엔 설명을 듣고 싶어지는군요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_020","speaker":"시뇨라","text":"네가 알아야 할 만큼은 알았어. 결과도 봤고. 여기서 네 기분까지 풀어 주는 건 내 일이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_021","speaker":"","text":"타르탈리아는 불쾌한 듯 웃었다. 자신만 모른 일에 짜증을 내면서도 대화를 놓치지 않는 반응. 그 모습에 더 불편해졌다. 이제야 내가 기억하던 타르탈리아와 닮아 보였기 때문이다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_022","speaker":"나","text":"종려 씨. 왜 그런 계약을 맺은 겁니까? 신의 심장을 넘길 만큼 뭘 받았어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_023","speaker":"종려","text":"모두 답할 수는 없네. 계약에는 비밀을 지킨다는 약속도 들어 있어. 자네가 겪은 위험을 가볍게 여겨서 말을 아끼는 것은 아니네.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_024","options":[{"label":"위험은 밖에서 몸으로 치르고, 값이 어떻게 정해졌는지는 못 듣는다는 게 참 기분 나쁘네요. 약속 어기라고 떼쓰진 않을게요. 그래도 제가 납득했다고 듣진 마세요.","id":"PRO_L04K1_zhongli_025","items":[{"k":"line","id":"PRO_L04K1_zhongli_026","speaker":"종려","text":"그러겠네. 침묵을 받아들였다는 것과 그 침묵에 만족한다는 것은 다른 일이니. 말할 수 없는 것을 다른 말로 꾸며 납득을 구하지도 않겠네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 약속 하나만 받을게요. 계약 때문에 말 못 하는 부분을 제 기억 탓으로 돌리지는 마세요. 요즘 제 기억만 남는 일이 너무 많아서요.","id":"PRO_L04K1_zhongli_027","items":[{"k":"line","id":"PRO_L04K1_zhongli_028","speaker":"종려","text":"자네가 기억한다고 말한 일을 내 편의를 위해 지우지는 않겠네. 다만 자네의 기억과 내가 말할 수 있는 사실 사이의 빈칸을 채웠다고 가장할 수도 없지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_029","speaker":"","text":"시뇨라는 받은 물건을 확인하고 몸을 돌렸다. 타르탈리아는 내 다친 팔을 살피다가 먼저 말을 걸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_030","speaker":"타르탈리아","text":"나한테도 할 말 있다고 했지. 그런데 그 표정은 처음 만난 사람한테 인사하는 표정이 아닌데. 그 상처하고 내가 무슨 관계야?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_031","speaker":"나","text":"황금옥에서 너하고 싸웠어. 네가 밀리고, 내가 끝내려는 순간 건물이 무너졌지. 나는 돌에 깔렸고 병사들이 꺼냈어. 넌 사라졌고. 기억해?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_032","speaker":"타르탈리아","text":"황금옥에서 너랑? 잠깐, 그건 내가 아는 일이 아닌데. 그 시간이 매끄럽지 않은 건 맞아. 하지만 너랑 칼 맞댄 기억은 없어. 이렇게 적의를 받는데 재미있게 싸웠다는 기억도 없다니, 나한테도 손해네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_033","speaker":"","text":"손이 굳었다. 각청에게 들었던 말이 다른 얼굴에서 돌아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_034","options":[{"label":"그때 너는 싸움이 즐거워 보이지 않았어. 끝나는 순간만 기다리는 것 같았고. 그런데 지금은 내가 알던 얼굴을 하네. 이걸 기억 못 한다는 말 하나로 넘기라고?","id":"PRO_L04K1_zhongli_035","items":[{"k":"line","id":"PRO_L04K1_zhongli_036","speaker":"타르탈리아","text":"넘기라고는 안 했어. 나도 누가 내 이름으로 네게 그런 기억을 남겼는지 알고 싶으니까. 그래도 없는 기억을 있는 척하진 않아. 칼로 확인하고 싶으면 상처부터 낫고 와.","map":"MAP_LIYUE_HARBOR"}]},{"label":"황금옥에서 우리가 싸웠다는 말 자체가 처음이야, 아니면 그때만 기억이 끊긴 거야? 둘을 같은 말로 넘기고 싶진 않아.","id":"PRO_L04K1_zhongli_037","items":[{"k":"line","id":"PRO_L04K1_zhongli_038","speaker":"타르탈리아","text":"그 시간만 끊겨 있어. 기억 못 한다는 말로 네가 겪은 일까지 없애려는 건 아니야. 그렇다고 맞장구칠 수도 없고. 칼로 확인하고 싶으면 상처부터 낫고 와.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_039","speaker":"나","text":"칼로 알 수 있는 일이었으면 황금옥에서 끝났겠지. 됐어. 기억나는 게 생기면 숨기지 마. 나도 본 걸 거짓말로 바꿔서 편해질 생각 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_040","speaker":"타르탈리아","text":"그 정도면 얘기할 여지는 있네. 다 낫고 나면 한 판 하자. 잊은 싸움으로만 평가받는 건 재미없거든.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_041","speaker":"나","text":"환자 앞에서 재경기 예약부터 잡는 거 봐. 지금은 예약 안 받아. 내 다음 목표는 밥집까지 안 업히고 가는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_128","text":"종려는 두 사람의 말을 듣고 있었다. 내가 돌아보자 그는 고개를 아주 조금 저었다. 모든 현상을 한마디로 설명할 답을 내놓지는 않았다. 계약을 아는 사람과 지금 벌어진 이상을 전부 아는 사람은 같지 않을 수 있었다."},{"k":"line","id":"PRO_L04K1_depart_001","speaker":"","text":"은행 밖으로 나오자 햇빛이 눈에 들어왔다. 도시를 구한 뒤에는 답이 이어질 줄 알았다. 손에 남은 것은 더 정확해진 질문들이었다. 모락스의 계획만으로 설명되지 않는 죽음, 살아 돌아온 사람들의 빈 기억, 내가 알던 사람과 달랐던 상대.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_002","speaker":"나","text":"이나즈마로 가 보자. 다음에 무슨 일이 있는지 안다고 자신할 생각은 없어. 그래도 이 세계가 내가 알던 이야기와 어디서 달라지는지 보려면 계속 움직여야지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_003","speaker":"나","text":"이번엔 '아는데'라는 말부터 좀 줄이고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_131","text":"그 결심을 입 밖에 낸 뒤 곧장 항구로 뛰어가지 않았다. 치료소에 돌아가 군의관에게 장거리 이동을 준비하고 싶다고 말할 차례였다. 목적지를 정하는 것과 당장 갈 수 있다는 것은 다르다는 정도는 이제 몸으로 알았다."},{"k":"line","id":"PRO_L04K1_depart_004","speaker":"나","text":"이나즈마로 갈 생각입니다. 바로는 아니고, 배편 알아보는 동안 치료 계속 받을게요. 중간에 건물 무너지는 일정은 제가 안 잡겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_005","speaker":"군의관","text":"그 일정은 앞으로도 잡지 마십시오. 이틀마다 상처 확인하고, 무거운 짐은 한쪽 어깨에 걸지 마세요. 항해 날짜가 정해지면 그 전에 다시 오십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_006","speaker":"","text":"각청은 해안 통행을 확인하러 가는 길에 나를 만났다. 처음처럼 내가 누구인지 묻지 않았다. 오늘 약속한 사람이 어느 자리에 앉아 있는지 알고 찾아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_007","speaker":"나","text":"나, 다음엔 이나즈마로 가려고. 그리고 진한테 내가 살아 있고 리월 위기는 일단 막았다고 알려야겠어. 치료 중이라는 말도 넣고. 다음 소식이 수색 요청이면 너무 미안하잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_008","speaker":"각청","text":"길드 정규 전달편에 맡기면 돼. 네가 본 이상한 일은 짧게 따로 적어. 추측까지 진이 본 사실처럼 쓰진 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_137","text":"치료소 책상에서 편지를 적었다. 살아남았고 치료 중이라는 소식, 바다의 위기를 막았다는 일, 다음 목적지를 알아보고 있다는 계획이었다. 길드 창구에 맡겼고 몬드행 전달편에 접수되었다는 답을 받았다."},{"k":"line","id":"PRO_L04K1_depart_009","speaker":"각청","text":"배편은 남십자 함대 쪽에도 물어봐. 만나면 황금옥에서 살아 나왔다는 얘기부터 자랑하지 마. 네 몸 상태를 과장하면 배에 태우는 사람도 곤란해져.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_depart_010","options":[{"label":"알았어. 선장한테는 얌전히 소개부터 할게. 너한테는…… 고마웠어. 내가 기억하는 닷새의 너한테도, 그걸 기억 못 하면서 다시 도와준 지금의 너한테도.","id":"PRO_L04K1_depart_011","items":[{"k":"line","id":"PRO_L04K1_depart_012","speaker":"각청","text":"둘을 따로 세워 두지 말라니까. 그 고맙다는 말은 지금 내가 들었어. 그걸로 됐어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_013","speaker":"각청","text":"돌아오면 그냥 이름 불러. 그때 내가 \"우리 어디서 만났지?\" 하면 그땐 진짜 화내도 돼.","map":"MAP_LIYUE_HARBOR"}]},{"label":"돌아오면 그냥 이름 부를게. 네가 모르는 닷새를 내가 매번 설명하면서 처음부터 다시 만나는 건 이제 그만하고 싶어.","id":"PRO_L04K1_depart_014","items":[{"k":"line","id":"PRO_L04K1_depart_015","speaker":"각청","text":"그래. 설명 안 해도 돼. 그 닷새는 네가 갖고 있어. 나는 오늘부터 생긴 걸 갖고 있을게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_016","speaker":"각청","text":"그때 내가 \"우리 어디서 만났지?\" 하면 그땐 진짜 화내도 돼.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_depart_017","speaker":"","text":"한동안 답하지 않고 웃었다. 돌아오라는 명령도, 머무르라는 부탁도 아니었다. 다시 만났을 때 서로 아는 사람으로 서고 싶다는 말이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_142","text":"다음 날 항구에 마련된 남십자 함대의 연락 장소로 갔다. 선장은 아직 만나지 못했고, 창구의 선원 역시 초면이었다. 이나즈마 방면의 출항 안내를 기다리는 사람들 곁에 서자 다음 여정을 준비하고 있다는 실감이 났다."},{"k":"line","id":"PRO_L04K1_depart_018","speaker":"나","text":"각청한테 남십자 함대 쪽에 물어보라고 소개받았습니다. 이나즈마 방면 운항하고 승선 상담 부탁드려요. 지금 치료 중이라 출발 전에 몸 상태도 다시 볼 거고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_019","speaker":"남십자 선원","text":"신청은 전하겠습니다. 선장님이 직접 물으실 겁니다. 출발 날짜가 정해진 걸로 생각하진 마십시오. 연락은 치료소로 드리면 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_020","speaker":"나","text":"네. 당분간 거기 있어요. 돌아갈 곳을 알려 두는 게 생각보다 중요하더라고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_021","speaker":"","text":"치료소에 돌아오자 칠성 쪽의 정산 담당자가 기다리고 있었다. 끝낸 일의 몫을 실제로 돌려받는 자리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_022","speaker":"정산 담당자","text":"지급액은 1,800모라, 영웅의 경험 두 개와 모험가의 경험 세 개입니다. 리월 방어에 참여하고 위험을 전달한 공적에 대한 정산입니다. 확인하신 뒤 받아 주십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_depart_023","options":[{"label":"확인했습니다. 1,800모라에 영웅의 경험 두 개, 모험가의 경험 세 개. 받을게요. 다음엔 돈 쓸 일이 치료보다 밥하고 배편 쪽에 많았으면 좋겠네요.","keep":"ISK_L04_K1_149","items":[{"k":"line","id":"PRO_L04K1_depart_024","speaker":"정산 담당자","text":"기록에 남겼습니다. 다음 몫도 밥값으로 쓰이기를 바라겠습니다.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_150","text":"치료소 창 너머의 바다 위에는 군옥각이 없었다. 잠깐 그 하늘을 올려다본 뒤 침상 곁의 여행 준비 메모로 눈을 내렸다. 이나즈마로 떠날 준비는 시작되었고, 아직 풀리지 않은 질문들은 함께 가지고 갈 것이었다."},{"k":"keep","id":"ISK_L04_K1_END"}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L04_K1_001_0","text":"바깥을 향해 손을 뻗었다. 큰 들보는 건드리지 않았다. 손끝에 닿는 작은 돌부터 옆으로 밀었다."},{"k":"text","id":"V141_AFTER_ISK_L04_K1_001_0","text":"작은 돌이 옆으로 굴렀다. 좁은 틈으로 빛이 들어오고, 바깥에서 받침을 부르는 소리가 가까워졌다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."},{"k":"text","id":"V141_BEFORE_ISK_L04_K1_073_0","text":"감우와 연비가 치료소를 찾아왔다. 고운각에서 함께 보고를 찾던 두 사람이, 이번에는 보고 대신 밥을 들고 왔다."}]},{"id":"ISK_L04_K2","entry":"ISK_L04_K2_001","items":[{"k":"keep","id":"ISK_L04_K2_001","hold":true,"text":"들보가 다리를 누르고 있었다. 몸을 일으키려 하자 통증에 숨이 턱 막혔다."},{"k":"line","id":"PRO_L04K2_rubble_001","speaker":"나","text":"……아, 안 돼. 다리가 안 빠져.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_002","speaker":"","text":"출구가 있던 쪽에서 돌 구르는 소리가 들렸다. 손에 잡힌 파편으로 바닥을 두드렸다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_003","speaker":"나","text":"거기…… 사람 있어요? 여기 있어요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_004","speaker":"천암군","text":"들립니다! 들어가신 통로를 따라왔습니다. 그 자리에서 움직이지 마세요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_005","speaker":"천암군","text":"앞이 막혔습니다. 목소리는 잘 들립니다. 손을 움직일 수 있습니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K2_rubble_006","options":[{"label":"손은 움직여요. 이쪽이에요. 소리 들려요?","id":"PRO_L04K2_rubble_007","items":[{"k":"line","id":"PRO_L04K2_rubble_008","speaker":"","text":"손에 쥔 파편으로 다시 두드렸다. 이번에는 바로 가까운 곳에서 대답이 돌아왔다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_009","speaker":"천암군","text":"들립니다. 그쪽부터 열겠습니다. 손은 잠깐 뒤로 빼 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"다리가 눌렸어요. 여기, 더 무너지는 건 아니죠?","id":"PRO_L04K2_rubble_010","items":[{"k":"line","id":"PRO_L04K2_rubble_011","speaker":"천암군","text":"바깥에서도 들보가 보입니다. 먼저 받치겠습니다. 혼자 다리를 빼려 하지 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_012","speaker":"","text":"바깥에서 받침을 부르는 소리가 이어졌다. 꽉 쥐었던 파편을 내려놓았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L04K2_rubble_013","speaker":"천암군","text":"손앞의 작은 파편부터 치우겠습니다. 몸을 누르는 들보는 건드리지 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_014","speaker":"나","text":"……이 작은 것만요. 손은 닿아요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"thru","id":"ISK_L04_K2_001"},{"k":"line","id":"PRO_L04K2_rubble_015","speaker":"천암군","text":"보입니다! 뒤쪽, 받쳐! 조금만 더……","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_016","speaker":"나","text":"아……! 잠깐, 다리가……!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_017","speaker":"천암군","text":"멈춰! 받침 그대로 잡아. 더 들지 마!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_018","speaker":"","text":"움직임이 멎었다. 천암군이 다시 신호를 맞추자 다리를 누르던 무게가 조금씩 줄었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_019","speaker":"나","text":"……타르탈리아는요? 그 사람은 나왔어요?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_020","speaker":"천암군","text":"우인단 집행관 말입니까? 안에 같이 있었습니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_021","speaker":"나","text":"네. 무너지기 전엔 바로 앞에 있었는데……","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_022","speaker":"천암군","text":"바깥에도 전하겠습니다. 먼저 손을 이쪽으로 뻗어 보십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_023","speaker":"","text":"돌 틈을 더듬던 손이 천암군에게 붙잡혔다. 미끄러질까 봐 손가락에 힘을 줬다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_024","speaker":"나","text":"……잡았어요. 놓지 마요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_025","speaker":"천암군","text":"놓지 않습니다. 여기 있으니 제 목소리를 듣고 계세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K2_007","text":"손이 팔 아래로 들어왔다. 병사 둘이 같은 속도로 몸을 끌어내자 거친 바닥이 옷을 긁었다. 바깥의 빛을 본 뒤에도 한동안 눈을 제대로 뜨지 못했다. 공기를 들이마시자 가슴이 들썩였고, 그 움직임이 아직 내 것이라는 사실이 이상했다. 타르탈리아가 있을 자리는 보이지 않았다."},{"k":"line","id":"PRO_L04K2_rubble_026","speaker":"군의관","text":"다리를 펴려고 힘주지 마세요. 눌렸던 곳부터 확인하겠습니다. 제가 만지는 곳이 느껴지면 말해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K2_rubble_027","options":[{"label":"받을게요. 치료해 주세요. 두 번 꺼내게 할 생각은 없습니다.","keep":"ISK_L04_K2_009","items":[{"k":"line","id":"PRO_L04K2_rubble_028","speaker":"군의관","text":"살아 있으니 치료하는 겁니다. 그 이상의 뜻은 나중에 생각하셔도 됩니다. 다리부터 보겠습니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K2_010","text":"군의관은 구호 상자를 열고 지혈에 쓸 천과 약품을 꺼냈다. 호흡과 눈의 반응을 살피고 눌린 다리의 감각을 확인한 뒤 상처를 씻었다. 잔해에서 꺼낸 몸은 살아 있었고 치료에 반응했다. 내가 왜 살아남았는지는 이 짧은 진찰만으로 알아낼 수 없었다."},{"k":"choice","group":"G_PRO_L04K2_rubble_029","options":[{"label":"바지 자르셔도 됩니다. 어차피 오늘 옷은 끝났어요. 옷값보다 다리값이 비싸다는 정도는 저도 압니다.","id":"PRO_L04K2_rubble_030","items":[{"k":"line","id":"PRO_L04K2_rubble_031","speaker":"군의관","text":"그렇게 말씀하시면 처치하기 편합니다. 다리값 아는 분이 처치 끝나자마자 뛰어가겠다고 하지만 않으면 됩니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_032","speaker":"나","text":"그 말이 복선처럼 들리는 건 왜일까요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_033","speaker":"군의관","text":"그런 분을 많이 봤으니까요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"저 다리 움직일 수 있을까요? 잘 걷겠다는 말은 아니고, 옆에서 받쳐 주면 어디까지 되는지 알고 싶어요.","id":"PRO_L04K2_rubble_034","items":[{"k":"line","id":"PRO_L04K2_rubble_035","speaker":"군의관","text":"감각과 움직임은 확인되고 있습니다. 처치한 뒤 부축받으며 천천히 서 보겠습니다. 걸을 수 있는 만큼과 버티고 싶은 만큼을 헷갈리지만 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K2_017","text":"붕대가 감기는 동안 먼 바다에서 일어난 거대한 움직임이 공기와 땅을 울렸다. 호위 병사 하나가 언덕 끝을 보고 돌아와, 항구에서 오셀에 맞선 방어가 시작되었다는 급한 연락을 전했다. 일어서려다 군의관의 손에 어깨를 눌렸다."},{"k":"line","id":"PRO_L04K2_rubble_036","speaker":"나","text":"알아요, 갑자기 일어나지 말라는 거죠. 그런데 저쪽은 가야 해요. 황금옥에서 막을 줄 알았는데 결국 바다가 움직였어요. 응광하고 각청한테 저 살아 나왔고 타르탈리아는 안 보인다고 전해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_037","speaker":"군의관","text":"호위대와 함께 이동하십시오. 다리를 끌면서 혼자 따라가는 건 허락하지 않겠습니다. 복선 맞았죠.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_038","speaker":"나","text":"……네.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K2_020","text":"병사의 어깨를 빌려 일어섰다. 안에서 만난 타르탈리아가 떠올랐다. 누군가를 찾는다는 말에도, 부하들의 상태에도 무심하던 얼굴이었다. 그러나 지금 그 얼굴을 붙잡으려 무너진 안으로 돌아가는 것은 사람들을 다시 위험 속에 세우는 일이었다. 바다를 향한 길을 골랐다."},{"k":"keep","id":"ISK_L04_K2_021","text":"병사들은 길의 완만한 부분을 골라 이동했다. 자꾸 부축을 받는 것이 미안했지만 그때마다 거절하면 오히려 더 늦어졌다. 한참 뒤 대피한 사람들이 모이는 항구 외곽의 넓은 길에 닿았다."},{"k":"line","id":"PRO_L04K2_porter_001","speaker":"","text":"사람들이 빠져나간 거리 한쪽에서 유리 깨지는 소리가 났다. 빈 가게였다. 보물 사냥단 셋이 자루를 메고 나왔다. 바다가 일어선 날에도 남의 물건부터 챙기는 사람은 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_002","speaker":"보물 사냥단","text":"비켜. 다리도 성치 않은 게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_003","speaker":"나","text":"그 말은 맞는데요. 비킬 다리가 없어서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_004","speaker":"","text":"호위 병사가 창을 내렸다. 나도 무기를 들었다. 다리 대신 팔로 하는 싸움이면 할 수 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"combat","id":"PRO_L04K2_porter_005","group":"EG_TREASURE_PATROL","text":"대피로 비어 버린 거리를 터는 보물 사냥단 습격조. 길을 막고 서 있으니 치울 수밖에 없다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_006","speaker":"","text":"자루가 바닥에 떨어지고 사냥단은 골목으로 흩어졌다. 병사가 자루를 가게 안으로 던져 넣고 문을 닫았다. 다시 걸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_007","speaker":"","text":"집결지 앞에서 수레 하나가 길을 가로막고 있었다. 사람을 태우려고 짐을 내린 수레였다. 앞쪽에서 누군가 끈을 당기는 병사에게 매듭을 너무 깊게 넣지 말라고 핀잔을 주었다. 걸음이 멎었다. 닷새 동안 들어 귀에 익은 목소리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_008","speaker":"짐꾼","text":"다시 풀어야 하는 매듭인데 그렇게 꽉 묶으면 칼로 끊어야 하잖소. 손 이쪽으로 빼고…… 거기, 당신 왜 그렇게 보고 있소? 어디 갔다가 그런 꼴로 돌아왔소? 같이 내려오기로 해 놓고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_009","speaker":"","text":"살아 있었다. 내가 들어 올리려다 끝내 두고 온 사람이 자기 발로 서서 남의 일을 거들고 있었다. 이름을 부를 수 없어서 그대로 앞으로 다가갔다. 짐꾼은 다친 다리를 보고 손을 내밀었다. 그 손을 잡자 어깨가 무너졌다. 차가웠던 몸과 따뜻한 손이 같은 사람의 것이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_010","speaker":"나","text":"……살아 계셨네요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_011","speaker":"나","text":"저, 당신을 거기 두고 나왔어요. 들려고 했는데 안 됐고, 무서워서 도망쳤어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_012","speaker":"짐꾼","text":"두고 나왔다니 어디서? 의례에 같이 간 건 기억하오. 그다음에 정신 차리니까 길 옆이었고, 내가 왜 거기 있는지 모르겠더군. 병사들이 쉬라고 했는데 바다가 난리라 여기로 옮겼소. 당신이 나를 찾는다는 말은 아까 들었는데, 대피하는 사이에 엇갈린 모양이오.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_027","text":"더 세게 손을 잡으려다가 놓았다. 손에 붕대를 감은 나를 보고 짐꾼이 얼굴을 찌푸렸기 때문이다. 의례에서 분명 이 사람의 죽음을 확인했다. 지금의 대답이 그 사실을 지우지는 않았다. 대신 죽었던 사람에게도 설명할 수 없는 시간이 있고, 그 뒤에 다시 시작된 하루가 있다는 것을 눈앞에서 보았다."},{"k":"choice","group":"G_PRO_L04K2_porter_013","options":[{"label":"자세한 건 나중에 해도 될까요? 지금은 당신이 여기 계신 것부터 좀 믿고 싶어요.","id":"PRO_L04K2_porter_014","items":[{"k":"line","id":"PRO_L04K2_porter_015","speaker":"짐꾼","text":"내가 설명할 수 있었으면 벌써 했겠지. 당신은 나를 두고 도망쳤다고 하고, 나는 돌아와서 나를 찾는 사람을 보고 있소. 둘 다 할 말이 많아 보이는데 바다가 잠잠해진 다음에 하오.","map":"MAP_LIYUE_HARBOR"}]},{"label":"각청은 저를 기억 못 해요. 당신은…… 닷새 동안 같이 있던 거, 기억하세요?","id":"PRO_L04K2_porter_016","items":[{"k":"line","id":"PRO_L04K2_porter_017","speaker":"짐꾼","text":"기억하오. 매듭 못 묶던 사람이 닷새째 되니까 포대는 안 떨어뜨리더군. 의례 다음부터가 비어 있는 거요. 그러니 지금 앞에 있는 사람부터 보시오. 할 말은 바다가 잠잠해진 다음에 하고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_porter_018","speaker":"","text":"웃으려다가 울음처럼 숨을 뱉었다. 각청에게서 잃은 닷새가 이 사람에게는 남아 있었다. 그 차이를 단서라고 부르고 싶지 않았다. 살아 있는 사람이 먼저였다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_porter_019","options":[{"label":"저는 군옥각 쪽으로 가요. 위에서 막는 동안 길을 지켜야 해요. 당신은 대피하는 사람들하고 같이 나가 주세요. 이번엔 자기 몸 하나만 챙기세요.","id":"PRO_L04K2_porter_020","items":[{"k":"line","id":"PRO_L04K2_porter_021","speaker":"짐꾼","text":"그 몸으로 또 가겠다고? 말리면 들을 얼굴도 아니군. 그럼 당신도 약속은 지키시오. 내려와서 짐 어찌 됐는지 같이 보기로 했잖소. 이번에는 끝까지 보고 나서 헤어지자고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"저는 군옥각 쪽 길을 지키러 가요. 짐 확인하러 만날 때까지 둘 다 멀쩡히 돌아오는 거, 먼저 약속해요.","id":"PRO_L04K2_porter_022","items":[{"k":"line","id":"PRO_L04K2_porter_023","speaker":"짐꾼","text":"그 약속이면 나도 할 수 있소. 짐 때문에 남으라는 부탁 안 하는 건 고맙군. 내려와서 짐 어찌 됐는지 같이 보기로 한 것도 잊지 마시오. 이번에는 끝까지 보고 나서 헤어지자고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_porter_024","speaker":"","text":"각청이 보낸 병사가 수색 보고를 가지고 다가왔다. 이번에는 찾았다는 소식이 실제로 목적지에 닿아야 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_025","speaker":"나","text":"찾았어요. 제가 찾던 분 맞고 살아 계세요. 각청한테도 그렇게 전해 주세요. 이분 대피하는 길부터 안내해 주시고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_026","speaker":"","text":"병사는 대피 조에 짐꾼을 인계하고 발견 소식을 각청에게 전했다. 그가 걸어가는 뒷모습을 오래 보지 않았다. 이번에는 어디로 가는지 알고 있었고, 다시 만날 일을 남겨 두었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_027","speaker":"각청","text":"찾았다는 보고 받았어. 다행이네. 수색 인원은 대피 쪽에 붙일게. 네 상태는 군의관한테 들었고. 정면에서 뛰어다닐 생각이면 지금 돌려보낸다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_028","speaker":"나","text":"정면으로 뛸 기운은 없어. 그래도 길 하나는 지킬 수 있으니까 맡겨 줘. 사람 찾았다고 나만 앉아 있기엔 저 바다가 너무 시끄럽잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_029","speaker":"각청","text":"군옥각 연결 지점. 선인들이 정면 막는 동안 뒤에서 장치 노리는 적을 끊어. 혼자 멀리 쫓아갔다가 다리 풀리면 네 몸 내가 들고 내려와야 돼. 그건 좀 싫어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_030","speaker":"나","text":"솔직해서 좋네.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_039","text":"각청은 나를 전투 인원에게 넘기며 다친 쪽을 분명히 알렸다. 누구도 그것을 듣고 도움이 안 된다고 말하지 않았다. 작은 몫을 실제로 끝내는 편이 큰일을 하겠다며 쓰러지는 것보다 나았다."},{"k":"keep","id":"ISK_L04_K2_040","text":"군옥각 위에서는 바람이 얼굴을 때렸다. 응광과 선인들의 힘이 바다를 향해 이어졌고, 그 빛 뒤로 병사들이 움직였다. 물결이 부딪칠 때마다 바닥이 흔들렸지만 곧바로 부서지지는 않았다."},{"k":"line","id":"PRO_L04K2_osial_001","speaker":"응광","text":"황금옥에서 살아 나온 손님이 돌아왔군. 지금은 의자를 내줄 수 없어. 뒤쪽 길을 부탁할게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_002","speaker":"나","text":"의자는 나중에 빌리겠습니다. 먼저 하나만요. 짐꾼 찾았어요. 살아 있고 대피 중입니다. 사람 붙여 주신 거 잊지 않을게요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_003","speaker":"응광","text":"좋은 소식 하나는 가져왔네. 그렇다고 다친 몸까지 잊지는 마. 네가 선 자리를 비우지 않는 게 지금 제일 큰 도움이야.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_004","speaker":"류운차풍진군","text":"이 몸이 바다를 막는 사이 연결 장치에 손을 대려는 것들이 있네. 장치를 살피겠다고 함부로 선 밖으로 나가지 말게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_005","speaker":"나","text":"알겠습니다. 오늘은 혼자 더 들겠다고 고집부리는 사람이 제일 먼저 지치는 날 같아서요. 저는 벌써 한 번 지쳤으니 자격이 있습니다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_006","speaker":"","text":"금속 부딪치는 소리가 뒤에서 울렸다. 연결로 끝에 나타난 습격자들이 방어 인원을 밀어내며 안쪽을 노렸다. 옆의 병사가 방패를 세웠고, 각청이 앞을 막는 동안 나는 그 틈으로 파고드는 적에게 무기를 겨누었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K2_047","text":"선인과 칠성이 오셀의 압력을 막는 동안, 군옥각의 연결 지점과 진법을 지키는 방어전이 시작된다."},{"k":"line","id":"PRO_L04K2_osial_007","speaker":"","text":"연결 지점을 향하던 적의 움직임이 마침내 꺾였다. 그러나 바다의 힘이 다시 장치를 덮치자 선인들이 펼친 방어가 크게 휘었고, 건물 아래로 떨어진 파편이 돌아오지 않는 깊이까지 내려갔다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_008","speaker":"류운차풍진군","text":"연결부가 더 버티지 못하겠네. 이 몸이 받아 낼 테니 안쪽 인원부터 물리게. 장치 붙잡으려고 남으면 구해야 할 사람만 느네!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_009","speaker":"","text":"응광은 남은 대피 인원과 손상된 지점을 빠르게 확인했다. 비서가 들고 가려던 상자에 시선이 갔다. 큰 상자는 두 사람이 들어야 했다. 그 곁에 서지 못하는 부상자가 있었다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_010","speaker":"나","text":"상자는 여기 놔요. 저 사람 먼저. 어깨 이쪽으로 잡아 주세요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_011","speaker":"","text":"비서는 상자를 내려놓았다. 의례장에서 짐꾼을 혼자 들어 올리려다 실패한 팔이었다. 이번에는 혼자가 아니었고, 들어야 할 사람도 숨을 쉬며 발을 움직이려 애썼다. 그 숨소리에 보폭을 맞췄다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_012","speaker":"응광","text":"군옥각을 포기하겠어. 남은 힘을 모아 바다로 떨어뜨릴 거야. 사람은 모두 옮겨. 가져갈 수 없는 물건은 두고 가. 여기 남는 건 내가 책임질 손해니까, 누구도 그것 때문에 목숨 걸 필요 없어.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K2_osial_013","options":[{"label":"아깝지 않다는 얼굴 안 하셔도 됩니다. 제가 먼저 버리라고 한 말 때문에 하는 선택처럼 남기지는 않을게요.","id":"PRO_L04K2_osial_014","items":[{"k":"line","id":"PRO_L04K2_osial_015","speaker":"응광","text":"이미 알고 있군. 그럼 두 번 말할 필요 없겠네. 내 결정을 네가 대신 짊어지려고 하지 마. 너는 네가 받친 사람을 놓지 않는 쪽에 힘을 써. 그게 내 집을 가장 값있게 떠나는 방법이야.","map":"MAP_OSIAL_BATTLE"}]},{"label":"제가 챙길 수 있는 사람부터 데리고 나갈게요. 나중에 제가 결단한 것처럼 말하지도 않겠습니다.","id":"PRO_L04K2_osial_016","items":[{"k":"line","id":"PRO_L04K2_osial_017","speaker":"응광","text":"그 말은 받아 두지. 설명은 살아서 내려간 뒤에도 할 수 있어. 네가 받친 사람을 놓지 않는 쪽에 힘을 써.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K2_osial_018","speaker":"","text":"선인들이 힘을 모으자 바람의 방향이 바뀌었다. 지나가다 문턱에 걸린 끈을 손으로 걷어 냈다. 풀어야 하는 매듭을 너무 깊게 넣지 말라던 목소리가 떠올랐다. 떠나야 할 때 붙잡는 것은 좋은 매듭이 아니었다.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K2_osial_019","options":[{"label":"뒤쪽 상자는 놔두고 왔어. 주인 허락받았으니까 물건 찾으러 돌아갈 사람 없게 해 줘. 이제 우리도 빠지면 되는 거지?","id":"PRO_L04K2_osial_020","items":[{"k":"line","id":"PRO_L04K2_osial_021","speaker":"각청","text":"맞아. 더 돌아갈 이유 없어. 부상자는 저쪽이 받았으니 네 손도 빼. 사람 다 내보내고 너만 뒤에 남으면 그게 끝난 거야? 아니지.","map":"MAP_OSIAL_BATTLE"}]},{"label":"내가 맡은 사람은 넘겼어. 이제 나도 좀 부축받아도 되겠지? 괜찮은 척하는 재주가 늘어서 그게 제일 걱정이야.","id":"PRO_L04K2_osial_022","items":[{"k":"line","id":"PRO_L04K2_osial_023","speaker":"각청","text":"그 말은 잘했어. 팔 이쪽으로 걸어. 다리에 힘 없으면 그만큼 내가 받으면 돼. 너 생각보다 무겁진 않네.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_024","speaker":"나","text":"그건 칭찬이야?","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_025","speaker":"각청","text":"보고야.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K2_osial_026","speaker":"","text":"소가 남은 사람들의 위치를 확인하고 선인들이 빠져나갈 길을 붙들었다. 바닥이 기울면서 발이 미끄러졌지만 옆의 손이 나를 잡았다. 응광이 힘을 내려 보내는 순간 군옥각은 도시를 받치던 높이를 버리고 바다를 향해 떨어졌다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_027","speaker":"","text":"거대한 충격이 하늘과 물을 갈랐다. 조금 전까지 사람을 들고 나오던 문과, 그 뒤에 두고 온 상자와, 손님을 위해 비워졌던 의자가 하나의 빛 속으로 사라졌다. 오래 도시를 위협하던 울림이 마침내 잦아들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K2_065","text":"안전지대에 내려왔을 때 나는 한동안 팔을 둥글게 든 채 있었다. 이미 다른 인원에게 넘긴 부상자의 무게가 아직 몸에 남아 있었다. 각청이 어깨에서 손을 빼도 된다고 말하자 그제야 팔을 내렸다. 살아 있는 이들의 이름을 부르는 소리가 올라왔다."},{"k":"keep","id":"ISK_L04_K2_066","text":"해안의 급한 대피는 멈췄고 전투 인원은 남은 사람을 확인하기 시작했다. 군옥각을 잃었지만 도시 전체가 그 뒤를 따라 가라앉지는 않았다. 서로의 빈자리를 받치며 버틴 끝에, 응광과 선인들이 마지막 결정을 실행한 결과였다."},{"k":"line","id":"PRO_L04K2_osial_028","speaker":"나","text":"끝났다는 게 이런 소리였구나. 나 잠깐 앉을게. 이번에는 어디 안 가. 다리가 더는 내 의견을 안 받아 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_osial_029","speaker":"각청","text":"앉아. 군의관 올 거야. 어디 안 간다는 말은 여기 있는 사람들 다 들었으니까 혼자 일어나지 마. 네가 찾던 사람도 대피소 도착한 거 확인됐어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_osial_030","speaker":"나","text":"……고마워.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_osial_031","speaker":"각청","text":"그 말 하려고 그 얼굴 하는 거야? 쉬고 나서 해.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_069","text":"치료 구역에서 군의관은 다시 벌어진 상처를 살피고 붕대를 갈았다. 다친 다리에 과하게 힘을 준 탓에 붓기가 늘었지만 감각과 움직임은 남아 있었다. 아픈 곳을 아프다고 말하는 일이 오히려 쉬워졌다."},{"k":"line","id":"PRO_L04K2_name_001","speaker":"나","text":"이번엔 정말 쉬겠습니다. 다만 사람 하나가 찾아오면 저 여기 있다고 알려 주세요. 짐꾼이고, 의례 전에 저하고 같이 지냈던 분이에요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_002","speaker":"군의관","text":"접수 담당자에게 말해 두겠습니다. 사람 만나면 설명하느라 흥분해서 일어나지 마세요. 오늘은 치료받는 역할입니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_003","speaker":"나","text":"역할 배정이 확실하네요. 대본대로 할게요.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_072","text":"누워서 천막 위를 보았다. 짐꾼이 언제 올지 기다리는 동안 잠이 들었다. 깨어났을 때는 낮이 지나 있었고, 침상 옆의 의자에 익숙한 사람이 앉아 있었다. 의례장에서 내려놓았던 몸이 이번에는 제 팔을 무릎 위에 얹고 꾸벅꾸벅 졸고 있었다."},{"k":"line","id":"PRO_L04K2_name_004","speaker":"나","text":"의자 불편하면 깨우시지 그랬어요. 그렇게 자면 허리 더 아프잖아요. 그런데…… 다시 와 주셨네요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_005","speaker":"짐꾼","text":"누운 사람 깨워 놓고 나 쉬겠다고 할 수는 없잖소. 당신이 먼저 찾아오겠다더니 몸을 그 꼴로 만들어 놓아서 내가 왔지. 내려오면 이야기하자던 약속은 지켜야 하니.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_006","speaker":"","text":"짐꾼이 살아 있는지 다시 손목을 확인하지 않았다. 잠에서 깬 사람이 뻣뻣해진 허리를 펴고 물을 찾는 모습을 보았다. 닷새 동안 너무 흔해서 흘려보냈던 행동들이 전부 선명했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_007","speaker":"나","text":"제대로 말할게요. 의례에서 사람들이 한꺼번에 죽었어요. 당신 숨도 맥박도 없었고, 제가 들어 올리려다 못 했어요. 당신이 잘못 기억한다는 말은 아니에요. 제가 왜 그렇게 굴었는지 알아 주셨으면 해서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_008","speaker":"짐꾼","text":"그 말을 들으니 당신 얼굴은 이해가 되오. 나는 내가 그렇게 됐다는 감각이 없소. 안다고 거짓말해 줄 수도 없고. 그래도 당신이 찾으러 돌아왔다는 건 알지. 당신이 나를 두고 왔다고 계속 자기를 붙들면, 지금 찾아온 나는 어디 서 있어야 하오?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_009","speaker":"","text":"시선을 내렸다가 다시 들었다. 죽음을 기억하는 사람만 대화의 중심에 두면 살아 돌아온 사람이 자기 이야기를 할 자리가 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_name_010","options":[{"label":"그러네요. 이름부터 알려 주세요. 닷새를 같이 있었는데 짐꾼이라고만 부른 게 이제 와서 너무 미안해요.","id":"PRO_L04K2_name_011","items":[{"k":"line","id":"PRO_L04K2_name_012","speaker":"짐꾼","text":"미안할 일까지는 아니오. 일터에서는 늘 그렇게 불리니. 그래도 이름을 묻는 건 좋군. 적어 주겠소. 당신도 적어 주시오. 다음에 누가 찾으러 와도 서로 설명하기 편하게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 오늘은 제가 설명하는 쪽을 줄일게요. 당신이 정신 차린 다음 얘기를 듣고 싶어요. 누가 물 줬는지 같은 것부터요.","id":"PRO_L04K2_name_013","items":[{"k":"line","id":"PRO_L04K2_name_014","speaker":"짐꾼","text":"길가에 앉아 있는데 한 아주머니가 물을 줬소. 내가 짐부터 찾겠다고 일어나니까 당신하고 똑같이 고집부린다고 핀잔도 주고. 이름은 못 물었지. 그러고 보니 당신한테도 내 이름을 말한 적이 없군. 적어 주겠소. 당신도 적어 주시오.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_name_015","speaker":"","text":"짐꾼은 종이에 자기 이름과 찾을 수 있는 작업 구역을 적어 주었다. 종이를 받아 이름을 읽고서 짐꾼의 얼굴을 다시 보았다. 장록. 닷새 동안 포대 뒤에 가려져 있던 이름이 두 글자로 손 안에 놓였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_016","speaker":"나","text":"장록 씨.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_017","speaker":"나","text":"……이제야 부르네요. 제 이름하고 지금 머무는 곳도 적어 드릴게요. 몸 좀 나아지면 포대 확인하러 같이 가요. 이번엔 끝나는 것까지 옆에서 볼게요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_018","speaker":"장록","text":"그렇게 불리니까 일터가 아니라 집 같군. 됐소, 포대는 안 도망가오. 당신 다리가 먼저지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_019","speaker":"","text":"나도 내 이름과 당분간 머무는 치료소를 적어 건넸다. 서로를 부르는 데 더는 막연한 설명이 필요하지 않았다. 그 종이가 사라진 시간을 되돌리지는 않았지만 다음 만남을 마련하는 데는 도움이 되었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_088","text":"다음 이틀 동안 재진료를 받으며 짧게 걷는 연습을 했다. 장록은 자신의 작업 구역과 치료소를 오가며 필요한 소식을 전했다. 그가 겪은 빈 시간은 돌아오지 않았지만, 지금 어디에 머무는지 모르는 사람으로 다시 사라지지는 않았다."},{"k":"line","id":"PRO_L04K2_name_020","speaker":"각청","text":"오늘 리월항 일반 봉쇄 해제해. 황금옥 잔해랑 해안 파손 구역만 계속 막고. 너희가 기다리던 포대도 상대랑 검수 인원 불러서 확인할 거야. 이번엔 기억 말고 실제 물건을 같이 보면 돼.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_021","speaker":"나","text":"좋아. 지난번에 내가 본 건 끈 풀린 것까지였고 안에 뭐가 있었는지는 못 봤어. 그건 그대로 말할게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_022","speaker":"각청","text":"그리고 천천히 걸어. 끝까지 같이라고 해 놓고 중간에 또 쓰러지면 그 아저씨가 널 들고 가야 되잖아. 허리 아프시다며.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_023","speaker":"나","text":"소문이 빠르네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_024","speaker":"각청","text":"치료소 전부가 알아.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_091","text":"각청은 통행을 재개한 길을 안내하고 검수 인원에게 시간을 알렸다. 나와 장록은 그 길을 함께 걸었다. 전에 기다리던 자리에 포대가 있었고, 물건을 넘겨받을 담당자가 도착해 있었다. 끈을 풀고 내용물과 수량을 확인하는 동안 나는 옆에서 지켜보았다. 지금 새로 인계할 수 있게 된 자리였다."},{"k":"keep","id":"ISK_L04_K2_092","text":"상대가 물건을 확인하고 인수 증서를 건넸다. 장록은 서명을 마친 뒤 증서와 빈손을 번갈아 보았다. 누구의 기억이 옳았는지 싸우느라 멈춰 있던 일이, 현재의 물건을 함께 확인하는 일로 마침내 끝났다. 장록은 어깨를 한 번 크게 돌리고 내 쪽으로 몸을 돌렸다."},{"k":"line","id":"PRO_L04K2_cargo_001","speaker":"장록","text":"끝났군. 이거 하나 내려놓는 데 무슨 일이 이렇게 많았는지. 당신이 내 짐을 대신 든 건 없지만, 끝까지 같이 본 사람은 됐소. 그건 기억할 수 있겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_cargo_002","options":[{"label":"대신 안 들어도 한몫은 했네요. 그럼 이제 제 다리 핑계로 밥집까지는 장록 씨가 천천히 걸어 주세요. 비싼 집 고르자는 뜻은 아니고요.","id":"PRO_L04K2_cargo_003","items":[{"k":"line","id":"PRO_L04K2_cargo_004","speaker":"장록","text":"말은 여전히 뻔뻔하군. 됐소, 길가에서 먹을 만한 데는 알아. 먹고 나면 나는 집에 소식부터 보낼 거요. 당신도 기다리는 사람 있으면 알리시오. 없다 해도 돌아올 곳은 하나쯤 적어 두고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"밥 먹고 나면 서로 소식 보낼 곳부터 정리하죠. 살아 있다고 알리는 걸 저는 자꾸 일이 다 끝난 다음으로 미뤘거든요.","id":"PRO_L04K2_cargo_005","items":[{"k":"line","id":"PRO_L04K2_cargo_006","speaker":"장록","text":"좋은 순서군. 배부터 채우고, 기다리는 사람한테도 밥이 넘어갈 만한 소식을 보내자고. 길가에서 먹을 만한 데는 알아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_096","text":"두 사람은 길가의 식당에서 천천히 한 끼를 먹었다. 장록은 다음에 맡을 일과 집에 보낼 소식을 이야기했고, 나는 듣다가 내 몫의 국물을 마셨다. 의례장에서 두고 온 사람의 이야기가 그 장면에서 멈추지 않았다. 지금의 그는 다음 일을 고르는 사람이었다."},{"k":"keep","id":"ISK_L04_K2_097","text":"응광과 선인들을 다시 만난 것은 그날 늦은 오후였다. 군옥각 대신 임시로 마련한 공간에서 피해 보고와 이후의 경계를 논하고 있었다. 전투의 규모에 비하면 작은 이야기였지만, 이번에는 스스로 작은 말로 줄이지 않기로 했다."},{"k":"line","id":"PRO_L04K2_council_001","speaker":"나","text":"찾던 분은 살아 계시고 화물 인계도 끝났습니다. 장록이라는 분이에요. 의례 그 순간은 기억 못 하지만 저랑 기다리던 닷새는 기억하세요. 수색 계속해 주신 덕분이에요. 바다 얘기에 묻히기 전에 직접 전하고 싶었습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_002","speaker":"응광","text":"잘 전해 줬어. 도시를 지킨 뒤 남겨야 할 게 거대한 승리 이야기만은 아니니까. 다만 기억의 빈칸은 계속 남아 있군. 네가 본 것과 그 사람이 기억하는 것을 따로 적어 두겠어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_003","speaker":"류운차풍진군","text":"산에서 자네가 그 사람을 두고 왔다며 괴로워하던 모습을 기억하네. 다시 만났으니 이 몸도 다행이라 생각하네. 허나 기쁜 일과 설명할 일을 한데 섞어 억지 답을 만들지는 말게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_004","speaker":"나","text":"처음에는 살아 있는 사람만 보면 어떻게 살아 있냐고 붙들었는데, 그분이 그러더라고요. 그렇게만 묻고 있으면 지금 찾아온 자기는 어디 서 있느냐고. 좀 부끄러웠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_005","speaker":"각청","text":"그래서 지금 할 수 있는 일을 다시 정하는 거예요. 바다 경계는 선인들께 도움받아 계속하고, 통행이랑 생활은 저희가 돌려놓겠습니다. 선언보다 매일 그 일을 끝내는 쪽이 보여 주는 게 더 많겠죠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_006","speaker":"류운차풍진군","text":"자네의 뜻은 들었네. 이번에는 직접 지키고 직접 내놓는 것을 보았지. 서로 확인할 길을 남겨 두는 편이 낫겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_007","speaker":"응광","text":"연락할 길은 열어 둘게요. 군옥각을 잃었다고 리월의 결정까지 공중에 매달려 사라진 건 아니니까요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_council_008","options":[{"label":"저도 리월에서 더 할 일 있으면 알려 주세요. 다만 군의관이 무거운 짐은 아직 들지 말랬어요. 산 뛰어 올라가는 일은 며칠만 뒤로 미뤄 주시면 좋겠습니다.","id":"PRO_L04K2_council_009","items":[{"k":"line","id":"PRO_L04K2_council_010","speaker":"류운차풍진군","text":"이 몸이 자네를 급한 전갈에만 쓰려고 기다리는 줄 아는가. 자네 다리가 낫는 동안에도 날 수 있는 자들은 있네. 몸부터 돌보게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"몸이 나을 때까지는 전달이나 설명 정도로 돕겠습니다. 할 수 있는 범위를 먼저 말씀드리는 게 낫겠죠.","id":"PRO_L04K2_council_011","items":[{"k":"line","id":"PRO_L04K2_council_012","speaker":"류운차풍진군","text":"그 범위를 아는 것도 책임이지. 의지가 있다는 이유로 몸의 상태를 지울 수는 없네. 몸부터 돌보게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_council_013","speaker":"","text":"그 잔소리를 다시 들을 수 있다는 사실이 나에게는 위로였다. 소는 문밖에서 시선을 돌려 나를 보았다. 황금옥으로 가기 전 돌아올 길을 보라고 했던 사람이었다. 이번에는 고개를 숙여 인사했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_014","speaker":"나","text":"그때 돌아올 길 보라고 하신 말씀, 도움이 됐어요. 관리 통로로 들어간 걸 병사들한테 남겼고, 그 길을 기억해서 저를 찾았대요. 저 혼자 잘해서 나온 건 아니었습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_015","speaker":"소","text":"살아 돌아왔으면 됐어. 다음에도 길을 남겨. 너를 찾는 사람도 생겼으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_001","speaker":"","text":"면담이 끝난 뒤 임시 집무 공간을 나서자 종려가 길가에서 기다리고 있었다. 그의 얼굴을 알아보았지만 다가가며 오래된 친구처럼 부르지는 않았다. 류운차풍진군은 두 사람을 잠깐 보고 먼저 다른 선인들과 이동했다. 옛 인연을 설명하는 말은 남기지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_002","speaker":"종려","text":"나는 왕생당의 객경, 종려라고 하네. 자네가 리월에서 겪은 일이 적지 않다고 들었어. 몸이 괜찮다면 잠깐 이야기를 나누고 싶군. 다리가 불편하면 앉을 곳부터 찾지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_003","speaker":"나","text":"종려 씨. 성함은 알고 있습니다. 어디부터 물어야 할지 모르는 사람을 길가에서 만나니까 이상하네요. 우선 앉자는 데는 전적으로 동의합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_114","text":"두 사람은 가까운 차 자리로 옮겼다. 종려는 내가 자세를 잡은 뒤 차를 권했다. 의례와 폐허 사이를 오간 뒤 처음으로 누군가와 뜨거운 잔이 식기를 기다리는 시간이 생겼다."},{"k":"line","id":"PRO_L04K2_zhongli_004","speaker":"나","text":"사람들이 제군 없이 리월을 지켰다고 하더라고요. 맞는 말인데 화가 납니다. 시험당한 사람들은 시험이라고 들은 적이 없잖아요. 하루 벌어 먹고살던 사람은 그날도 짐 들러 나온 거였고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_005","speaker":"종려","text":"사람의 하루는 더 큰 목적이 있다는 이유로 가벼워지지 않네. 자네가 화를 내는 것은 이해하네. 하지만 리월 사람들이 이번에 한 선택까지 다른 누군가의 생각 속으로 돌려놓을 필요는 없을 걸세.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_006","options":[{"label":"그건 알아요. 응광이 군옥각을 포기한 건 직접 고른 일이었어요. 그래서 더 묻고 싶어요. 누군가는 얼마나 알고 있었고, 누군가는 왜 아무것도 모른 채 버텨야 했는지.","id":"PRO_L04K2_zhongli_007","items":[{"k":"line","id":"PRO_L04K2_zhongli_008","speaker":"종려","text":"자네가 나에 대해 알고 있다고 여기는 부분도 있겠군. 여기서 이름을 크게 확인하려 하지 않는 걸 보니 어디까지 말할지는 생각하고 온 모양이네. 답할 수 있는 일은 직접 답하겠어. 다만 모든 질문에 같은 범위의 대답을 줄 수는 없지.","map":"MAP_LIYUE_HARBOR"}]},{"label":"사람들이 무슨 위험을 감수하는지 알고 선택할 기회는 있었는지 묻고 싶어요. 제가 아는 이름 확인받는 것보다 그게 더 걸립니다.","id":"PRO_L04K2_zhongli_009","items":[{"k":"line","id":"PRO_L04K2_zhongli_010","speaker":"종려","text":"책임의 범위를 묻는 질문으로 듣겠네. 답할 수 있는 일은 직접 답하겠어. 모든 질문에 같은 범위의 대답을 줄 수는 없지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_zhongli_011","speaker":"나","text":"그럼 하나만요. 의례에서 사람들이 실제로 죽고 다시 나타난 일, 그것도 당신이 의도한 겁니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_012","speaker":"종려","text":"자네가 겪었다는 그 죽음과 기억의 빈자리를 내가 계획한 시험의 결과라고 말해 줄 수는 없네. 내가 설명할 수 있는 계획이 있다는 이유로 그 밖의 모든 현상을 거기에 넣어서는 안 되지. 자네가 본 일은 그 자체로 살펴야 할 일이네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_013","speaker":"","text":"잔을 내려놓았다. 모든 일이 하나의 손에서 나왔다고 들으면 미워할 사람을 정하기는 쉬웠을 것이다. 그러나 그 대답은 내가 아는 이야기와 지금 벌어진 일 사이에 다시 경계를 그었다. 답답했지만 없는 다리를 밟고 건너가는 것보다는 나았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_014","speaker":"나","text":"그럼 남은 질문은 계약 쪽이겠네요. 물을 수 있는 자리에서 직접 묻고 싶습니다. 당신 가는 곳에 따라가도 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_015","speaker":"종려","text":"북국은행에서 마무리할 일이 있네. 그곳으로 오게. 다만 자네가 내 답에 만족할 것이라고 미리 약속할 수는 없겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_016","options":[{"label":"솔직한 초대네요. 대답이 마음에 안 들어도 컵은 안 던질게요. 치료비 내고 나면 남의 그릇값까지 물 여유가 없어서요.","id":"PRO_L04K2_zhongli_017","items":[{"k":"line","id":"PRO_L04K2_zhongli_018","speaker":"종려","text":"그릇을 지켜 준다니 다행이군. 불만은 말로 전하게. 적어도 무엇이 답답한지는 더 분명히 들을 수 있을 테니.","map":"MAP_LIYUE_HARBOR"}]},{"label":"알겠습니다. 다만 제 말이 거칠어져도 못 배운 사람 취급은 하지 마세요. 오늘은 모르는 값이 좀 컸습니다.","id":"PRO_L04K2_zhongli_019","items":[{"k":"line","id":"PRO_L04K2_zhongli_020","speaker":"종려","text":"질문이 거칠다는 이유로 그 안의 일을 못 들은 척하지는 않겠네. 자네도 대답을 듣기 전에 정한 결론이 있다면 잠깐 내려놓고 오게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_130","text":"북국은행에 들어섰을 때 시뇨라를 먼저 보았다. 옆에 선 타르탈리아가 고개를 돌렸다. 멀쩡한 얼굴이었다. 붕대 아래 손가락을 움켜쥐었다. 잔해와 함께 사라진 상대가 살아 있는 사람들 사이에서 대화를 나누고 있었다."},{"k":"line","id":"PRO_L04K2_zhongli_021","speaker":"시뇨라","text":"몬드의 그 방해꾼이잖아. 리월까지 기어왔어? 그 다리는 또 어디서 나서다 얻은 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_022","speaker":"시뇨라","text":"끼어들 생각이면 지금 말해. 참아 줄 생각은 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_023","speaker":"나","text":"안 끼어듭니다. 계약 자리에 주먹부터 들이밀러 온 건 아니에요. 다만 그 계약 때문에 묻고 싶은 게 있고, 저 사람한테도 할 말이 있습니다. 끝나면 제 차례도 좀 남겨 주세요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_024","speaker":"타르탈리아","text":"나한테? 시뇨라한테 한 소리 듣고도 눈은 계속 이쪽이네. 종려 씨 거래부터 끝내는 게 좋겠군요. 나도 그 설명 기다리던 중이라서.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_025","speaker":"","text":"그 말투에 눈을 가늘게 떴다. 기분이 나빠도 상대와 한 번 부딪쳐 보고 싶어 하는 온도가 있었다. 황금옥에서는 같은 입가의 웃음이 비어 보였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_026","speaker":"종려","text":"얼음의 여왕과 맺은 계약에 따라 나의 신의 심장을 넘기겠네. 시뇨라, 자네가 받아 전하게. 약속한 대가와 조건도 그대로 지켜져야 하겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_027","speaker":"","text":"시뇨라가 신의 심장을 받았다. 종려가 모락스라는 사실은 알고 있었지만, 그 힘의 상징이 다른 손으로 넘어가는 일은 처음 보는 현실이었다. 문밖을 향해 누구의 이름도 외치지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_028","speaker":"타르탈리아","text":"나는 내 방식대로 움직이고 있다고 생각했는데, 뒤에서는 이미 합의가 돼 있었던 거군요. 적어도 언제부터 어디까지 알고 있었는지는 들을 수 있겠죠?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_029","speaker":"시뇨라","text":"네가 알아야 할 만큼은 알았어. 결과도 봤고. 여기서 네 기분까지 풀어 주는 건 내 일이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_030","speaker":"나","text":"그 불만은 저도 있어요. 종려 씨, 왜 그 계약을 맺은 겁니까? 신의 심장을 넘길 만큼 뭘 받았어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_031","speaker":"종려","text":"이번 계약에는 그 이유와 내용을 밖에 밝히지 않겠다는 약속도 들어 있네. 자네가 겪은 위험을 가볍게 여겨서 말을 아끼는 것은 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_032","options":[{"label":"그러면 저는 끝까지 모르는 채로 아픈 기억만 들고 나가겠네요. 그렇다고 제가 이해했다거나 괜찮다고는 말하지 않겠습니다. 그건 제 입으로도 거짓말이니까요.","id":"PRO_L04K2_zhongli_033","items":[{"k":"line","id":"PRO_L04K2_zhongli_034","speaker":"종려","text":"그렇게 받아들이겠네. 자네에게 없는 납득을 만들어 달라고 요구할 수는 없지. 다만 자네가 리월을 지키기 위해 한 일에 대한 감사까지 비밀로 둘 이유는 없네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"지금 답 못 하는 질문은 그대로 남겨 둘게요. 설명 못 들은 자리에 제가 멋대로 이유를 채워 넣지는 않겠습니다. 대신 아직 납득 안 했다는 것도 같이 기억해 주세요.","id":"PRO_L04K2_zhongli_035","items":[{"k":"line","id":"PRO_L04K2_zhongli_036","speaker":"종려","text":"답을 얻지 못했다는 사실을 정확히 남기는 것도 중요하지. 침묵을 동의로 받아들이지는 않겠네. 자네가 리월을 지키기 위해 한 일에 대한 감사까지 비밀로 둘 이유는 없네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_zhongli_037","speaker":"나","text":"타르탈리아, 황금옥에서 있었던 일 기억해? 나하고 싸웠고, 네가 밀리다가 바닥이 무너졌어. 너는 먼지 속으로 사라졌고 나는 깔렸다가 병사들이 꺼냈어. 그중에 기억나는 거 있어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_038","speaker":"타르탈리아","text":"네가 황금옥에서 나와 싸웠다고? 처음 듣는 얘기야. 그 무렵이 끊겨 있는 건 나도 알아. 하지만 너랑 싸운 장면은 없어. 내가 밀렸다는 말까지 붙으니 더 직접 확인하고 싶어지는군. 다친 몸을 지금 상대하겠다는 뜻은 아니고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_039","speaker":"나","text":"그때 너는 내가 찾는 짐꾼 얘기를 해도 아무 관심이 없었어. 싸움을 즐기는 게 아니라 내가 어디까지 오는지만 기다리는 것 같았어. 지금 너는 그때하고 느낌이 달라. 본인도 모른다는 거야?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_040","speaker":"타르탈리아","text":"없는 기억을 꾸며서 맞장구쳐 줄 수는 없지. 네가 묘사하는 내가 좀 기분 나쁜 상대라는 건 알겠어. 누가 내 일에 손을 댄 건지, 내가 놓친 게 있는지부터 알아봐야겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_041","speaker":"","text":"기억이 없다는 사람에게 기억하라고 소리쳐도 답이 생기지 않는다는 것은 이미 배웠다. 장록 앞에서 들은 말을 적 앞에서도 써야 한다는 사실이 썩 반갑지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_042","speaker":"나","text":"좋아. 기억나는 게 생기면 사람 보내. 나도 본 걸 안 봤다고 바꾸지는 않을 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_043","speaker":"타르탈리아","text":"그 정도면 얘기할 여지는 있네. 다 낫고 나면 한 판 하자. 잊은 싸움으로만 평가받는 건 재미없거든.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_044","speaker":"나","text":"환자 앞에서 재경기 예약부터 잡는 거 봐. 지금은 예약 안 받아. 내 다음 목표는 밥집까지 내 다리로 가는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_152","text":"타르탈리아가 웃었다. 그 웃음을 보면서도 손을 내밀지는 않았다. 지금의 가벼움과 황금옥의 낯섦은 둘 다 기억해 두기로 했다. 오늘 당장 대답이 나올 질문을 모두 썼다는 것을 알았다."},{"k":"line","id":"PRO_L04K2_depart_001","speaker":"","text":"북국은행을 나와 사람들 사이에 섞여 천천히 걸었다. 이곳에서 같은 질문을 반복한다고 모든 답이 열릴 것 같지는 않았다. 내가 아는 이야기와 실제로 벌어진 일의 차이는 한 도시에서 시작해 한 도시에서 끝나는 것처럼 보이지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_002","speaker":"나","text":"다음엔 이나즈마로 가야겠어. 거기서 답이 나온다고 장담은 못 하지만, 신을 만나 물을 길도 더 찾아봐야지. 이번엔 가기 전에 어디로 가는지도 남기고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_003","speaker":"나","text":"'아는데'라는 말도 좀 줄이고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_155","text":"바로 배를 찾아 달려가지 않았다. 치료소로 돌아와 여행 준비를 하고 싶다는 말을 군의관에게 먼저 꺼낼 차례였다. 황금옥에서 살아 나왔다고 그 뒤의 위험이 모두 나를 비껴가는 것은 아니었다."},{"k":"line","id":"PRO_L04K2_depart_004","speaker":"나","text":"이나즈마행 배편을 알아보려고요. 당장 떠나겠다는 건 아니에요. 항해 전에 어디까지 회복돼야 하는지 알려 주세요. 몸 괜찮다는 말을 제가 혼자 먼저 정하지는 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_005","speaker":"군의관","text":"그렇게 준비하시면 됩니다. 무거운 짐 메지 말고, 걷다가 어지럽거나 다리 감각이 달라지면 바로 돌아오세요. 출항 날짜가 정해지면 그 전에 다시 진료받으십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_158","text":"장록에게는 다음 날 만나는 자리에서 여행할 뜻을 전하기로 했다. 그는 이제 기다릴 화물이 없는 사람이었고, 나는 새로 챙길 짐이 생긴 사람이었다. 서로의 일이 끝나야만 헤어질 수 있다고 붙들 이유는 없어졌지만, 말 없이 사라질 이유도 없었다."},{"k":"line","id":"PRO_L04K2_depart_006","speaker":"나","text":"저는 이나즈마 쪽으로 갈 준비를 하려고요. 아직 배도 안 정해졌고 들어갈 수 있는지도 알아봐야 해요. 당분간은 치료소에서 찾으시면 되고, 출항할 수 있게 되면 다시 인사드릴게요. 이번엔 소리 소문 없이 없어지지 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_007","speaker":"장록","text":"갈 곳을 정했군. 여기서 알아낸 게 다 끝났다는 얼굴은 아니지만, 붙잡고 있을 이유만 찾다 보면 평생 짐을 못 내리는 법이오. 내가 줄 만한 대단한 물건은 없소. 대신 배에 가져갈 짐은 한쪽으로 쏠리지 않게 싸시오. 그 어깨로 욕심내지 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_008","options":[{"label":"대단한 물건보다 그 말이 저한테는 더 필요한 것 같네요. 장록 씨도 다음 일 시작하기 전에 쉬세요. 허리 아픈 사람 둘이 서로 걱정하는 모양새가 됐네.","id":"PRO_L04K2_depart_009","items":[{"k":"line","id":"PRO_L04K2_depart_010","speaker":"장록","text":"허리는 내가 선배지. 당신은 다리부터 챙기시오. 다음에 리월 오면 물자 구역에 와서 이름 부르시오. 포대 뒤에서라도 대답할 테니.","map":"MAP_LIYUE_HARBOR"}]},{"label":"이름을 알고 헤어지니까 이상하게 덜 무섭네요. 또 아무 말 없이 사라지는 사람이 될까 봐 그게 제일 싫었거든요.","id":"PRO_L04K2_depart_011","items":[{"k":"line","id":"PRO_L04K2_depart_012","speaker":"장록","text":"이름 적은 종이 잃어버리지 마시오. 그거 하나면 어디서든 찾아올 수 있잖소. 다음에 리월 오면 물자 구역에 와서 이름 부르시오. 포대 뒤에서라도 대답할 테니.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_depart_013","speaker":"","text":"장록은 웃으며 어깨를 한 번 두드리려다 다친 곳을 보고 손을 거두었다. 대신 멀쩡한 쪽 팔을 가볍게 잡았다. 서로가 살아 돌아온 이유는 알지 못했다. 그러나 누가 먼저 찾았는지, 다음에는 어디서 부르면 되는지는 알고 있었다. 그 정도를 가진 채 헤어지는 것도 가능한 일이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_014","speaker":"","text":"각청은 남십자 함대가 이나즈마 방면 항해를 상의할 수 있는 창구를 알려 주었다. 먼저 몬드에도 소식을 남겨 두기로 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_015","options":[{"label":"진한테 편지 보낼게. 리월 위기는 막았고 나는 살아서 치료 중이라고. 황금옥 일하고 기억 공백은 내가 본 범위만 적을게. 범인 알아낸 것처럼은 안 보내.","id":"PRO_L04K2_depart_016","items":[{"k":"line","id":"PRO_L04K2_depart_017","speaker":"각청","text":"길드 전달편에 접수하면 돼. 너 기다리는 사람한테는 먼저 알려 주는 게 좋지. 네가 여기서 사람 못 찾아서 답답했던 거 생각하면.","map":"MAP_LIYUE_HARBOR"}]},{"label":"편지 첫 줄은 살아 있고 치료받고 있다는 말로 할게. 그다음에 실제로 본 일만 적고. 다음 행선지 알아보는 중이라는 걸 벌써 출항한 것처럼 보내지는 않을 거야.","id":"PRO_L04K2_depart_018","items":[{"k":"line","id":"PRO_L04K2_depart_019","speaker":"각청","text":"그렇게 구분해서 적으면 받는 쪽도 네가 어디 있는지 알겠지. 회신 받을 주소도 빠뜨리지 마. 길드 전달편에 접수하면 돼.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_166","text":"길드에서 편지를 작성해 맡겼다. 전하려던 소식과 당분간 연락받을 치료소를 적었고, 전달 담당자가 몬드행으로 접수했다. 이번에는 어디로 갔는지도 모를 사람으로 남지 않도록 내 쪽에서 할 일을 마쳤다."},{"k":"line","id":"PRO_L04K2_depart_020","speaker":"나","text":"네가 나를 처음 못 알아봤을 때 되게 억울했어. 내가 겪은 일을 나만 떠안은 것 같아서. 그런데 그 뒤에 사람도 찾아 줬고 내 말 듣고 움직였잖아. 고마워, 각청.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_021","speaker":"각청","text":"그렇게 말해 주면 나도 듣기 편하지. 그 닷새는 못 돌려줘. 대신 오늘부터 생긴 건 내가 갖고 있을게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_022","speaker":"각청","text":"그러니까 돌아오면 그냥 이름 불러. 그때 내가 \"우리 어디서 만났지?\" 하면 그땐 진짜 화내도 돼.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_023","speaker":"나","text":"그 말 녹음해 두고 싶네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_024","speaker":"각청","text":"뭐?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_025","speaker":"나","text":"아니야. 알았어. 이름 부를게.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_169","text":"내 이름을 다시 소개하지 않았다. 각청이 이미 알고 있는 이름으로 고개를 끄덕였다. 잊힌 인연을 처음부터 되돌릴 수는 없었어도 다음에 만날 사람으로 남을 수는 있었다. 그녀는 도시의 일로 돌아갔고, 나는 항구의 연락 창구로 향했다."},{"k":"line","id":"PRO_L04K2_depart_026","speaker":"나","text":"이나즈마 방면 배편을 상담하고 싶습니다. 각청한테 이쪽으로 문의하라고 소개받았어요. 지금 치료 중이고요. 출항 일정하고 승선 조건을 먼저 듣고, 입국 문제도 어떻게 준비해야 하는지 알고 싶어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_027","speaker":"남십자 선원","text":"뜻은 선장님께 전달하겠습니다. 다만 배에 자리가 있는 것과 이나즈마에 들어갈 수 있는 것은 별개입니다. 일정이 정해지면 어디로 연락드리면 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_028","speaker":"나","text":"항구 치료소요. 연락 오기 전에 무작정 배에 올라가 자리 맡지는 않을게요. 남의 짐처럼 실려 가고 싶지도 않고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_029","speaker":"","text":"접수가 끝난 것을 확인하고 치료소로 돌아왔다. 길에서 군옥각이 있던 하늘을 보았다. 그 빈자리는 도시를 구한 값이 무엇인지 기억하게 했지만, 남아 있는 길과 사람까지 가리지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_030","speaker":"정산 담당자","text":"돌아오셨군요. 리월 방어에 참여하고 위험을 전달한 공적에 대한 정산입니다. 1,800모라, 영웅의 경험 두 개와 모험가의 경험 세 개를 지급합니다. 확인하고 받아 주십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_031","options":[{"label":"확인했습니다. 1,800모라, 영웅의 경험 두 개, 모험가의 경험 세 개. 받겠습니다. 남의 화물 끝나는 걸 보고 왔더니 이제 제 몫 확인할 차례네요.","keep":"ISK_L04_K2_176","items":[{"k":"line","id":"PRO_L04K2_depart_032","speaker":"정산 담당자","text":"수령 기록에 남겼습니다. 인계 끝나는 걸 지켜본 분이니 절차는 익숙하시겠군요.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_177","text":"받은 물품을 치료소의 짐 옆에 정리했다. 장록은 자기 일을 마쳤고, 각청은 도시를 되돌리고 있었으며, 응광과 선인들은 다음 경계를 맡았다. 나도 이곳에 남길 연락처와 떠날 이유를 정했다. 죽음과 기억의 의문은 풀리지 않았다. 그러나 리월에서 해야 했던 일은 사람들을 살아 있는 다음 하루로 돌려놓는 곳까지 왔다. 다음 행선지는 이나즈마였다."},{"k":"keep","id":"ISK_L04_K2_END"}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L04_K2_001_0","text":"손앞의 작은 파편에 손가락을 걸었다. 들보는 건드리지 않았다."},{"k":"text","id":"V141_AFTER_ISK_L04_K2_001_0","text":"파편이 옆으로 굴렀다. 좁은 틈으로 빛이 들고, 흙 묻은 손 하나가 나타났다."},{"k":"text","id":"V141_BEFORE_ISK_L04_K2_091_0","text":"향릉과 행추가 소식을 듣고 물자 구역까지 찾아왔다. 지금 나눌 이야기는 남은 짐의 수량보다, 함께 겪고 돌아온 일이었다."},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_0","text":"자, 이건 기다리지 말고 지금 먹기! 아저씨 것도 있어요!"},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_1","text":"자네가 끝까지 봤다는 그 짐, 내용물이 책이면 한 권 빌려도 되겠나?"},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_2","text":"그건 주인한테 말해. 난 이름 제대로 물어본 것만으로 오늘 할 일 다 했어."}]}]};})(globalThis);
